#undef COLD_BODY_OP_SCHEMA

enum {
    COLD_BODY_OP_SCHEMA_COUNT =
        (int32_t)(sizeof(ColdBodyOpSchemas) / sizeof(ColdBodyOpSchemas[0])),
};

_Static_assert(BODY_OP_NOP == 0, "BodyIR op schema requires zero-based kinds");
_Static_assert(BODY_OP_I32_LSR == 164,
               "BodyIR op schema legacy exhaustive range changed");
_Static_assert(COLD_BODY_OP_SCHEMA_COUNT == BODY_OP_TYPE_SIZE + 1,
               "BodyIR op schema must cover every declared kind");

static const ColdBodyOpSchema *cold_body_op_schema(int32_t kind) {
    if (kind < BODY_OP_NOP || kind >= COLD_BODY_OP_SCHEMA_COUNT)
        die("cold BodyIR op schema unknown kind");
    const ColdBodyOpSchema *schema = &ColdBodyOpSchemas[kind];
    if (schema->kind != kind)
        die("cold BodyIR op schema missing, duplicate, or out of order kind");
    return schema;
}

static void cold_validate_body_op_schema(void) {
    for (int32_t kind = BODY_OP_NOP; kind <= BODY_OP_I32_LSR; kind++)
        (void)cold_body_op_schema(kind);
    for (int32_t kind = BODY_OP_I32_LSR + 1;
         kind < COLD_BODY_OP_SCHEMA_COUNT; kind++)
        (void)cold_body_op_schema(kind);
}

