/* ================================================================
 * Code generation
 * ================================================================ */
typedef struct Code {
    uint32_t *words;
    int32_t count;
    int32_t cap;
    Arena *arena;
    bool linux_syscalls;
    int32_t *global_patch_pos;    /* code word index for each GLOBAL_ADDR */
    int32_t *global_patch_idx;    /* global index for each GLOBAL_ADDR */
    int32_t *global_patch_dst;    /* dst slot for each GLOBAL_ADDR */
    int32_t global_patch_count;
    int32_t global_patch_cap;
    int32_t global_data_size;     /* total size of global variable data area */
    uint8_t *global_data;         /* initialized bytes for direct executable */
    int32_t *global_offsets;      /* per-global byte offset within data area */
    int32_t global_count;         /* number of globals */
    int32_t *local_string_literal_offsets;
    int32_t local_string_literal_count;
    int32_t bump_alloc_pos;       /* word index of shared bump-allocator routine (-1 = raw mmap) */
    /* Heap ops lower to libc calloc/free patch calls instead of inline
       mmap/munmap. Only valid in codegen drivers that resolve FunctionPatch
       entries into relocations (object emission); raw exec writers keep the
       inline mmap path. */
    bool heap_runtime_calls;
    int32_t heap_alloc_shim_pos;  /* word index of calloc shim (-1 = absent) */
    int32_t heap_free_shim_pos;   /* word index of free shim (-1 = absent) */
} Code;

static void code_record_global_patch(Code *code,
                                     int32_t patch_pos,
                                     int32_t global_index,
                                     int32_t dst_slot) {
    int32_t pc = code->global_patch_count;
    if (pc >= code->global_patch_cap) {
        int32_t nc = code->global_patch_cap > 0 ? code->global_patch_cap * 2 : 64;
        int32_t *np = arena_alloc(code->arena, (size_t)nc * 3 * sizeof(int32_t));
        if (code->global_patch_pos) {
            memcpy(np, code->global_patch_pos, (size_t)pc * sizeof(int32_t));
            memcpy(np + nc, code->global_patch_idx, (size_t)pc * sizeof(int32_t));
            memcpy(np + nc * 2, code->global_patch_dst, (size_t)pc * sizeof(int32_t));
        }
        code->global_patch_pos = np;
        code->global_patch_idx = np + nc;
        code->global_patch_dst = np + nc * 2;
        code->global_patch_cap = nc;
    }
    code->global_patch_pos[pc] = patch_pos;
    code->global_patch_idx[pc] = global_index;
    code->global_patch_dst[pc] = dst_slot;
    code->global_patch_count = pc + 1;
}

static int32_t cold_layout_globals(Symbols *symbols, int32_t *offsets) {
    int32_t total = 0;
    if (!symbols) return 0;
    for (int32_t gi = 0; gi < symbols->global_count; gi++) {
        if (offsets) offsets[gi] = total;
        int32_t sz = symbols->globals[gi].size;
        if (sz <= 0) sz = 8;
        total += (sz + 7) & ~7;
    }
    return total;
}

static void cold_fill_global_data(Symbols *symbols, const int32_t *offsets,
                                  uint8_t *data, int32_t data_size) {
    if (!symbols || !data || data_size < 0) return;
    int32_t running_offset = 0;
    for (int32_t gi = 0; gi < symbols->global_count; gi++) {
        GlobalDef *global = &symbols->globals[gi];
        int32_t size = global->size > 0 ? global->size : 8;
        int32_t offset = offsets ? offsets[gi] : running_offset;
        if (global->init_data.len != size)
            die("cold global initializer storage size mismatch");
        if (offset < 0 || offset > data_size || size > data_size - offset)
            die("cold global initializer storage out of bounds");
        memcpy(data + offset, global->init_data.ptr, (size_t)size);
        running_offset += (size + 7) & ~7;
    }
}

static uint8_t *cold_build_global_data(Arena *arena,
                                       Symbols *symbols,
                                       int32_t **out_offsets,
                                       int32_t *out_size) {
    if (out_offsets) *out_offsets = NULL;
    if (out_size) *out_size = 0;
    if (!arena || !symbols || symbols->global_count <= 0) return NULL;
    int32_t *offsets = arena_alloc(arena,
        (size_t)symbols->global_count * sizeof(int32_t));
    int32_t size = cold_layout_globals(symbols, offsets);
    uint8_t *data = size > 0 ? arena_alloc(arena, (size_t)size) : NULL;
    if (data && size > 0) memset(data, 0, (size_t)size);
    if (data && size > 0) cold_fill_global_data(symbols, offsets, data, size);
    if (out_offsets) *out_offsets = offsets;
    if (out_size) *out_size = size;
    return data;
}

static bool cold_macho_write_object_with_globals(const char *out_path,
                                                 Code *shared,
                                                 Symbols *symbols,
                                                 Arena *arena,
                                                 const char **func_names,
                                                 const int32_t *func_offsets,
                                                 int32_t name_count,
                                                 int32_t local_count,
                                                 const int32_t *reloc_offsets,
                                                 const int32_t *reloc_symbols,
                                                 int32_t reloc_count) {
    if (!out_path || !shared || !symbols || !arena ||
        !func_names || !func_offsets || name_count <= 0 ||
        shared->global_patch_count <= 0) {
        return false;
    }
    if (symbols->global_count <= 0)
        die("Mach-O global relocation requires globals");

    shared->global_count = symbols->global_count;
    int32_t global_data_size = 0;
    uint8_t *global_data = cold_build_global_data(arena, symbols,
                                                  &shared->global_offsets,
                                                  &global_data_size);
    shared->global_data_size = global_data_size;

    int32_t global_count = symbols->global_count;
    int32_t td_name_count = name_count + global_count;
    const char **td_names = arena_alloc(arena,
        (size_t)td_name_count * sizeof(const char *));
    uint64_t *td_values = arena_alloc(arena,
        (size_t)td_name_count * sizeof(uint64_t));
    uint8_t *td_sections = arena_alloc(arena,
        (size_t)td_name_count * sizeof(uint8_t));
    for (int32_t ni = 0; ni < name_count; ni++) {
        td_names[ni] = func_names[ni];
        if (func_offsets[ni] >= 0) {
            td_values[ni] = (uint64_t)func_offsets[ni] * 4ULL;
            td_sections[ni] = 1;
        } else {
            td_values[ni] = 0;
            td_sections[ni] = 0;
        }
    }
    int32_t data_addr = macho_align_i32(shared->count * 4, 8);
    for (int32_t gi = 0; gi < global_count; gi++) {
        Span gn = symbols->globals[gi].name;
        if (gn.len <= 0) die("Mach-O global relocation requires named globals");
        char *name_buf = arena_alloc(arena, (size_t)gn.len + 1);
        memcpy(name_buf, gn.ptr, (size_t)gn.len);
        name_buf[gn.len] = '\0';
        td_names[name_count + gi] = name_buf;
        td_values[name_count + gi] = (uint64_t)(data_addr + shared->global_offsets[gi]);
        td_sections[name_count + gi] = 2;
    }

    int32_t td_reloc_count = reloc_count + shared->global_patch_count * 2;
    int32_t *td_reloc_offsets = arena_alloc(arena,
        (size_t)(td_reloc_count > 0 ? td_reloc_count : 1) * sizeof(int32_t));
    int32_t *td_reloc_symbols = arena_alloc(arena,
        (size_t)(td_reloc_count > 0 ? td_reloc_count : 1) * sizeof(int32_t));
    uint8_t *td_reloc_types = arena_alloc(arena,
        (size_t)(td_reloc_count > 0 ? td_reloc_count : 1));
    uint8_t *td_reloc_pcrel = arena_alloc(arena,
        (size_t)(td_reloc_count > 0 ? td_reloc_count : 1));
    int32_t tri = 0;
    for (int32_t ri = 0; ri < reloc_count; ri++) {
        td_reloc_offsets[tri] = reloc_offsets[ri];
        td_reloc_symbols[tri] = reloc_symbols[ri];
        td_reloc_types[tri] = ARM64_RELOC_BRANCH26;
        td_reloc_pcrel[tri] = 1;
        tri++;
    }
    for (int32_t pi = 0; pi < shared->global_patch_count; pi++) {
        int32_t pos = shared->global_patch_pos[pi];
        int32_t gi = shared->global_patch_idx[pi];
        if (pos < 0 || pos + 1 >= shared->count ||
            gi < 0 || gi >= global_count) {
            die("Mach-O global relocation out of range");
        }
        shared->words[pos] = 0x90000000u;      /* adrp x0, symbol@PAGE */
        shared->words[pos + 1] = 0x91000000u;  /* add  x0, x0, symbol@PAGEOFF */
        int32_t sym_index = name_count + gi;
        td_reloc_offsets[tri] = pos * 4;
        td_reloc_symbols[tri] = sym_index;
        td_reloc_types[tri] = ARM64_RELOC_PAGE21;
        td_reloc_pcrel[tri] = 1;
        tri++;
        td_reloc_offsets[tri] = (pos + 1) * 4;
        td_reloc_symbols[tri] = sym_index;
        td_reloc_types[tri] = ARM64_RELOC_PAGEOFF12;
        td_reloc_pcrel[tri] = 0;
        tri++;
    }

    return macho_write_text_data_object(out_path,
                                        shared->words,
                                        shared->count,
                                        global_data,
                                        global_data_size,
                                        td_names,
                                        td_values,
                                        td_sections,
                                        td_name_count,
                                        local_count,
                                        td_reloc_offsets,
                                        td_reloc_symbols,
                                        td_reloc_types,
                                        td_reloc_pcrel,
                                        td_reloc_count);
}

typedef struct Patch {
    int32_t pos;
    int32_t target_block;
    int32_t kind;
} Patch;

typedef struct PatchList {
    Patch *items;
    int32_t count;
    int32_t cap;
    Arena *arena;
} PatchList;

typedef struct FunctionPatch {
    int32_t pos;
    int32_t target_function;
    int32_t kind;
} FunctionPatch;

enum {
    FUNCTION_PATCH_CALL = 1,
    FUNCTION_PATCH_ADDR = 2
};

typedef struct FunctionPatchList {
    FunctionPatch *items;
    int32_t count;
    int32_t cap;
    Arena *arena;
} FunctionPatchList;

static void code_emit(Code *code, uint32_t word);
static void codegen_func(Code *code, BodyIR *body, Symbols *symbols,
                         FunctionPatchList *function_patches);
static void cold_optimize_body(BodyIR *body, Symbols *symbols, bool enable_licm);
static void cold_forward_var_ref_alias_args(BodyIR *body, Symbols *symbols);
static int32_t cold_source_line_at(Span source, int32_t pos);
static bool cold_write_direct_macho_line_map_from_bodies(const char *out_path,
                                                         const char *source_path,
                                                         Symbols *symbols,
                                                         BodyIR **function_bodies,
                                                         const int32_t *function_offsets,
                                                         int32_t function_count);
static uint8_t *cold_emit_dwarf_debug_line(const char *source_path,
                                            const char **func_names,
                                            const int32_t *func_offsets,
                                            const int32_t *func_word_counts,
                                            const int32_t *func_source_lines,
                                            int32_t func_count,
                                            int32_t code_words,
                                            int32_t *out_size);

#define COLD_WSDEQUE_CAP 256
typedef struct ColdWSDeque {
    int32_t tasks[COLD_WSDEQUE_CAP];
    int32_t top;
    int32_t bottom;
} ColdWSDeque;

static bool cold_wsdeque_push(ColdWSDeque *q, int32_t task) {
    int32_t t = q->top;
    if (t >= COLD_WSDEQUE_CAP) return false;
    q->tasks[t] = task;
    __atomic_store_n(&q->top, t + 1, __ATOMIC_RELEASE);
    return true;
}

static bool cold_wsdeque_pop(ColdWSDeque *q, int32_t *task) {
    int32_t t = __atomic_load_n(&q->top, __ATOMIC_ACQUIRE);
    if (t <= 0) return false;
    int32_t new_t = t - 1;
    __atomic_store_n(&q->top, new_t, __ATOMIC_RELEASE);
    int32_t b = __atomic_load_n(&q->bottom, __ATOMIC_ACQUIRE);
    if (new_t >= b) {
        *task = q->tasks[new_t];
        return true;
    }
    __atomic_store_n(&q->top, b, __ATOMIC_RELEASE);
    return false;
}

static bool cold_wsdeque_steal(ColdWSDeque *q, int32_t *task) {
    int32_t b = __atomic_load_n(&q->bottom, __ATOMIC_ACQUIRE);
    __atomic_thread_fence(__ATOMIC_SEQ_CST);
    int32_t t = __atomic_load_n(&q->top, __ATOMIC_ACQUIRE);
    if (b >= t) return false;
    *task = q->tasks[b];
    int32_t expected = b;
    if (!__atomic_compare_exchange_n(&q->bottom, &expected, b + 1,
                                     0, __ATOMIC_RELEASE, __ATOMIC_RELAXED)) {
        return false;
    }
    return true;
}


/* ---- parallel codegen worker (lock-free work-stealing) ---- */

typedef struct CodegenWorker {
    ColdWSDeque *deque;          /* per-worker work-stealing deque */
    ColdWSDeque *all_deques;     /* base of all workers' deques (array) */
    int32_t worker_index;        /* index of this worker (0..active-1) */
    int32_t active_workers;      /* total active workers */
    int32_t entry_function;
    int32_t function_count;
    BodyIR **function_bodies;
    bool *reachable_functions;
    Symbols *symbols;
    Code *local_code;
    FunctionPatchList local_patches;
    int32_t *local_function_pos;
    int32_t *local_function_end;
} CodegenWorker;

/* Lock-free Work-Stealing Deque (Chase-Lev style).
   Owner pushes/pops from top; thieves steal from bottom.
   All synchronisation via __atomic builtins. */
static void *codegen_worker_run(void *arg) {
    CodegenWorker *w = (CodegenWorker *)arg;
    for (;;) {
        int32_t i = -1;
        /* 1. Try to pop from own deque */
        if (!cold_wsdeque_pop(w->deque, &i)) {
            /* 2. Steal from a random victim */
            bool stolen = false;
            for (int32_t attempt = 0; attempt < w->active_workers * 2; attempt++) {
                int32_t victim = (w->worker_index + 1 + attempt) % w->active_workers;
                if (cold_wsdeque_steal(&w->all_deques[victim], &i)) {
                    stolen = true;
                    break;
                }
            }
            if (!stolen) break;  /* all queues empty */
        }
        if (i < 0 || i >= w->function_count) continue;
        if (i == w->entry_function || !w->reachable_functions[i] ||
            !w->function_bodies[i] ||
            w->function_bodies[i]->has_fallback) continue;
        w->local_function_pos[i] = w->local_code->count;
        BodyIR *body = w->function_bodies[i];
        if (body->has_fallback || body->block_count == 0 ||
            (body->block_count > 0 && body->block_term[0] < 0)) {
            die("cold worker function body is not codegen-ready");
        }
        codegen_func(w->local_code, body, w->symbols, &w->local_patches);
        w->local_function_end[i] = w->local_code->count;
    }
    return NULL;
}

/* Forward declaration for import worker */
static void cold_compile_import_function_direct(Symbols *symbols,
    ColdImportSource *imports, int32_t import_count,
    ColdFunctionBodyStore *body_store, int32_t target_fn);

/* Import worker context and runner: lock-free parallel import body compilation
   using per-thread jmp_buf for error recovery. */
typedef struct {
    ColdWSDeque *dq; ColdWSDeque *all; int32_t idx; int32_t njobs;
    Symbols *sym; ColdImportSource *imps; int32_t icount;
    ColdFunctionBodyStore *body_store;
} ImportWorkerCtx;

static void *cold_import_worker_run(void *arg) {
    ImportWorkerCtx *ctx = (ImportWorkerCtx *)arg;
    pthread_once(&ColdWorkerJmpKeyOnce, cold_worker_jmp_key_init);
    ColdWorkerJmpData *wj = (ColdWorkerJmpData *)pthread_getspecific(ColdWorkerJmpKey);
    if (!wj) {
        wj = (ColdWorkerJmpData *)calloc(1, sizeof(ColdWorkerJmpData));
        pthread_setspecific(ColdWorkerJmpKey, wj);
    }
    for (;;) {
        int32_t fn_index = -1;
        if (!cold_wsdeque_pop(ctx->dq, &fn_index)) {
            bool stolen = false;
            for (int32_t attempt = 0; attempt < ctx->njobs * 2; attempt++) {
                int32_t victim = (ctx->idx + 1 + attempt) % ctx->njobs;
                if (cold_wsdeque_steal(&ctx->all[victim], &fn_index)) {
                    stolen = true; break;
                }
            }
            if (!stolen) break;
        }
        if (fn_index < 0 || fn_index >= ctx->sym->function_count) continue;
        if (cold_function_body_store_get(ctx->body_store, fn_index)) continue;
        wj->enabled = false;
        if (wj->depth < COLD_JMP_STACK_MAX) wj->depth++;
        if (setjmp(wj->stack[wj->depth - 1]) == 0) {
            wj->enabled = true;
            cold_compile_import_function_direct(ctx->sym, ctx->imps, ctx->icount,
                                                ctx->body_store, fn_index);
        }
        if (wj->depth > 0) wj->depth--;
        wj->enabled = false;
    }
    return NULL;
}

static int32_t cold_jobs_from_env(void) {
    const char *env = getenv("BACKEND_JOBS");
    if (!env || !env[0]) return 1;
    int32_t n = 0;
    for (const char *p = env; *p; p++) {
        if (*p >= '0' && *p <= '9') n = n * 10 + (*p - '0');
        else return 1;
    }
    if (n < 1) return 1;
    if (n > 16) n = 16;
    return n;
}

/* ---- end parallel codegen ---- */

static Code *code_new(Arena *arena, int32_t cap) {
    Code *code = arena_alloc(arena, sizeof(Code));
    code->words = arena_alloc(arena, (size_t)cap * sizeof(uint32_t));
    code->cap = cap;
    code->arena = arena;
    code->linux_syscalls = false;
    code->bump_alloc_pos = -1;
    code->heap_runtime_calls = false;
    code->heap_alloc_shim_pos = -1;
    code->heap_free_shim_pos = -1;
    return code;
}

/* Apple arm64 packs stack arguments at natural size/alignment (bool -> 1 byte,
   i32 -> 4 bytes); standard AAPCS64 (linux/android/ohos) and rv64 round each
   slot up to 8 bytes.  The flag defaults to the build host ABI and is only
   ever rewritten from an explicit, host-defaulted target string, so signature
   collection and codegen always agree within one process. */
#if defined(__APPLE__)
static bool cold_abi_darwin_arg_packing = true;
#else
static bool cold_abi_darwin_arg_packing = false;
#endif

/* Android objects always link against bionic via the NDK (cold self-link
   cannot emit reloc 311), so stdio handles must come from libc instead of
   the self-contained fd-as-pointer model. */
static bool cold_target_external_libc = false;

/* Argument packing must be fixed per target for the WHOLE invocation: BodyIR
   parameter layout runs at parse time, caller staging at codegen time. A late
   flip (code_configure_target) leaves the two phases with different stack-arg
   ABIs and corrupts cross-object calls. Configure as soon as the command-level
   target is resolved. */
static void cold_configure_abi_for_target(const char *target) {
    cold_abi_darwin_arg_packing =
        !target || strstr(target, "apple-darwin") != NULL;
    cold_target_external_libc = target && strstr(target, "android") != NULL;
}

static void code_configure_target(Code *code, const char *target) {
    if (!code) return;
    if (!target || target[0] == '\0') target = cold_host_default_target();
    code->linux_syscalls = strstr(target, "linux") && strstr(target, "aarch64");
    cold_abi_darwin_arg_packing = strstr(target, "apple-darwin") != NULL;
    cold_target_external_libc = strstr(target, "android") != NULL;
}

static void code_emit(Code *code, uint32_t word) {
    if (code->count >= code->cap) {
        int32_t next = code->cap * 2;
        uint32_t *fresh = arena_alloc(code->arena, (size_t)next * sizeof(uint32_t));
        memcpy(fresh, code->words, (size_t)code->count * sizeof(uint32_t));
        code->words = fresh;
        code->cap = next;
    }
    code->words[code->count++] = word;
}

static void code_ensure_word_cap(Code *code, int32_t need) {
    if (!code || need <= code->cap) return;
    int32_t next = code->cap > 0 ? code->cap : 1;
    while (next < need) next *= 2;
    uint32_t *fresh = arena_alloc(code->arena, (size_t)next * sizeof(uint32_t));
    memcpy(fresh, code->words, (size_t)code->count * sizeof(uint32_t));
    code->words = fresh;
    code->cap = next;
}

static void a64_patch_b(Code *code, int32_t pos, int32_t target) {
    int32_t delta = target - pos;
    code->words[pos] = (code->words[pos] & 0xFC000000u) | ((uint32_t)delta & 0x03FFFFFFu);
}

/* b.cond/cbz/cbnz share the same imm19 field: a 19-bit SIGNED word offset,
   so the representable range is [-2^18, 2^18-1] = [-262144, 262143] words
   (+-1MiB in bytes). The prior threshold here (524287 = 2^19-1) used the
   unsigned-field width instead of the signed range -- any delta in
   [262144, 524287] passed this check yet still had its sign bit (bit 18)
   silently set by the `& 0x7FFFFu` mask below, encoding a large NEGATIVE
   offset instead of the intended forward jump (a latent miscompile,
   never observed only because real deltas so far landed on one side or
   the other of that gap). Fixed as a prerequisite to relaxation. */
static void a64_patch_bcond(Code *code, int32_t pos, int32_t target) {
    int32_t delta = target - pos;
    if (delta >= -262144 && delta <= 262143) {
        code->words[pos] = (code->words[pos] & 0xFF00001Fu) | (((uint32_t)delta & 0x7FFFFu) << 5);
        return;
    }
    /* Long-range escape. This backend is single-pass/deferred-backpatch
       throughout (see docs/singlepass_backpatch_plan.md for the pure-Cheng
       analogue): once a word is emitted, nothing after it can move, so a
       veneer cannot be inserted at patch time. Every b.cond/cbz/cbnz
       placeholder emitted with offset 0 is therefore immediately followed
       (at emission time, see the `a64_nop()` calls next to each
       `a64_bcond(0, ...)`/`a64_cbz(...)` site) by one reserved NOP word --
       dead when the branch is in range, and rewritten in place here into
       an unconditional `b` (imm26, +-128MiB) veneer when it is not.
       word[pos]  <- b.<inverted-cond> +2   (skip the veneer if cond false)
       word[pos+1]<- b target               (the reserved slot, full range) */
    int32_t veneer = pos + 1;
    int32_t b_delta = target - veneer;
    if (b_delta < -33554432 || b_delta > 33554431) {
        fprintf(stderr, "cheng_cold: b veneer offset overflow (delta=%d, max=33554431 words)\n", b_delta);
        abort();
    }
    uint32_t cond = code->words[pos] & 0xFu;
    code->words[pos] = 0x54000000u | ((uint32_t)(2 & 0x7FFFFu) << 5) | ((cond ^ 1u) & 0xFu);
    code->words[veneer] = 0x14000000u | ((uint32_t)b_delta & 0x03FFFFFFu);
}

/* Same long-range escape as a64_patch_bcond, adapted for cbz/cbnz (rt in
   bits[4:0], zero/nonzero sense in bit 24 instead of a 4-bit cond field).
   Shares the reserved-NOP-at-emission-time convention. */
static void a64_patch_cbz(Code *code, int32_t pos, int32_t target) {
    int32_t delta = target - pos;
    if (delta >= -262144 && delta <= 262143) {
        code->words[pos] = (code->words[pos] & 0xFF00001Fu) | (((uint32_t)delta & 0x7FFFFu) << 5);
        return;
    }
    int32_t veneer = pos + 1;
    int32_t b_delta = target - veneer;
    if (b_delta < -33554432 || b_delta > 33554431) {
        fprintf(stderr, "cheng_cold: cbz/cbnz veneer offset overflow (delta=%d, max=33554431 words)\n", b_delta);
        abort();
    }
    uint32_t ins = code->words[pos];
    uint32_t rt = ins & 0x1Fu;
    uint32_t inv_opcode = (ins & 0xFF000000u) ^ 0x01000000u; /* cbz<->cbnz */
    code->words[pos] = inv_opcode | ((uint32_t)(2 & 0x7FFFFu) << 5) | rt;
    code->words[veneer] = 0x14000000u | ((uint32_t)b_delta & 0x03FFFFFFu);
}

static int32_t code_append_bytes(Code *code, const char *bytes, int32_t len) {
    int32_t start_bytes = code->count * 4;
    int32_t pos = 0;
    while (pos < len) {
        uint32_t word = 0;
        for (int32_t b = 0; b < 4 && pos < len; b++, pos++) {
            word |= ((uint32_t)(uint8_t)bytes[pos]) << (uint32_t)(b * 8);
        }
        code_emit(code, word);
    }
    return start_bytes;
}

static void patches_add(PatchList *patches, int32_t pos, int32_t target_block, int32_t kind) {
    if (patches->count >= patches->cap) {
        int32_t next = patches->cap ? patches->cap * 2 : 32;
        Patch *fresh = arena_alloc(patches->arena, (size_t)next * sizeof(Patch));
        if (patches->items) memcpy(fresh, patches->items, (size_t)patches->count * sizeof(Patch));
        patches->items = fresh;
        patches->cap = next;
    }
    patches->items[patches->count++] = (Patch){pos, target_block, kind};
}

static void function_patches_add_kind(FunctionPatchList *patches, int32_t pos,
                                      int32_t target_function, int32_t kind) {
    if (patches->count >= patches->cap) {
        int32_t next = patches->cap ? patches->cap * 2 : 32;
        FunctionPatch *fresh = arena_alloc(patches->arena, (size_t)next * sizeof(FunctionPatch));
        if (patches->items) memcpy(fresh, patches->items, (size_t)patches->count * sizeof(FunctionPatch));
        patches->items = fresh;
        patches->cap = next;
    }
    patches->items[patches->count++] = (FunctionPatch){pos, target_function, kind};
}

static void function_patches_add(FunctionPatchList *patches, int32_t pos, int32_t target_function) {
    function_patches_add_kind(patches, pos, target_function, FUNCTION_PATCH_CALL);
}

static void function_patches_add_addr(FunctionPatchList *patches, int32_t pos, int32_t target_function) {
    function_patches_add_kind(patches, pos, target_function, FUNCTION_PATCH_ADDR);
}

/* ---- large immediate / large offset helpers ---- */

static uint32_t a64_add_imm_shifted(int rd, int rn, uint16_t imm12, bool x64) {
    return (x64 ? 0x91000000u : 0x11000000u) | ((uint32_t)rd) | ((uint32_t)rn << 5)
           | ((uint32_t)(imm12 & 0xFFF) << 10) | (1u << 22);
}

static uint32_t a64_sub_imm_shifted(int rd, int rn, uint16_t imm12, bool x64) {
    return (x64 ? 0xD1000000u : 0x51000000u) | ((uint32_t)rd) | ((uint32_t)rn << 5)
           | ((uint32_t)(imm12 & 0xFFF) << 10) | (1u << 22);
}

/* Emit SUB with potentially large 64-bit immediate (two instructions if needed). */
static void a64_emit_sub_large(Code *code, int rd, int rn, int32_t value, bool x64) {
    if (value <= 0xFFF) {
        code_emit(code, a64_sub_imm(rd, rn, (uint16_t)value, x64));
        return;
    }
    if (value % 0x1000 == 0 && value / 0x1000 <= 0xFFF) {
        code_emit(code, a64_sub_imm_shifted(rd, rn, (uint16_t)(value / 0x1000), x64));
        return;
    }
    int32_t hi = (value >> 12) << 12;
    int32_t lo = value - hi;
    if (hi > 0)
        code_emit(code, a64_sub_imm_shifted(rd, rn, (uint16_t)(hi / 0x1000), x64));
    if (lo > 0)
        code_emit(code, a64_sub_imm(rd, rd, (uint16_t)lo, x64));
}

/* Emit ADD with potentially large 64-bit immediate. */
static void a64_emit_add_large(Code *code, int rd, int rn, int32_t value, bool x64) {
    if (value <= 0xFFF) {
        code_emit(code, a64_add_imm(rd, rn, (uint16_t)value, x64));
        return;
    }
    if (value % 0x1000 == 0 && value / 0x1000 <= 0xFFF) {
        code_emit(code, a64_add_imm_shifted(rd, rn, (uint16_t)(value / 0x1000), x64));
        return;
    }
    int32_t hi = (value >> 12) << 12;
    int32_t lo = value - hi;
    if (hi > 0)
        code_emit(code, a64_add_imm_shifted(rd, rn, (uint16_t)(hi / 0x1000), x64));
    if (lo > 0)
        code_emit(code, a64_add_imm(rd, rd, (uint16_t)lo, x64));
}

/* Emit movz/movk sequence to load an arbitrary 64-bit value into rd. */
__attribute__((unused))
static void a64_emit_mov_large(Code *code, int rd, uint64_t value) {
    int sft = 0;
    bool first = true;
    while (value > 0) {
        uint16_t chunk = (uint16_t)(value & 0xFFFF);
        if (first) {
            code_emit(code, a64_movz_x(rd, chunk, sft));
            first = false;
        } else {
            code_emit(code, a64_movk_x(rd, chunk, sft));
        }
        value >>= 16;
        sft++;
    }
    if (first) code_emit(code, a64_movz_x(rd, 0, 0));
}

/* Load from SP with potentially large unsigned offset.
   For offsets within scaled 12-bit range (and properly aligned), use
   immediate encoding.  Otherwise compute address in scratch register
   via a64_emit_add_large (ADD immediate which supports SP), then load. */
static void a64_emit_ldr_sp_off(Code *code, int rt, int32_t offset, bool x64) {
    int32_t max_off = x64 ? 32760 : 16380;
    int32_t align  = x64 ? 7 : 3;
    if (offset >= 0 && offset <= max_off && (offset & align) == 0) {
        code_emit(code, a64_ldr_imm(rt, SP, offset, x64));
    } else {
        int scratch = rt == 16 ? 10 : 16;
        a64_emit_add_large(code, scratch, SP, offset, true);
        code_emit(code, a64_ldr_imm(rt, scratch, 0, x64));
    }
}

/* Store to SP with potentially large unsigned offset. */
static void a64_emit_str_sp_off(Code *code, int rt, int32_t offset, bool x64) {
    int32_t max_off = x64 ? 32760 : 16380;
    int32_t align  = x64 ? 7 : 3;
    if (offset >= 0 && offset <= max_off && (offset & align) == 0) {
        code_emit(code, a64_str_imm(rt, SP, offset, x64));
    } else {
        int scratch = rt == 16 ? 10 : 16;
        a64_emit_add_large(code, scratch, SP, offset, true);
        code_emit(code, a64_str_imm(rt, scratch, 0, x64));
    }
}

/* Load from any base register with potentially large unsigned offset.
   Falls back to scratch register + add_large when offset exceeds imm12. */
static void a64_emit_ldr_off(Code *code, int rt, int rn, int32_t offset, bool x64) {
    int32_t max_off = x64 ? 32760 : 16380;
    int32_t align  = x64 ? 7 : 3;
    if (offset >= 0 && offset <= max_off && (offset & align) == 0) {
        code_emit(code, a64_ldr_imm(rt, rn, offset, x64));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_ldr_imm(rt, scratch, 0, x64));
    }
}

/* Store to any base register with potentially large unsigned offset. */
static void a64_emit_str_off(Code *code, int rt, int rn, int32_t offset, bool x64) {
    int32_t max_off = x64 ? 32760 : 16380;
    int32_t align  = x64 ? 7 : 3;
    if (offset >= 0 && offset <= max_off && (offset & align) == 0) {
        code_emit(code, a64_str_imm(rt, rn, offset, x64));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_str_imm(rt, scratch, 0, x64));
    }
}

/* Byte load from SP with potentially large offset. */
__attribute__((unused))
static void a64_emit_ldrb_sp_off(Code *code, int rt, int32_t offset) {
    if (offset >= 0 && offset <= 4095) {
        code_emit(code, a64_ldrb_imm(rt, SP, offset));
    } else {
        int scratch = rt == 16 ? 10 : 16;
        a64_emit_add_large(code, scratch, SP, offset, true);
        code_emit(code, a64_ldrb_imm(rt, scratch, 0));
    }
}

/* Byte store to SP with potentially large offset. */
static void a64_emit_strb_sp_off(Code *code, int rt, int32_t offset) {
    if (offset >= 0 && offset <= 4095) {
        code_emit(code, a64_strb_imm(rt, SP, offset));
    } else {
        int scratch = rt == 16 ? 10 : 16;
        a64_emit_add_large(code, scratch, SP, offset, true);
        code_emit(code, a64_strb_imm(rt, scratch, 0));
    }
}

static void a64_emit_ldrb_off(Code *code, int rt, int rn, int32_t offset) {
    if (offset >= 0 && offset <= 4095) {
        code_emit(code, a64_ldrb_imm(rt, rn, offset));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_ldrb_imm(rt, scratch, 0));
    }
}

static void a64_emit_strb_off(Code *code, int rt, int rn, int32_t offset) {
    if (offset >= 0 && offset <= 4095) {
        code_emit(code, a64_strb_imm(rt, rn, offset));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_strb_imm(rt, scratch, 0));
    }
}

static void a64_emit_ldrh_off(Code *code, int rt, int rn, int32_t offset) {
    if (offset >= 0 && offset <= 8190 && (offset & 1) == 0) {
        code_emit(code, a64_ldrh_imm(rt, rn, offset));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_ldrh_imm(rt, scratch, 0));
    }
}

static void a64_emit_strh_off(Code *code, int rt, int rn, int32_t offset) {
    if (offset >= 0 && offset <= 8190 && (offset & 1) == 0) {
        code_emit(code, a64_strh_imm(rt, rn, offset));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_strh_imm(rt, scratch, 0));
    }
}

static void a64_emit_ldrsb_off(Code *code, int rt, int rn, int32_t offset) {
    if (offset >= 0 && offset <= 4095) {
        code_emit(code, a64_ldrsb_imm(rt, rn, offset));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_ldrsb_imm(rt, scratch, 0));
    }
}

static void a64_emit_ldrsh_off(Code *code, int rt, int rn, int32_t offset) {
    if (offset >= 0 && offset <= 8190 && (offset & 1) == 0) {
        code_emit(code, a64_ldrsh_imm(rt, rn, offset));
    } else {
        int scratch = (rt == rn || rt == 16) ? 10 : 16;
        a64_emit_add_large(code, scratch, rn, offset, true);
        code_emit(code, a64_ldrsh_imm(rt, scratch, 0));
    }
}

static void a64_emit_ldr_width_off(Code *code, int rt, int rn, int32_t offset, int32_t width) {
    if (width == 1) {
        a64_emit_ldrb_off(code, rt, rn, offset);
    } else if (width == 2) {
        a64_emit_ldrh_off(code, rt, rn, offset);
    } else if (width == 4) {
        a64_emit_ldr_off(code, rt, rn, offset, false);
    } else if (width == 8) {
        a64_emit_ldr_off(code, rt, rn, offset, true);
    } else {
        die("unsupported AArch64 payload load width");
    }
}

/* #133 v3: same width dispatch as a64_emit_ldr_width_off, but a narrow
   (1/2-byte) load additionally sign-extends via LDRSB/LDRSH when
   `is_signed` is set -- used by codegen_copy_slot_from_offset's constant-
   index fixed-array element read so int8[N]/int16[N] negative elements
   round-trip correctly instead of LDRB/LDRH's zero-extend. Width 4/8 (or
   is_signed==false) behave exactly as before. */
static void a64_emit_ldr_width_off_maybe_signed(Code *code, int rt, int rn,
                                                 int32_t offset, int32_t width,
                                                 bool is_signed) {
    if (is_signed && width == 1) { a64_emit_ldrsb_off(code, rt, rn, offset); return; }
    if (is_signed && width == 2) { a64_emit_ldrsh_off(code, rt, rn, offset); return; }
    a64_emit_ldr_width_off(code, rt, rn, offset, width);
}

static void a64_emit_str_width_off(Code *code, int rt, int rn, int32_t offset, int32_t width) {
    if (width == 1) {
        a64_emit_strb_off(code, rt, rn, offset);
    } else if (width == 2) {
        a64_emit_strh_off(code, rt, rn, offset);
    } else if (width == 4) {
        a64_emit_str_off(code, rt, rn, offset, false);
    } else if (width == 8) {
        a64_emit_str_off(code, rt, rn, offset, true);
    } else {
        die("unsupported AArch64 payload store width");
    }
}

static void emit_epilogue(Code *code, int32_t frame_size) {
    if (frame_size > 0) a64_emit_add_large(code, SP, SP, frame_size, true);
    code_emit(code, a64_ldp_post(FP, LR, SP, 16));
    code_emit(code, a64_ldp_post(19, 20, SP, 16));
    code_emit(code, a64_ret());
}

static bool cold_a64_return_uses_indirect(int32_t kind) {
    return kind != SLOT_I32 && kind != SLOT_I64 &&
           kind != SLOT_PTR && kind != SLOT_OPAQUE;
}

#ifdef COLD_BACKEND_ONLY
static int32_t cold_arg_reg_count(int32_t kind, int32_t size) {
    if (kind == SLOT_I32 || kind == SLOT_I64 || kind == SLOT_I32_REF || kind == SLOT_I64_REF) return 1;
    if (kind == SLOT_F32 || kind == SLOT_F64) return 1;
    if (kind == SLOT_PTR) return 1;
    if (kind == SLOT_STR) return 2;
    if (kind == SLOT_VARIANT) return size > 16 ? 1 : 2;
    if (kind == SLOT_OBJECT || kind == SLOT_ARRAY_I32) return size > 16 ? 1 : 2;
    if (kind == SLOT_SEQ_I32) return 2;
    if (kind == SLOT_SEQ_STR) return 2;
    if (kind == SLOT_SEQ_OPAQUE) return 2;
    if (kind == SLOT_I32_REF ||
        kind == SLOT_SEQ_I32_REF || kind == SLOT_OBJECT_REF ||
        kind == SLOT_STR_REF || kind == SLOT_SEQ_STR_REF ||
        kind == SLOT_SEQ_OPAQUE_REF ||
        kind == SLOT_OPAQUE || kind == SLOT_OPAQUE_REF) return 1;
    die("unsupported cold call ABI kind");
    return 1;
}
#endif /* COLD_BACKEND_ONLY */

static int32_t cold_abi_arg_storage_bytes(int32_t kind, int32_t size) {
    if (cold_abi_darwin_arg_packing) {
        /* bool params carry a 1-byte ABI size from signature collection. */
        if (kind == SLOT_I32 && size == 1) return 1;
        if (kind == SLOT_I32 || kind == SLOT_F32) return 4;
    }
    return cold_arg_reg_count(kind, size) * 8;
}

static bool cold_abi_place_arg(int32_t *reg_cursor, int32_t *stack_cursor,
                               int32_t kind, int32_t size,
                               int32_t *base_reg, int32_t *stack_offset) {
    int32_t reg_count = cold_arg_reg_count(kind, size);
    if (*reg_cursor + reg_count <= 8) {
        *base_reg = *reg_cursor;
        *stack_offset = -1;
        *reg_cursor += reg_count;
        return true;
    }
    int32_t bytes = cold_abi_arg_storage_bytes(kind, size);
    /* Stack slots align to the value's natural alignment (1/4/8). */
    int32_t align = bytes >= 8 ? 8 : bytes;
    *stack_cursor = align_i32(*stack_cursor, align);
    *base_reg = -1;
    *stack_offset = *stack_cursor;
    *stack_cursor += bytes;
    *reg_cursor = 8;
    return false;
}

static int32_t cold_outgoing_stack_bytes(FnDef *fn) {
    int32_t reg = 0;
    int32_t stack = 0;
    for (int32_t i = 0; i < fn->arity; i++) {
        int32_t base_reg = -1;
        int32_t stack_offset = -1;
        (void)cold_abi_place_arg(&reg, &stack, fn->param_kind[i],
                                 fn->param_size[i], &base_reg, &stack_offset);
    }
    return align_i32(stack, 16);
}

static bool cold_call_value_composite_kind(int32_t kind) {
    return kind == SLOT_VARIANT ||
           kind == SLOT_OBJECT ||
           kind == SLOT_ARRAY_I32 ||
           kind == SLOT_SEQ_I32 ||
           kind == SLOT_SEQ_STR ||
           kind == SLOT_SEQ_OPAQUE;
}

static int32_t cold_effective_call_param_kind(BodyIR *body, FnDef *fn,
                                              int32_t arg_start,
                                              int32_t index) {
    int32_t kind = fn->param_kind[index];
    int32_t arg_index = arg_start + index;
    if (kind != SLOT_OPAQUE || !body ||
        arg_index < 0 || arg_index >= body->call_arg_count) {
        return kind;
    }
    int32_t arg_slot = body->call_arg_slot[arg_index];
    if (arg_slot < 0 || arg_slot >= body->slot_count) return kind;
    int32_t arg_kind = body->slot_kind[arg_slot];
    return cold_call_value_composite_kind(arg_kind) ? arg_kind : kind;
}

static int32_t cold_effective_call_param_size(BodyIR *body, FnDef *fn,
                                              int32_t arg_start,
                                              int32_t index) {
    int32_t size = fn->param_size[index] > 0 ? fn->param_size[index] : 0;
    int32_t param_kind = cold_effective_call_param_kind(body, fn, arg_start, index);
    int32_t arg_index = arg_start + index;
    if (body && arg_index >= 0 && arg_index < body->call_arg_count) {
        int32_t arg_slot = body->call_arg_slot[arg_index];
        if (arg_slot >= 0 && arg_slot < body->slot_count) {
            int32_t actual_size = body->slot_size[arg_slot];
            if (size <= 0 ||
                (cold_call_value_composite_kind(param_kind) &&
                 actual_size > size)) {
                size = actual_size;
            }
        }
    }
    return size;
}

static int32_t cold_outgoing_stack_bytes_for_call(BodyIR *body, FnDef *fn,
                                                  int32_t arg_start) {
    int32_t reg = 0;
    int32_t stack = 0;
    for (int32_t i = 0; i < fn->arity; i++) {
        int32_t base_reg = -1;
        int32_t stack_offset = -1;
        int32_t param_kind = cold_effective_call_param_kind(body, fn, arg_start, i);
        int32_t param_size = cold_effective_call_param_size(body, fn, arg_start, i);
        (void)cold_abi_place_arg(&reg, &stack, param_kind,
                                 param_size, &base_reg, &stack_offset);
    }
    return align_i32(stack, 16);
}

static void codegen_store_params(Code *code, BodyIR *body) {
    int32_t reg = 0;
    int32_t stack = 0;
    for (int32_t i = 0; i < body->param_count; i++) {
        int32_t slot = body->param_slot[i];
        int32_t kind = body->slot_kind[slot];
        int32_t size = body->slot_size[slot];
        int32_t base_reg = -1;
        int32_t stack_offset = -1;
        bool in_regs = cold_abi_place_arg(&reg, &stack, kind, size,
                                          &base_reg, &stack_offset);
        int32_t incoming_stack_offset = 32 + stack_offset;
        if (kind == SLOT_I32) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], false);
            } else if (cold_abi_arg_storage_bytes(kind, size) == 1) {
                /* Darwin packed bool stack slot: byte load zero-extends to
                   the canonical 0/1 register form. */
                a64_emit_ldrb_off(code, R9, FP, incoming_stack_offset);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], false);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, false);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], false);
            }
        } else if (kind == SLOT_F32) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], false);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, false);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], false);
            }
        } else if (kind == SLOT_I64 || kind == SLOT_F64 || kind == SLOT_PTR) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], true);
            }
        } else if (kind == SLOT_STR) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
                a64_emit_str_sp_off(code, base_reg + 1, body->slot_offset[slot] + 8, true);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], true);
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset + 8, true);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot] + 8, true);
            }
            code_emit(code, a64_movz(R9, 0, 0));
            a64_emit_str_sp_off(code, R9, body->slot_offset[slot] + COLD_STR_FLAGS_OFFSET, true);
        } else if (kind == SLOT_I32_REF || kind == SLOT_I64_REF) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], true);
            }
        } else if (kind == SLOT_STR_REF) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], true);
            }
        } else if (kind == SLOT_VARIANT) {
            if (size > 16) {
                int32_t src_reg = in_regs ? base_reg : R9;
                if (!in_regs) a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                for (int32_t off = 0; off < size; off += 8) {
                    a64_emit_ldr_off(code, R10, src_reg, off, true);
                    a64_emit_str_sp_off(code, R10, body->slot_offset[slot] + off, true);
                }
            } else {
                if (in_regs) {
                    a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
                    a64_emit_str_sp_off(code, base_reg + 1, body->slot_offset[slot] + 8, true);
                } else {
                    for (int32_t off = 0; off < size; off += 8) {
                        a64_emit_ldr_off(code, R9, FP, incoming_stack_offset + off, true);
                        a64_emit_str_sp_off(code, R9, body->slot_offset[slot] + off, true);
                    }
                }
            }
        } else if (kind == SLOT_OBJECT || kind == SLOT_ARRAY_I32 ||
                   kind == SLOT_SEQ_I32 || kind == SLOT_SEQ_STR ||
                   kind == SLOT_SEQ_OPAQUE) {
            if (size > 16) {
                int32_t src_reg = in_regs ? base_reg : R9;
                if (!in_regs) a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                for (int32_t off = 0; off < size; off += 8) {
                    a64_emit_ldr_off(code, R10, src_reg, off, true);
                    a64_emit_str_sp_off(code, R10, body->slot_offset[slot] + off, true);
                }
            } else {
                if (in_regs) {
                    a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
                    a64_emit_str_sp_off(code, base_reg + 1, body->slot_offset[slot] + 8, true);
                } else {
                    for (int32_t off = 0; off < size; off += 8) {
                        a64_emit_ldr_off(code, R9, FP, incoming_stack_offset + off, true);
                        a64_emit_str_sp_off(code, R9, body->slot_offset[slot] + off, true);
                    }
                }
            }
        } else if (kind == SLOT_SEQ_I32_REF || kind == SLOT_SEQ_STR_REF ||
                   kind == SLOT_SEQ_OPAQUE_REF ||
                   kind == SLOT_OBJECT_REF || kind == SLOT_OPAQUE ||
                   kind == SLOT_OPAQUE_REF || kind == -1) {
            if (in_regs) {
                a64_emit_str_sp_off(code, base_reg, body->slot_offset[slot], true);
            } else {
                a64_emit_ldr_off(code, R9, FP, incoming_stack_offset, true);
                a64_emit_str_sp_off(code, R9, body->slot_offset[slot], true);
            }
        } else {
            die("unsupported cold parameter kind");
        }
    }
}

static void codegen_place_x_arg(Code *code, bool in_regs, int32_t base_reg,
                                int32_t stack_offset, int32_t src_reg) {
    if (in_regs) {
        if (base_reg != src_reg) code_emit(code, a64_add_imm(base_reg, src_reg, 0, true));
    } else {
        a64_emit_str_sp_off(code, src_reg, stack_offset, true);
    }
}

static void codegen_place_w_arg(Code *code, bool in_regs, int32_t base_reg,
                                int32_t stack_offset, int32_t src_reg,
                                int32_t abi_bytes) {
    if (in_regs) {
        if (base_reg != src_reg) code_emit(code, a64_add_imm(base_reg, src_reg, 0, true));
    } else if (abi_bytes == 1) {
        /* Darwin packed bool stack slot: store exactly one byte (values are
           already normalized 0/1 by Cheng bool semantics). */
        a64_emit_strb_sp_off(code, src_reg, stack_offset);
    } else {
        a64_emit_str_sp_off(code, src_reg, stack_offset, false);
    }
}

static bool codegen_slot_is_uint8_fixed_array(BodyIR *body, int32_t slot);
static void codegen_mmap_len_reg(Code *code, int len_reg, int dst_reg, int brk_imm);
static void codegen_copy_bytes(Code *code, int src_reg, int len_reg, int dst_cursor_reg);
static void codegen_mov_i32_const(Code *code, int reg, int32_t value);

static bool cold_codegen_param_is_type(FnDef *fn, int32_t index, const char *type_name) {
    if (!fn || index < 0 || index >= fn->arity) return false;
    return span_eq(span_trim(fn->param_type[index]), type_name);
}

static bool cold_codegen_param_is_cstring(FnDef *fn, int32_t index) {
    return cold_codegen_param_is_type(fn, index, "cstring");
}

static bool cold_codegen_param_is_utf8_view(FnDef *fn, int32_t index) {
    return cold_codegen_param_is_type(fn, index, "utf8_view");
}

static bool cold_codegen_param_is_bytes_view(FnDef *fn, int32_t index) {
    return cold_codegen_param_is_type(fn, index, "bytes_view");
}

static bool cold_codegen_type_is_bytes_object(Span type) {
    type = span_trim(type);
    return span_eq(type, "Bytes") || span_eq(type, "rawbytes.Bytes");
}

static void codegen_place_pair_arg(Code *code, bool in_regs, int32_t base_reg,
                                   int32_t stack_offset, int ptr_reg, int len_reg) {
    if (in_regs) {
        if (base_reg != ptr_reg) code_emit(code, a64_add_imm(base_reg, ptr_reg, 0, true));
        if (base_reg + 1 != len_reg) code_emit(code, a64_add_imm(base_reg + 1, len_reg, 0, true));
    } else {
        a64_emit_str_sp_off(code, ptr_reg, stack_offset, true);
        a64_emit_str_sp_off(code, len_reg, stack_offset + 8, true);
    }
}

static void cold_a64_emit_string_literal_pair(Code *code, BodyIR *body,
                                              int32_t literal_index,
                                              int ptr_reg, int len_reg) {
    if (!body || literal_index < 0 ||
        literal_index >= body->string_literal_count)
        die("invalid string literal index");
    Span literal = body->string_literal[literal_index];
    int32_t adr_pos = code->count;
    code_emit(code, a64_adr(ptr_reg, 0));
    int32_t data_offset = -1;
    if (code->local_string_literal_offsets &&
        literal_index < code->local_string_literal_count) {
        data_offset = code->local_string_literal_offsets[literal_index];
        int32_t delta = data_offset - adr_pos * 4;
        if (data_offset < 0 || delta <= -1048576 || delta >= 1048576) {
            data_offset = -1;
        }
    }
    if (data_offset >= 0) {
        code->words[adr_pos] = a64_adr(ptr_reg, data_offset - adr_pos * 4);
    } else {
        int32_t skip_pos = code->count;
        code_emit(code, a64_b(0));
        data_offset = code_append_bytes(code, (const char *)literal.ptr,
                                        literal.len + 1);
        int32_t after_data = code->count;
        code->words[adr_pos] = a64_adr(ptr_reg, data_offset - adr_pos * 4);
        code->words[skip_pos] = a64_b(after_data - skip_pos);
        if (code->local_string_literal_offsets &&
            literal_index < code->local_string_literal_count) {
            code->local_string_literal_offsets[literal_index] = data_offset;
        }
    }
    if (literal.len <= 0xFFFF) {
        code_emit(code, a64_movz_x(len_reg, (uint16_t)literal.len, 0));
    } else {
        code_emit(code, a64_movz_x(len_reg, (uint16_t)(literal.len & 0xFFFF), 0));
        code_emit(code, a64_movk(len_reg, (uint16_t)((literal.len >> 16) & 0xFFFF), 1));
    }
}

static bool cold_body_call_arg_uses_slot(BodyIR *body, Symbols *symbols,
                                         int32_t op, int32_t slot) {
    if (!body || !symbols || op < 0 || op >= body->op_count) return true;
    int32_t kind = body->op_kind[op];
    if (kind != BODY_OP_CALL_I32 && kind != BODY_OP_CALL_COMPOSITE) return false;
    int32_t fn_index = body->op_a[op];
    int32_t arg_start = body->op_b[op];
    if (fn_index < 0 || fn_index >= symbols->function_count) return true;
    FnDef *fn = &symbols->functions[fn_index];
    if (arg_start < 0 || arg_start + fn->arity > body->call_arg_count) return true;
    for (int32_t i = 0; i < fn->arity; i++) {
        if (body->call_arg_slot[arg_start + i] == slot) return true;
    }
    return false;
}

static bool cold_body_op_reads_slot(BodyIR *body, Symbols *symbols,
                                    int32_t op, int32_t slot) {
    if (!body || op < 0 || op >= body->op_count) return true;
    int32_t kind = body->op_kind[op];
    const ColdBodyOpSchema *schema = cold_body_op_schema(kind);
    if (kind == BODY_OP_CALL_I32 || kind == BODY_OP_CALL_COMPOSITE)
        return cold_body_call_arg_uses_slot(body, symbols, op, slot);
    if (body->op_a[op] == slot || body->op_b[op] == slot ||
        (schema->reads_c_slot && body->op_c[op] == slot) ||
        (schema->reads_dst_slot && body->op_dst[op] == slot))
        return true;
    if (kind == BODY_OP_MAKE_COMPOSITE || kind == BODY_OP_MAKE_VARIANT) {
        int32_t start = body->op_b[op];
        int32_t count = body->op_c[op];
        if (start < 0 || count < 0 || start + count > body->call_arg_count)
            return true;
        for (int32_t i = 0; i < count; i++) {
            if (body->call_arg_slot[start + i] == slot) return true;
        }
    }
    if (kind == BODY_OP_MAKE_SEQ_OPAQUE) {
        int32_t start = body->op_a[op];
        int32_t count = body->op_c[op];
        if (start < 0 || count < 0 || start + count > body->call_arg_count)
            return true;
        for (int32_t i = 0; i < count; i++) {
            if (body->call_arg_slot[start + i] == slot) return true;
        }
    }
    return false;
}

static int32_t cold_a64_call_str_literal_index(BodyIR *body, Symbols *symbols,
                                               FnDef *fn, int32_t call_op,
                                               int32_t arg_start,
                                               int32_t param_index) {
    if (!body || !fn || call_op <= 0 || param_index < 0 ||
        param_index >= fn->arity) return -1;
    int32_t arg_pos = arg_start + param_index;
    if (arg_pos < 0 || arg_pos >= body->call_arg_count) return -1;
    int32_t slot = body->call_arg_slot[arg_pos];
    if (slot < 0 || slot >= body->slot_count ||
        body->slot_kind[slot] != SLOT_STR) return -1;
    int32_t def = call_op - 1;
    while (def >= 0 && body->op_kind[def] == BODY_OP_NOP) def--;
    if (def < 0 || body->op_kind[def] != BODY_OP_STR_LITERAL ||
        body->op_dst[def] != slot) return -1;
    if (cold_effective_call_param_kind(body, fn, arg_start, param_index) != SLOT_STR)
        return -1;
    for (int32_t op = call_op + 1; op < body->op_count; op++) {
        if (body->op_dst[op] == slot) break;
        if (cold_body_op_reads_slot(body, symbols, op, slot)) return -1;
    }
    int32_t literal_index = body->op_a[def];
    if (literal_index < 0 || literal_index >= body->string_literal_count)
        return -1;
    return literal_index;
}

static bool cold_a64_str_literal_deferred_to_call(BodyIR *body, Symbols *symbols,
                                                  int32_t literal_op) {
    if (!body || literal_op < 0 || literal_op >= body->op_count ||
        body->op_kind[literal_op] != BODY_OP_STR_LITERAL) return false;
    int32_t slot = body->op_dst[literal_op];
    if (slot < 0 || slot >= body->slot_count ||
        body->slot_kind[slot] != SLOT_STR) return false;
    int32_t call_op = literal_op + 1;
    while (call_op < body->op_count &&
           body->op_kind[call_op] == BODY_OP_NOP) call_op++;
    if (call_op >= body->op_count) return false;
    int32_t kind = body->op_kind[call_op];
    if (kind != BODY_OP_CALL_I32 && kind != BODY_OP_CALL_COMPOSITE) return false;
    int32_t fn_index = body->op_a[call_op];
    int32_t arg_start = body->op_b[call_op];
    if (fn_index < 0 || fn_index >= symbols->function_count) return false;
    FnDef *fn = &symbols->functions[fn_index];
    if (arg_start < 0 || arg_start + fn->arity > body->call_arg_count) return false;
    for (int32_t i = 0; i < fn->arity; i++) {
        if (body->call_arg_slot[arg_start + i] != slot) continue;
        return cold_a64_call_str_literal_index(body, symbols, fn, call_op,
                                               arg_start, i) >= 0;
    }
    return false;
}

static void codegen_load_str_pair_at_offset(Code *code, BodyIR *body, int32_t slot,
                                            int32_t local_offset,
                                            int ptr_reg, int len_reg) {
    int32_t kind = body->slot_kind[slot];
    if (kind == SLOT_STR_REF) {
        a64_emit_ldr_sp_off(code, ptr_reg, local_offset, true);
        code_emit(code, a64_ldr_imm(len_reg, ptr_reg, COLD_STR_LEN_OFFSET, false));
        code_emit(code, a64_ldr_imm(ptr_reg, ptr_reg, COLD_STR_DATA_OFFSET, true));
    } else if (kind == SLOT_STR) {
        a64_emit_ldr_sp_off(code, ptr_reg, local_offset + COLD_STR_DATA_OFFSET, true);
        a64_emit_ldr_sp_off(code, len_reg, local_offset + COLD_STR_LEN_OFFSET, false);
    } else {
        die("codegen_load_str_pair_at_offset slot kind mismatch");
    }
    code_emit(code, a64_cmp_imm(len_reg, 0));
    int32_t nonempty = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_imm(ptr_reg, SP, 0, true));
    a64_patch_bcond(code, nonempty, code->count);
}

static void codegen_reject_embedded_nul_in_pair(Code *code, int ptr_reg,
                                                int len_reg, int brk_imm) {
    code_emit(code, a64_movz_x(R11, 0, 0));
    int32_t loop = code->count;
    code_emit(code, a64_cmp_reg_x(R11, len_reg));
    int32_t done = code->count;
    code_emit(code, a64_bcond(0, COND_GE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_reg_x(R12, ptr_reg, R11));
    code_emit(code, a64_ldrb_imm(R10, R12, 0));
    code_emit(code, a64_cmp_imm(R10, 0));
    int32_t byte_ok = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_brk(brk_imm));
    a64_patch_bcond(code, byte_ok, code->count);
    code_emit(code, a64_add_imm(R11, R11, 1, true));
    code_emit(code, a64_b(loop - code->count));
    a64_patch_bcond(code, done, code->count);
}

static void codegen_cstring_from_slot_at_offset(Code *code, BodyIR *body,
                                                int32_t slot,
                                                int32_t local_offset,
                                                int dst_reg,
                                                int brk_imm) {
    codegen_load_str_pair_at_offset(code, body, slot, local_offset, R2, R3);
    codegen_reject_embedded_nul_in_pair(code, R2, R3, brk_imm);
    code_emit(code, a64_add_imm(R1, R3, 1, true));
    /* Save R0-R1 across mmap: mmap clobbers R0 (return value) and may
     * clobber R1 (len_reg adjusted to R1).  This is essential when
     * codegen_load_call_args has already placed a prior cstring argument
     * into R0 via codegen_place_x_arg. */
    code_emit(code, 0xa9bf07e0);  /* stp x0, x1, [sp, #-16]! */
    codegen_mmap_len_reg(code, R1, dst_reg, brk_imm);
    code_emit(code, 0xa8c107e0);  /* ldp x0, x1, [sp], #16 */
    codegen_load_str_pair_at_offset(code, body, slot, local_offset, R2, R3);
    code_emit(code, a64_add_imm(R6, dst_reg, 0, true));
    codegen_copy_bytes(code, R2, R3, R6);
    code_emit(code, a64_movz(R5, 0, 0));
    code_emit(code, a64_strb_imm(R5, R6, 0));
}

static void codegen_load_bytes_view_pair_at_offset(Code *code, BodyIR *body,
                                                   int32_t slot,
                                                   int32_t local_offset,
                                                   int ptr_reg,
                                                   int len_reg,
                                                   int brk_imm) {
    int32_t kind = body->slot_kind[slot];
    if (kind == SLOT_ARRAY_I32 && codegen_slot_is_uint8_fixed_array(body, slot)) {
        a64_emit_add_large(code, ptr_reg, SP, local_offset, true);
        codegen_mov_i32_const(code, len_reg, body->slot_aux[slot]);
        return;
    }
    Span slot_type = span_trim(body->slot_type[slot]);
    if ((kind == SLOT_OBJECT || kind == SLOT_OBJECT_REF) &&
        cold_codegen_type_is_bytes_object(slot_type)) {
        if (kind == SLOT_OBJECT_REF) {
            a64_emit_ldr_sp_off(code, R12, local_offset, true);
            code_emit(code, a64_cmp_imm(R12, 0));
            int32_t ok = code->count;
            code_emit(code, a64_bcond(0, COND_NE));
            code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
            code_emit(code, a64_brk(brk_imm));
            a64_patch_bcond(code, ok, code->count);
            code_emit(code, a64_ldr_imm(ptr_reg, R12, 0, true));
            code_emit(code, a64_ldr_imm(len_reg, R12, 8, false));
        } else {
            a64_emit_ldr_sp_off(code, ptr_reg, local_offset + 0, true);
            a64_emit_ldr_sp_off(code, len_reg, local_offset + 8, false);
        }
        return;
    }
    die("bytes_view expects Bytes or uint8 fixed array");
}

static uint32_t a64_sxtw(int rd, int rn); /* Bug D fwd-decl: i32->i64 arg widen */
/* Cold mirror of the primary/backend2 ARMv8 SHA-256 call-site recognizer
   (PrimaryInlineSha256BlockKind). Matches the leaf name of
   cheng_crypto_sha256_compress_block / cheng_sha256_compress_block (the
   Path C / #60 seam functions whose scalar body is the single-block software
   compress) and requires the exact (ptr, ptr, ptr) ABI the kernel assumes:
   state = 8x uint32 hash words (native-endian, in/out), block = 64-byte raw
   big-endian message block, k256 = 64x uint32 round constants. */
static bool cold_fn_is_sha256_compress_block(FnDef *fn) {
    if (!fn || fn->arity != 3) return false;
    Span name = span_trim(fn->name);
    int32_t start = 0;
    for (int32_t i = 0; i < name.len; i++) {
        if (name.ptr[i] == '.') start = i + 1;
    }
    Span leaf = span_sub(name, start, name.len);
    if (!span_eq(leaf, "cheng_crypto_sha256_compress_block") &&
        !span_eq(leaf, "cheng_sha256_compress_block")) return false;
    for (int32_t i = 0; i < 3; i++) {
        if (fn->param_size[i] != 8) return false;
        if (fn->param_kind[i] != SLOT_OPAQUE && fn->param_kind[i] != SLOT_PTR)
            return false;
    }
    return true;
}

/* EXACTLY 193 words: mirrors sha256_hw_v3.s /
   PrimaryBodyIRFillInlineSha256Block instruction-for-instruction (no invented
   scheduling). X0=state ptr (32B, in/out), X1=block ptr (64B), X2=k256 ptr
   (256B). Clobbers x9 and v0-v7/v16-v21, all caller-saved by AAPCS64, so the
   usual post-call na_clobber(0..7) discipline covers the x-side. */
static void cold_a64_emit_inline_sha256_compress_block(Code *code) {
    code_emit(code, a64_ldr_q(0, 0, 0));
    code_emit(code, a64_ldr_q(1, 0, 16));
    code_emit(code, a64_ldr_q(4, 1, 0));
    code_emit(code, a64_ldr_q(5, 1, 16));
    code_emit(code, a64_ldr_q(6, 1, 32));
    code_emit(code, a64_ldr_q(7, 1, 48));
    code_emit(code, a64_rev32_v16b(4, 4));
    code_emit(code, a64_rev32_v16b(5, 5));
    code_emit(code, a64_rev32_v16b(6, 6));
    code_emit(code, a64_rev32_v16b(7, 7));
    code_emit(code, a64_mov_v16b(2, 0));
    code_emit(code, a64_mov_v16b(3, 1));
    for (int32_t g = 0; g < 4; g++) {
        int32_t msg = 4 + g;
        code_emit(code, a64_ldr_q(16, 2, g * 16));
        code_emit(code, a64_add_v4s(20, msg, 16));
        code_emit(code, a64_mov_v16b(18, 0));
        code_emit(code, a64_sha256h(0, 1, 20));
        code_emit(code, a64_sha256h2(1, 18, 20));
    }
    code_emit(code, a64_add_imm(9, 2, 64, true));
    for (int32_t i = 0; i < 12; i++) {
        code_emit(code, a64_sha256su0(4, 5));
        code_emit(code, a64_sha256su1(4, 6, 7));
        code_emit(code, a64_ldr_q(16, 9, 0));
        code_emit(code, a64_add_imm(9, 9, 16, true));
        code_emit(code, a64_add_v4s(20, 4, 16));
        code_emit(code, a64_mov_v16b(18, 0));
        code_emit(code, a64_sha256h(0, 1, 20));
        code_emit(code, a64_sha256h2(1, 18, 20));
        code_emit(code, a64_mov_v16b(21, 4));
        code_emit(code, a64_mov_v16b(4, 5));
        code_emit(code, a64_mov_v16b(5, 6));
        code_emit(code, a64_mov_v16b(6, 7));
        code_emit(code, a64_mov_v16b(7, 21));
    }
    code_emit(code, a64_add_v4s(0, 0, 2));
    code_emit(code, a64_add_v4s(1, 1, 3));
    code_emit(code, a64_str_q(0, 0, 0));
    code_emit(code, a64_str_q(1, 0, 16));
}

/* When the call target is the SHA-256 compress seam, the already-placed
   x0/x1/x2 arguments are exactly the kernel's inputs: emit the 193-word
   inline instead of `bl` (the callee's scalar body remains the fallback on
   every non-arm64 path). */
static bool cold_a64_try_emit_inline_sha256_call(Code *code, Symbols *symbols,
                                                 int32_t fn_index) {
    if (fn_index < 0 || fn_index >= symbols->function_count) return false;
    if (!cold_fn_is_sha256_compress_block(&symbols->functions[fn_index]))
        return false;
    cold_a64_emit_inline_sha256_compress_block(code);
    return true;
}

static int32_t codegen_load_call_args(Code *code, BodyIR *body, Symbols *symbols,
                                      FnDef *fn, int32_t arg_start,
                                      int32_t call_op) {
    int32_t stack_bytes = cold_outgoing_stack_bytes_for_call(body, fn, arg_start);
    if (stack_bytes > 0) a64_emit_sub_large(code, SP, SP, stack_bytes, true);
    int32_t reg = 0;
    int32_t stack = 0;
    for (int32_t i = 0; i < fn->arity; i++) {
        int32_t arg_slot = body->call_arg_slot[arg_start + i];
        int32_t arg_kind = body->slot_kind[arg_slot];
        int32_t param_kind = cold_effective_call_param_kind(body, fn, arg_start, i);
        int32_t param_size = cold_effective_call_param_size(body, fn, arg_start, i);
        int32_t base_reg = -1;
        int32_t stack_offset = -1;
        bool in_regs = cold_abi_place_arg(&reg, &stack, param_kind,
                                          param_size, &base_reg, &stack_offset);
        int32_t local_offset = body->slot_offset[arg_slot] + stack_bytes;
        if (cold_codegen_param_is_utf8_view(fn, i)) {
            codegen_load_str_pair_at_offset(code, body, arg_slot, local_offset,
                                            R9, R10);
            codegen_place_pair_arg(code, in_regs, base_reg, stack_offset, R9, R10);
            continue;
        }
        if (cold_codegen_param_is_bytes_view(fn, i)) {
            codegen_load_bytes_view_pair_at_offset(code, body, arg_slot, local_offset,
                                                   R9, R10, 121);
            codegen_place_pair_arg(code, in_regs, base_reg, stack_offset, R9, R10);
            continue;
        }
        if (cold_codegen_param_is_cstring(fn, i) &&
            (arg_kind == SLOT_STR || arg_kind == SLOT_STR_REF)) {
            codegen_cstring_from_slot_at_offset(code, body, arg_slot, local_offset,
                                                R9, 120);
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_STR && arg_kind == SLOT_STR) {
            int32_t literal_index = cold_a64_call_str_literal_index(
                body, symbols, fn, call_op, arg_start, i);
            if (literal_index >= 0) {
                cold_a64_emit_string_literal_pair(code, body, literal_index, R9, R10);
                codegen_place_pair_arg(code, in_regs, base_reg, stack_offset, R9, R10);
                continue;
            }
        }
        if (param_kind == SLOT_I32_REF) {
            if (arg_kind == SLOT_I32_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_I32) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_I64_REF) {
            if (arg_kind == SLOT_I64_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_I64) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_SEQ_I32_REF) {
            if (arg_kind == SLOT_SEQ_I32_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_SEQ_I32) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_SEQ_STR_REF) {
            if (arg_kind == SLOT_SEQ_STR_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_SEQ_STR) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_SEQ_OPAQUE_REF) {
            if (arg_kind == SLOT_SEQ_OPAQUE_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_SEQ_OPAQUE) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_STR_REF) {
            if (arg_kind == SLOT_STR_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_STR) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_PTR) {
            if (arg_kind == SLOT_OPAQUE_REF &&
                fn->param_type[i].len > 0 &&
                span_same(fn->param_type[i], body->slot_type[arg_slot])) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
                code_emit(code, a64_ldr_imm(R9, R9, 0, true));
            } else {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_OBJECT_REF) {
            if (arg_kind == SLOT_OBJECT_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else if (arg_kind == SLOT_OBJECT) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_OPAQUE_REF) {
            if (arg_kind == SLOT_OPAQUE_REF || arg_kind == SLOT_OBJECT_REF ||
                arg_kind == SLOT_I32_REF || arg_kind == SLOT_I64_REF ||
                arg_kind == SLOT_STR_REF || arg_kind == SLOT_SEQ_I32_REF ||
                arg_kind == SLOT_SEQ_STR_REF || arg_kind == SLOT_SEQ_OPAQUE_REF) {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
            } else {
                a64_emit_add_large(code, R9, SP, local_offset, true);
            }
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_OPAQUE) {
            if (arg_kind == SLOT_STR) {
                /* Extract just the data pointer (first 8 bytes) from str struct */
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
                codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
                continue;
            }
            if (arg_kind == SLOT_STR_REF) {
                /* Load ref, then dereference to get str.data_ptr */
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
                code_emit(code, a64_ldr_imm(R9, R9, 0, true));
                codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
                continue;
            }
            /* For other arg kinds, fall through to general handling */
        }
        if (param_kind == SLOT_I32 && arg_kind == SLOT_I32_REF) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            code_emit(code, a64_ldr_imm(R9, R9, 0, false));
            codegen_place_w_arg(code, in_regs, base_reg, stack_offset, R9,
                                cold_abi_arg_storage_bytes(param_kind, param_size));
            continue;
        }
        if (param_kind == SLOT_I32 && arg_kind == SLOT_VARIANT) {
            a64_emit_ldr_sp_off(code, R9, local_offset, false);
            codegen_place_w_arg(code, in_regs, base_reg, stack_offset, R9,
                                cold_abi_arg_storage_bytes(param_kind, param_size));
            continue;
        }
        if (param_kind == SLOT_I64 && arg_kind == SLOT_I64_REF) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            code_emit(code, a64_ldr_imm(R9, R9, 0, true));
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (param_kind == SLOT_STR && arg_kind == SLOT_STR_REF) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            if (in_regs) {
                code_emit(code, a64_ldr_imm(base_reg, R9, 0, true));
                code_emit(code, a64_ldr_imm(base_reg + 1, R9, 8, true));
            } else {
                code_emit(code, a64_ldr_imm(R9, R9, 0, true));
                a64_emit_str_sp_off(code, R9, stack_offset, true);
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
                code_emit(code, a64_ldr_imm(R9, R9, 8, true));
                a64_emit_str_sp_off(code, R9, stack_offset + 8, true);
            }
            continue;
        }
        if ((param_kind == SLOT_SEQ_I32 && arg_kind == SLOT_SEQ_I32_REF) ||
            (param_kind == SLOT_SEQ_STR && arg_kind == SLOT_SEQ_STR_REF) ||
            (param_kind == SLOT_SEQ_OPAQUE && arg_kind == SLOT_SEQ_OPAQUE_REF)) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            if (in_regs) {
                code_emit(code, a64_ldr_imm(base_reg, R9, 0, true));
                code_emit(code, a64_ldr_imm(base_reg + 1, R9, 8, true));
            } else {
                code_emit(code, a64_ldr_imm(R10, R9, 0, true));
                a64_emit_str_sp_off(code, R10, stack_offset, true);
                code_emit(code, a64_ldr_imm(R10, R9, 8, true));
                a64_emit_str_sp_off(code, R10, stack_offset + 8, true);
            }
            continue;
        }
        if (param_kind == SLOT_OBJECT && arg_kind == SLOT_OBJECT_REF) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            if (param_size > 16) {
                codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            } else if (in_regs) {
                code_emit(code, a64_ldr_imm(base_reg, R9, 0, true));
                code_emit(code, a64_ldr_imm(base_reg + 1, R9, 8, true));
            } else {
                for (int32_t off = 0; off < param_size; off += 8) {
                    code_emit(code, a64_ldr_imm(R10, R9, off, true));
                    a64_emit_str_sp_off(code, R10, stack_offset + off, true);
                }
            }
            continue;
        }
        /* Bug D: widen i32 arg -> i64 param at the ABI marshalling boundary.
           SLOT_I32 covers signed (int8/16/32/int) and unsigned (uint*) 32-bit
           ints without a signedness slot; a plain 32-bit load zero-extends,
           silently corrupting negative signed values fed to i64 params (e.g.
           ed25519 curve-constant limbs). Sign-extend by default (Cheng's int
           is signed; also covers int literals whose temp slot carries no type
           name) and only zero-extend for explicitly-unsigned uint../char
           args so high-bit unsigned values still survive. */
        if (param_kind == SLOT_I64 && arg_kind == SLOT_I32) {
            Span arg_ty = span_trim(cold_type_strip_var(body->slot_type[arg_slot], 0));
            bool arg_unsigned = (arg_ty.len >= 4 && arg_ty.ptr[0] == 'u' &&
                                 arg_ty.ptr[1] == 'i' && arg_ty.ptr[2] == 'n' &&
                                 arg_ty.ptr[3] == 't') ||
                                span_eq(arg_ty, "char");
            a64_emit_ldr_sp_off(code, R9, local_offset, false); /* ldr w9 (32-bit) */
            if (!arg_unsigned) code_emit(code, a64_sxtw(R9, R9)); /* sxtw x9,w9 */
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            continue;
        }
        if (arg_kind != param_kind) {
            /* tolerate OPAQUE variance (same as cold_call_args_match) */
            if (!((param_kind == SLOT_OPAQUE || param_kind == SLOT_OPAQUE_REF) &&
                  (arg_kind == SLOT_I32 || arg_kind == SLOT_I64 ||
                   arg_kind == SLOT_I32_REF || arg_kind == SLOT_I64_REF ||
                   arg_kind == SLOT_PTR ||
                   arg_kind == SLOT_OBJECT || arg_kind == SLOT_OBJECT_REF ||
                   arg_kind == SLOT_VARIANT || arg_kind == SLOT_SEQ_OPAQUE ||
                   arg_kind == SLOT_SEQ_OPAQUE_REF ||
                   arg_kind == SLOT_OPAQUE || arg_kind == SLOT_OPAQUE_REF)))
                a64_emit_add_large(code, R9, SP, local_offset, true);
        }
        int32_t arg_size = body->slot_size[arg_slot];
        if (arg_kind == SLOT_VARIANT && arg_size != param_size) { continue; }
        if (arg_kind == SLOT_I32 || arg_kind == SLOT_F32) {
            a64_emit_ldr_sp_off(code, R9, local_offset, false);
            codegen_place_w_arg(code, in_regs, base_reg, stack_offset, R9,
                                cold_abi_arg_storage_bytes(param_kind, param_size));
        } else if (arg_kind == SLOT_I64 || arg_kind == SLOT_F64 || arg_kind == SLOT_PTR) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
        } else if (arg_kind == SLOT_STR) {
            if (in_regs) {
                a64_emit_ldr_sp_off(code, base_reg, local_offset, true);
                a64_emit_ldr_sp_off(code, base_reg + 1, local_offset + 8, true);
            } else {
                a64_emit_ldr_sp_off(code, R9, local_offset, true);
                a64_emit_str_sp_off(code, R9, stack_offset, true);
                a64_emit_ldr_sp_off(code, R9, local_offset + 8, true);
                a64_emit_str_sp_off(code, R9, stack_offset + 8, true);
            }
        } else if (arg_kind == SLOT_OPAQUE || arg_kind == SLOT_OPAQUE_REF ||
                   arg_kind == SLOT_OBJECT_REF || arg_kind == SLOT_I32_REF || arg_kind == SLOT_I64_REF ||
                   arg_kind == SLOT_STR_REF || arg_kind == SLOT_SEQ_I32_REF ||
                   arg_kind == SLOT_SEQ_STR_REF || arg_kind == SLOT_SEQ_OPAQUE_REF) {
            a64_emit_ldr_sp_off(code, R9, local_offset, true);
            codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
        } else if (arg_kind == SLOT_VARIANT) {
            if (param_size > 16) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
                codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            } else {
                if (in_regs) {
                    a64_emit_ldr_sp_off(code, base_reg, local_offset, true);
                    a64_emit_ldr_sp_off(code, base_reg + 1, local_offset + 8, true);
                } else {
                    for (int32_t off = 0; off < param_size; off += 8) {
                        a64_emit_ldr_sp_off(code, R9, local_offset + off, true);
                        a64_emit_str_sp_off(code, R9, stack_offset + off, true);
                    }
                }
            }
        } else if (arg_kind == SLOT_OBJECT || arg_kind == SLOT_ARRAY_I32 ||
                   arg_kind == SLOT_SEQ_I32 || arg_kind == SLOT_SEQ_STR ||
                   arg_kind == SLOT_SEQ_OPAQUE) {
            if (param_size > 16) {
                a64_emit_add_large(code, R9, SP, local_offset, true);
                codegen_place_x_arg(code, in_regs, base_reg, stack_offset, R9);
            } else {
                if (in_regs) {
                    a64_emit_ldr_sp_off(code, base_reg, local_offset, true);
                    a64_emit_ldr_sp_off(code, base_reg + 1, local_offset + 8, true);
                } else {
                    for (int32_t off = 0; off < param_size; off += 8) {
                        a64_emit_ldr_sp_off(code, R9, local_offset + off, true);
                        a64_emit_str_sp_off(code, R9, stack_offset + off, true);
                    }
                }
            }
        } else {
            a64_emit_add_large(code, R9, SP, local_offset, true); /* generic SP-relative */
        }
    }
    return stack_bytes;
}

static void codegen_zero_slot(Code *code, BodyIR *body, int32_t slot) {
    code_emit(code, a64_movz_x(R0, 0, 0));
    for (int32_t off = 0; off < body->slot_size[slot]; off += 8) {
        a64_emit_str_sp_off(code, R0, body->slot_offset[slot] + off, true);
    }
}

static void codegen_mov_i32_const(Code *code, int reg, int32_t value) {
    uint32_t bits = (uint32_t)value;
    code_emit(code, a64_movz(reg, (uint16_t)(bits & 0xFFFFu), 0));
    if ((bits & 0xFFFF0000u) != 0) {
        code_emit(code, a64_movk(reg, (uint16_t)((bits >> 16) & 0xFFFFu), 1));
    }
}

static void codegen_mov_i64_const(Code *code, int reg, uint64_t value) {
    code_emit(code, a64_movz_x(reg, (uint16_t)(value & 0xFFFFu), 0));
    if ((value & 0xFFFF0000ULL) != 0) {
        code_emit(code, a64_movk_x(reg, (uint16_t)((value >> 16) & 0xFFFFu), 1));
    }
    if ((value & 0xFFFF00000000ULL) != 0) {
        code_emit(code, a64_movk_x(reg, (uint16_t)((value >> 32) & 0xFFFFu), 2));
    }
    if ((value & 0xFFFF000000000000ULL) != 0) {
        code_emit(code, a64_movk_x(reg, (uint16_t)((value >> 48) & 0xFFFFu), 3));
    }
}

static uint32_t a64_sxtw(int rd, int rn) {
    return 0x93407C00u | ((uint32_t)rn << 5) | (uint32_t)rd;
}

static uint32_t a64_cbnz(int rt, int32_t offset_words) {
    return 0x35000000u | ((uint32_t)(offset_words & 0x7FFFF) << 5) | (uint32_t)rt;
}

static uint32_t a64_fadd_s(int rd, int rn, int rm) { return 0x1E202800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fsub_s(int rd, int rn, int rm) { return 0x1E203800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fmul_s(int rd, int rn, int rm) { return 0x1E200800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fdiv_s(int rd, int rn, int rm) { return 0x1E201800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_scvtf_s(int rd, int rn) { return 0x1E220000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fcvtzs_w(int rd, int rn) { return 0x1E380000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fneg_s(int rd, int rn) { return 0x1E214000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fmov_s(int rd, int rn) { return 0x1E270000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fmov_sr(int rd, int rn) { return 0x1E260000u | ((uint32_t)rn << 5) | (uint32_t)rd; }

/* F64 (double) variants: bit 23 = sz=1 (64-bit float) */
static uint32_t a64_fadd_d(int rd, int rn, int rm) { return 0x1E602800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fsub_d(int rd, int rn, int rm) { return 0x1E603800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fmul_d(int rd, int rn, int rm) { return 0x1E600800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fdiv_d(int rd, int rn, int rm) { return 0x1E601800u | ((uint32_t)rm << 16) | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fneg_d(int rd, int rn) { return 0x1E614000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fmov_d(int rd, int rn) { return 0x9E670000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fmov_dr(int rd, int rn) { return 0x9E660000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_scvtf_d(int rd, int rn) { return 0x1E620000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fcvtzs_wd(int rd, int rn) { return 0x1E780000u | ((uint32_t)rn << 5) | (uint32_t)rd; }
static uint32_t a64_fcmp_s(int rd, int rm) { return 0x1E202000u | ((uint32_t)rm << 16) | ((uint32_t)rd << 5); }
static uint32_t a64_fcmp_d(int rd, int rm) { return 0x1E602000u | ((uint32_t)rm << 16) | ((uint32_t)rd << 5); }
/* #132: FCMP's NZCV table for an unordered (any-NaN) result is N=0,Z=0,C=1,V=1.
   COND_LT (N!=V, aarch64 literal 11) and COND_LE (Z==1||N!=V, literal 13) both
   read that as true, silently reporting NaN < x / NaN <= x as true. The
   aarch64-defined unordered-safe substitutes are MI (N==1) for "<" and LS
   (!(C==1&&Z==0), literal 9 -- already COND_LS) for "<=": both correctly
   evaluate to false on the unordered case. EQ/NE/GT/GE already come out
   correct on FCMP flags (verified via the full NZCV truth table: EQ=Z==1,
   NE=Z==0, GT=Z==0&&N==V, GE=N==V all agree with IEEE754 on the unordered
   row), so only LT/LE are remapped here. Used exclusively by the FCMP
   (F32_CMP/F64_CMP) codegen arms below -- must never touch integer/pointer
   COND_LT/COND_LE, which are correct as-is for two's-complement compares. */
static int32_t a64_fcmp_cond_unordered_safe(int32_t cond) {
    if (cond == COND_LT) return COND_MI;
    if (cond == COND_LE) return COND_LS;
    return cond;
}

static bool cold_body_slot_is_param(BodyIR *body, int32_t slot) {
    if (!body) return false;
    for (int32_t i = 0; i < body->param_count; i++) {
        if (body->param_slot[i] == slot) return true;
    }
    return false;
}

/* #133 v3: is the value TYPE stamped on this slot a signed narrow scalar
   (int8/int16)? parse_postfix already stamps the fixed-array element's real
   type name (e.g. "int8", "uint16") onto the destination slot of a
   constant-index BODY_OP_PAYLOAD_LOAD read (see the `body_slot_set_type`
   calls feeding this op in cold_parser.c) -- this is a direct text lookup
   of that stamp, no re-derivation from the array. uint8/bool/char/uint16
   (and everything else) return false, i.e. keep the existing zero-extend
   behavior. */
static bool codegen_scalar_dst_type_is_signed_narrow(BodyIR *body, int32_t slot) {
    if (!body || slot < 0 || slot >= body->slot_count) return false;
    Span t = span_trim(body->slot_type[slot]);
    return span_eq(t, "int8") || span_eq(t, "int16");
}

static void codegen_copy_slot_from_offset(Code *code, BodyIR *body,
                                          int32_t dst_slot, int32_t src_slot,
                                          int32_t src_offset, int32_t payload_width) {
    int32_t kind = body->slot_kind[dst_slot];
    int32_t src_kind = body->slot_kind[src_slot];
    if (payload_width <= 0) payload_width = body->slot_size[dst_slot];
    if (src_kind == SLOT_OBJECT_REF || src_kind == SLOT_SEQ_I32_REF ||
        src_kind == SLOT_SEQ_STR_REF || src_kind == SLOT_SEQ_OPAQUE_REF ||
        src_kind == SLOT_STR_REF || src_kind == SLOT_PTR ||
        src_kind == SLOT_I32_REF || src_kind == SLOT_I64_REF ||
        src_kind == SLOT_OPAQUE || src_kind == SLOT_OPAQUE_REF) {
        a64_emit_ldr_sp_off(code, R2, body->slot_offset[src_slot], true);
        if (src_kind == SLOT_OBJECT_REF &&
            cold_body_slot_is_param(body, src_slot)) {
            if (kind == SLOT_I32) {
                a64_emit_ldr_width_off_maybe_signed(code, R0, R2, src_offset, payload_width,
                                                    codegen_scalar_dst_type_is_signed_narrow(body, dst_slot));
                a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot], false);
                return;
            }
            int32_t total = payload_width;
            if (total != body->slot_size[dst_slot] &&
                total != align_i32(body->slot_size[dst_slot], 8))
                die("payload load width mismatches destination slot");
            for (int32_t off = 0; off < total; off += 8) {
                a64_emit_ldr_off(code, R0, R2, src_offset + off, true);
                a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot] + off, true);
            }
            return;
        }
        /* Null check: if pointer is NULL, zero dst and return */
        code_emit(code, a64_cmp_reg_x(R2, 31));
        int32_t null_jump = code->count;
        code_emit(code, a64_bcond(0, COND_EQ));
        code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
        if (kind == SLOT_I32) {
            a64_emit_ldr_width_off_maybe_signed(code, R0, R2, src_offset, payload_width,
                                                codegen_scalar_dst_type_is_signed_narrow(body, dst_slot));
            a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot], false);
            int32_t done_b = code->count;
            code_emit(code, a64_b(0));
            /* Null case: zero dst */
            int32_t null_case = code->count;
            a64_patch_bcond(code, null_jump, null_case);
            code_emit(code, a64_movz(R0, 0, 0));
            a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot], false);
            code->words[done_b] = a64_b(code->count - done_b);
            return;
        }
        int32_t total = payload_width;
        if (total != body->slot_size[dst_slot] && total != align_i32(body->slot_size[dst_slot], 8))
            die("payload load width mismatches destination slot");
        for (int32_t off = 0; off < total; off += 8) {
            a64_emit_ldr_off(code, R0, R2, src_offset + off, true);
            a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot] + off, true);
        }
        int32_t done_b2 = code->count;
        code_emit(code, a64_b(0));
        /* Null case: zero entire dst slot */
        int32_t null_case2 = code->count;
        a64_patch_bcond(code, null_jump, null_case2);
        codegen_zero_slot(code, body, dst_slot);
        code->words[done_b2] = a64_b(code->count - done_b2);
        return;
    }
    if (kind == SLOT_I32) {
        a64_emit_ldr_width_off_maybe_signed(code, R0, SP, body->slot_offset[src_slot] + src_offset,
                                            payload_width,
                                            codegen_scalar_dst_type_is_signed_narrow(body, dst_slot));
        a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot], false);
        return;
    }
    int32_t total = payload_width;
    if (total != body->slot_size[dst_slot] && total != align_i32(body->slot_size[dst_slot], 8))
        die("payload load width mismatches destination slot");
    for (int32_t off = 0; off < total; off += 8) {
        a64_emit_ldr_sp_off(code, R0, body->slot_offset[src_slot] + src_offset + off, true);
        a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot] + off, true);
    }
}

static void codegen_copy_stack_slot(Code *code, BodyIR *body,
                                    int32_t dst_slot, int32_t src_slot) {
    int32_t total = body->slot_size[dst_slot];
    int32_t src_total = body->slot_size[src_slot];
    if (src_total < total) total = src_total;
    int32_t off = 0;
    while (off < total) {
        int32_t remaining = total - off;
        bool wide = remaining >= 8;
        a64_emit_ldr_sp_off(code, R0, body->slot_offset[src_slot] + off, wide);
        a64_emit_str_sp_off(code, R0, body->slot_offset[dst_slot] + off, wide);
        off += wide ? 8 : 4;
    }
}

static void codegen_select_slot(Code *code, BodyIR *body,
                                int32_t dst, int32_t cond,
                                int32_t then_slot, int32_t else_slot) {
    if (body->slot_kind[cond] != SLOT_I32) die("select condition must be i32");
    a64_emit_ldr_sp_off(code, R1, body->slot_offset[cond], false);
    code_emit(code, a64_cmp_imm(R1, 0));
    int32_t false_jump = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    codegen_copy_stack_slot(code, body, dst, then_slot);
    int32_t done_jump = code->count;
    code_emit(code, a64_b(0));
    int32_t false_label = code->count;
    a64_patch_bcond(code, false_jump, false_label);
    codegen_copy_stack_slot(code, body, dst, else_slot);
    a64_patch_b(code, done_jump, code->count);
}

static bool cold_payload_store_should_deref_source(BodyIR *body,
                                                   int32_t src_slot,
                                                   int32_t payload_width) {
    if (!body || src_slot < 0 || src_slot >= body->slot_count) return false;
    if (payload_width <= body->slot_size[src_slot]) return false;
    int32_t kind = body->slot_kind[src_slot];
    return kind == SLOT_OBJECT_REF ||
           kind == SLOT_SEQ_I32_REF ||
           kind == SLOT_SEQ_STR_REF ||
           kind == SLOT_SEQ_OPAQUE_REF ||
           kind == SLOT_STR_REF ||
           kind == SLOT_OPAQUE_REF;
}

static void cold_a64_copy_payload_between_bases(Code *code,
                                                int src_base,
                                                int32_t src_offset,
                                                int dst_base,
                                                int32_t dst_offset,
                                                int32_t payload_width) {
    int32_t copied = 0;
    while (payload_width - copied >= 8) {
        a64_emit_ldr_width_off(code, R1, src_base, src_offset + copied, 8);
        a64_emit_str_width_off(code, R1, dst_base, dst_offset + copied, 8);
        copied += 8;
    }
    if (payload_width - copied >= 4) {
        a64_emit_ldr_width_off(code, R1, src_base, src_offset + copied, 4);
        a64_emit_str_width_off(code, R1, dst_base, dst_offset + copied, 4);
        copied += 4;
    }
    if (payload_width - copied >= 2) {
        a64_emit_ldr_width_off(code, R1, src_base, src_offset + copied, 2);
        a64_emit_str_width_off(code, R1, dst_base, dst_offset + copied, 2);
        copied += 2;
    }
    if (payload_width - copied == 1) {
        a64_emit_ldr_width_off(code, R1, src_base, src_offset + copied, 1);
        a64_emit_str_width_off(code, R1, dst_base, dst_offset + copied, 1);
    }
}

static void codegen_store_slot_to_offset(Code *code, BodyIR *body,
                                         int32_t dst_slot, int32_t dst_offset,
                                         int32_t src_slot, int32_t payload_width) {
    int32_t kind = body->slot_kind[src_slot];
    if (payload_width <= 0) payload_width = body->slot_size[src_slot];
    if (kind == SLOT_I32) {
        a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot], false);
        a64_emit_str_width_off(code, R1, SP, body->slot_offset[dst_slot] + dst_offset, payload_width);
        return;
    }
    if (kind == SLOT_I32_REF) {
        if (payload_width != 1 && payload_width != 2 && payload_width != 4)
            die("payload store width mismatches i32 ref source");
        a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
        a64_emit_ldr_width_off(code, R1, R3, 0, payload_width);
        a64_emit_str_width_off(code, R1, SP, body->slot_offset[dst_slot] + dst_offset, payload_width);
        return;
    }
    if (kind == SLOT_I64_REF) {
        if (payload_width != 8) die("payload store width mismatches i64 ref source");
        a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
        a64_emit_ldr_width_off(code, R1, R3, 0, 8);
        a64_emit_str_width_off(code, R1, SP, body->slot_offset[dst_slot] + dst_offset, 8);
        return;
    }
    if (cold_payload_store_should_deref_source(body, src_slot, payload_width)) {
        a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
        cold_a64_copy_payload_between_bases(code, R3, 0, SP,
                                            body->slot_offset[dst_slot] + dst_offset,
                                            payload_width);
        return;
    }
    int32_t total = body->slot_size[src_slot];
    if (payload_width != total && payload_width != align_i32(total, 8)) {
        fprintf(stderr, "cheng_cold: payload store offset mismatch src_kind=%d payload_width=%d src_size=%d src_type=%.*s\n",
                kind, payload_width, total,
                (int)body->slot_type[src_slot].len, body->slot_type[src_slot].ptr);
        die("payload store width mismatches source slot");
    }
    for (int32_t off = 0; off < total; off += 8) {
        a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot] + off, true);
        a64_emit_str_sp_off(code, R1, body->slot_offset[dst_slot] + dst_offset + off, true);
    }
}

static void codegen_store_slot_to_payload(Code *code, BodyIR *body,
                                          int32_t dst_slot, int32_t dst_offset,
                                          int32_t src_slot, int32_t payload_width) {
    int32_t dst_kind = body->slot_kind[dst_slot];
    if (dst_kind == SLOT_OBJECT) {
        codegen_store_slot_to_offset(code, body, dst_slot, dst_offset, src_slot, payload_width);
        return;
    }
    if (dst_kind != SLOT_OBJECT_REF && dst_kind != SLOT_SEQ_I32_REF &&
        dst_kind != SLOT_SEQ_STR_REF && dst_kind != SLOT_SEQ_OPAQUE_REF &&
        dst_kind != SLOT_STR_REF && dst_kind != SLOT_PTR &&
        dst_kind != SLOT_I32_REF && dst_kind != SLOT_I64_REF &&
        dst_kind != SLOT_OPAQUE && dst_kind != SLOT_OPAQUE_REF) {
        /* Non-object slot: write source directly to SP + base + field_offset */
        int32_t base_off = body->slot_offset[dst_slot];
        int32_t total_off = base_off + dst_offset;
        int32_t src_kind = body->slot_kind[src_slot];
        if (payload_width <= 0) payload_width = body->slot_size[src_slot];
        if (src_kind == SLOT_I32) {
            a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot], false);
            a64_emit_str_width_off(code, R1, SP, total_off, payload_width);
        } else if (src_kind == SLOT_I64) {
            a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot], true);
            if (payload_width != 8) die("payload store width mismatches i64 source");
            a64_emit_str_sp_off(code, R1, total_off, true);
        } else if (src_kind == SLOT_I32_REF) {
            if (payload_width != 1 && payload_width != 2 && payload_width != 4)
                die("payload store width mismatches i32 ref source");
            a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
            a64_emit_ldr_width_off(code, R1, R3, 0, payload_width);
            a64_emit_str_width_off(code, R1, SP, total_off, payload_width);
        } else if (src_kind == SLOT_I64_REF) {
            if (payload_width != 8) die("payload store width mismatches i64 ref source");
            a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
            a64_emit_ldr_width_off(code, R1, R3, 0, 8);
            a64_emit_str_width_off(code, R1, SP, total_off, 8);
        } else if (cold_payload_store_should_deref_source(body, src_slot, payload_width)) {
            a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
            cold_a64_copy_payload_between_bases(code, R3, 0, SP, total_off, payload_width);
        } else {
            int32_t sz = body->slot_size[src_slot];
            if (payload_width != sz && payload_width != align_i32(sz, 8)) {
                fprintf(stderr, "cheng_cold: payload store nonobject mismatch src_kind=%d payload_width=%d src_size=%d src_type=%.*s\n",
                        src_kind, payload_width, sz,
                        (int)body->slot_type[src_slot].len, body->slot_type[src_slot].ptr);
                die("payload store width mismatches source slot");
            }
            for (int32_t off = 0; off < sz; off += 8) {
                a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot] + off, true);
                a64_emit_str_sp_off(code, R1, total_off + off, true);
            }
        }
        return;
    }
    a64_emit_ldr_sp_off(code, R2, body->slot_offset[dst_slot], true);
    int32_t kind = body->slot_kind[src_slot];
    if (payload_width <= 0) payload_width = body->slot_size[src_slot];
    if (kind == SLOT_I32) {
        a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot], false);
        a64_emit_str_width_off(code, R1, R2, dst_offset, payload_width);
        return;
    }
    if (kind == SLOT_I32_REF) {
        if (payload_width != 1 && payload_width != 2 && payload_width != 4)
            die("payload store width mismatches i32 ref source");
        a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
        a64_emit_ldr_width_off(code, R1, R3, 0, payload_width);
        a64_emit_str_width_off(code, R1, R2, dst_offset, payload_width);
        return;
    }
    if (kind == SLOT_I64_REF) {
        if (payload_width != 8) die("payload store width mismatches i64 ref source");
        a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
        a64_emit_ldr_width_off(code, R1, R3, 0, 8);
        a64_emit_str_width_off(code, R1, R2, dst_offset, 8);
        return;
    }
    if (cold_payload_store_should_deref_source(body, src_slot, payload_width)) {
        a64_emit_ldr_sp_off(code, R3, body->slot_offset[src_slot], true);
        cold_a64_copy_payload_between_bases(code, R3, 0, R2, dst_offset, payload_width);
        return;
    }
    int32_t total = body->slot_size[src_slot];
    if (payload_width != total && payload_width != align_i32(total, 8)) {
        fprintf(stderr, "cheng_cold: payload store ref mismatch src_kind=%d payload_width=%d src_size=%d src_type=%.*s\n",
                kind, payload_width, total,
                (int)body->slot_type[src_slot].len, body->slot_type[src_slot].ptr);
        die("payload store width mismatches source slot");
    }
    for (int32_t off = 0; off < total; off += 8) {
        a64_emit_ldr_sp_off(code, R1, body->slot_offset[src_slot] + off, true);
        a64_emit_str_off(code, R1, R2, dst_offset + off, true);
    }
}

static int32_t cold_codegen_slot_copy_width(BodyIR *body, int32_t slot) {
    if (!body || slot < 0 || slot >= body->slot_count) die("cold frame invalid slot");
    int32_t kind = body->slot_kind[slot];
    int32_t size = body->slot_size[slot];
    if (size <= 0) return 0;
    if (kind == SLOT_I32) return 4;
    return align_i32(size, 8);
}

static void cold_frame_require_slot_span(BodyIR *body, int32_t *required,
                                         int32_t slot, int32_t offset,
                                         int32_t size) {
    if (!body || !required) die("cold frame span invalid");
    if (slot < 0 || slot >= body->slot_count) die("cold frame span invalid slot");
    if (offset < 0 || size < 0) die("cold frame span negative range");
    int32_t end = body->slot_offset[slot] + offset + size;
    if (end > *required) *required = end;
}

static bool cold_frame_kind_is_local_payload_target(int32_t kind) {
    return kind != SLOT_OBJECT_REF && kind != SLOT_SEQ_I32_REF &&
           kind != SLOT_SEQ_STR_REF && kind != SLOT_SEQ_OPAQUE_REF &&
           kind != SLOT_STR_REF && kind != SLOT_PTR &&
           kind != SLOT_I32_REF && kind != SLOT_I64_REF &&
           kind != SLOT_OPAQUE && kind != SLOT_OPAQUE_REF;
}

static void cold_frame_require_call_return(BodyIR *body, Symbols *symbols,
                                           int32_t *required, int32_t dst,
                                           int32_t fn_index) {
    if (dst < 0 || fn_index < 0 || fn_index >= symbols->function_count) return;
    FnDef *fn = &symbols->functions[fn_index];
    int32_t ret_kind = cold_return_kind_from_span(symbols, fn->ret);
    if (ret_kind == SLOT_I32 || ret_kind == SLOT_I64 ||
        ret_kind == SLOT_F32 || ret_kind == SLOT_F64 ||
        ret_kind == SLOT_PTR || ret_kind == SLOT_OPAQUE) {
        return;
    }
    int32_t ret_size = cold_return_slot_size(symbols, fn->ret, ret_kind);
    cold_frame_require_slot_span(body, required, dst, 0, ret_size);
}

static int32_t cold_required_codegen_frame_size(BodyIR *body, Symbols *symbols) {
    if (!body) return 0;
    int32_t required = body->frame_size;
    for (int32_t si = 0; si < body->slot_count; si++) {
        if (body->slot_size[si] > 0) {
            cold_frame_require_slot_span(body, &required, si, 0, body->slot_size[si]);
        }
    }
    for (int32_t op = 0; op < body->op_count; op++) {
        int32_t kind = body->op_kind[op];
        int32_t dst = body->op_dst[op];
        int32_t a = body->op_a[op];
        int32_t b = body->op_b[op];
        int32_t c = body->op_c[op];
        if (kind == BODY_OP_MAKE_VARIANT) {
            cold_frame_require_slot_span(body, &required, dst, 0, 8);
            for (int32_t field_index = 0; field_index < c; field_index++) {
                int32_t arg_slot = body->call_arg_slot[b + field_index];
                int32_t payload_offset = body->call_arg_offset[b + field_index];
                int32_t copy_width = cold_codegen_slot_copy_width(body, arg_slot);
                cold_frame_require_slot_span(body, &required, arg_slot, 0, copy_width);
                cold_frame_require_slot_span(body, &required, dst, payload_offset, copy_width);
            }
        } else if (kind == BODY_OP_MAKE_COMPOSITE) {
            cold_frame_require_slot_span(body, &required, dst, 0,
                                         cold_codegen_slot_copy_width(body, dst));
            for (int32_t item_index = 0; item_index < c; item_index++) {
                int32_t src_slot = body->call_arg_slot[b + item_index];
                int32_t dst_offset = body->call_arg_offset[b + item_index];
                int32_t copy_width = cold_codegen_slot_copy_width(body, src_slot);
                cold_frame_require_slot_span(body, &required, src_slot, 0, copy_width);
                cold_frame_require_slot_span(body, &required, dst, dst_offset, copy_width);
            }
        } else if (kind == BODY_OP_PAYLOAD_LOAD) {
            int32_t copy_width = c > 0 ? c : cold_codegen_slot_copy_width(body, dst);
            cold_frame_require_slot_span(body, &required, a, b, copy_width);
            cold_frame_require_slot_span(body, &required, dst, 0,
                                         cold_codegen_slot_copy_width(body, dst));
        } else if (kind == BODY_OP_PAYLOAD_STORE) {
            int32_t store_width = c > 0 ? c : cold_codegen_slot_copy_width(body, a);
            cold_frame_require_slot_span(body, &required, a, 0,
                                         cold_codegen_slot_copy_width(body, a));
            if (cold_frame_kind_is_local_payload_target(body->slot_kind[dst])) {
                cold_frame_require_slot_span(body, &required, dst, b, store_width);
            }
        } else if (kind == BODY_OP_COPY_COMPOSITE) {
            int32_t copy_width = cold_codegen_slot_copy_width(body, dst);
            cold_frame_require_slot_span(body, &required, a, 0, copy_width);
            cold_frame_require_slot_span(body, &required, dst, 0, copy_width);
        } else if (kind == BODY_OP_SELECT) {
            int32_t copy_width = cold_codegen_slot_copy_width(body, dst);
            cold_frame_require_slot_span(body, &required, b, 0, copy_width);
            cold_frame_require_slot_span(body, &required, c, 0, copy_width);
            cold_frame_require_slot_span(body, &required, dst, 0, copy_width);
        } else if (kind == BODY_OP_SLOT_STORE_I32) {
            cold_frame_require_slot_span(body, &required, dst, b, 4);
        } else if (kind == BODY_OP_SLOT_STORE_I64) {
            cold_frame_require_slot_span(body, &required, dst, b, 8);
        } else if (kind == BODY_OP_CALL_I32 || kind == BODY_OP_CALL_COMPOSITE) {
            cold_frame_require_call_return(body, symbols, &required, dst, a);
        }
    }
    return align_i32(required, 16);
}

static void codegen_load_str_pair(Code *code, BodyIR *body, int32_t slot,
                                  int ptr_reg, int len_reg);

static void codegen_str_eq(Code *code, BodyIR *body, int32_t dst, int32_t left, int32_t right) {
    if ((body->slot_kind[left] != SLOT_STR && body->slot_kind[left] != SLOT_STR_REF) ||
        (body->slot_kind[right] != SLOT_STR && body->slot_kind[right] != SLOT_STR_REF)) {
        die("str eq expects str operands");
    }
    codegen_load_str_pair(code, body, left, R2, R3);
    codegen_load_str_pair(code, body, right, 4, 5);
    code_emit(code, a64_cmp_reg(R3, 5));
    int32_t len_ne = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movz(6, 0, 0));
    int32_t loop = code->count;
    code_emit(code, a64_cmp_reg(6, R3));
    int32_t done_equal = code->count;
    code_emit(code, a64_bcond(0, COND_GE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_ldrb_imm(7, R2, 0));
    code_emit(code, a64_ldrb_imm(8, 4, 0));
    code_emit(code, a64_cmp_reg(7, 8));
    int32_t byte_ne = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_imm(R2, R2, 1, true));
    code_emit(code, a64_add_imm(4, 4, 1, true));
    code_emit(code, a64_add_imm(6, 6, 1, false));
    code_emit(code, a64_b(loop - code->count));
    int32_t equal_label = code->count;
    code_emit(code, a64_movz(R0, 1, 0));
    int32_t done_jump = code->count;
    code_emit(code, a64_b(0));
    int32_t false_label = code->count;
    code_emit(code, a64_movz(R0, 0, 0));
    int32_t done = code->count;
    a64_emit_str_sp_off(code, R0, body->slot_offset[dst], false);
    a64_patch_bcond(code, len_ne, false_label);
    a64_patch_bcond(code, done_equal, equal_label);
    a64_patch_bcond(code, byte_ne, false_label);
    a64_patch_b(code, done_jump, done);
}

static void codegen_copy_bytes(Code *code, int src_reg, int len_reg, int dst_cursor_reg) {
    code_emit(code, a64_cmp_imm(len_reg, 0));
    int32_t g3 = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movz(4, 0, 0));
    int32_t loop = code->count;
    code_emit(code, a64_cmp_reg(4, len_reg));
    int32_t done_pos = code->count;
    code_emit(code, a64_bcond(0, COND_GE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_ldrb_imm(5, src_reg, 0));
    code_emit(code, a64_strb_imm(5, dst_cursor_reg, 0));
    code_emit(code, a64_add_imm(src_reg, src_reg, 1, true));
    code_emit(code, a64_add_imm(dst_cursor_reg, dst_cursor_reg, 1, true));
    code_emit(code, a64_add_imm(4, 4, 1, false));
    code_emit(code, a64_b(loop - code->count));
    a64_patch_bcond(code, done_pos, code->count);
    a64_patch_bcond(code, g3, code->count);
}

static void codegen_load_str_pair(Code *code, BodyIR *body, int32_t slot,
                                  int ptr_reg, int len_reg) {
    int32_t kind = body->slot_kind[slot];
    if (kind == SLOT_STR_REF) {
        a64_emit_ldr_sp_off(code, ptr_reg, body->slot_offset[slot], true);
        code_emit(code, a64_ldr_imm(len_reg, ptr_reg, COLD_STR_LEN_OFFSET, false));
        code_emit(code, a64_ldr_imm(ptr_reg, ptr_reg, COLD_STR_DATA_OFFSET, true));
    } else if (kind == SLOT_STR) {
        a64_emit_ldr_sp_off(code, ptr_reg, body->slot_offset[slot] + COLD_STR_DATA_OFFSET, true);
        a64_emit_ldr_sp_off(code, len_reg, body->slot_offset[slot] + COLD_STR_LEN_OFFSET, false);
    } else {
        die("codegen_load_str_pair slot kind mismatch");
    }
    /* guard: if len==0, point ptr to SP to prevent NULL deref */
    code_emit(code, a64_cmp_imm(len_reg, 0));
    int32_t g1 = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_imm(ptr_reg, SP, 0, true));
    a64_patch_bcond(code, g1, code->count);
}

static void codegen_store_str_pair(Code *code, BodyIR *body, int32_t slot,
                                   int ptr_reg, int len_reg) {
    a64_emit_str_sp_off(code, ptr_reg, body->slot_offset[slot] + COLD_STR_DATA_OFFSET, true);
    a64_emit_str_sp_off(code, len_reg, body->slot_offset[slot] + COLD_STR_LEN_OFFSET, false);
    code_emit(code, a64_movz(R0, 0, 0));
    a64_emit_str_sp_off(code, R0, body->slot_offset[slot] + COLD_STR_STORE_ID_OFFSET, false);
    a64_emit_str_sp_off(code, R0, body->slot_offset[slot] + COLD_STR_FLAGS_OFFSET, true);
}

static void codegen_store_empty_str(Code *code, BodyIR *body, int32_t slot) {
    code_emit(code, a64_movz_x(R0, 0, 0));
    codegen_store_str_pair(code, body, slot, R0, R0);
}


static void codegen_mmap_len_reg(Code *code, int len_reg, int dst_reg, int brk_imm);

static void codegen_load_bytes_pair(Code *code, BodyIR *body, int32_t slot,
                                    int ptr_reg, int len_reg) {
    int32_t kind = body->slot_kind[slot];
    if (kind == SLOT_OBJECT_REF || kind == SLOT_OPAQUE_REF) {
        a64_emit_ldr_sp_off(code, R12, body->slot_offset[slot], true);
        code_emit(code, a64_cmp_reg_x(R12, 31));
        int32_t null_jump = code->count;
        code_emit(code, a64_bcond(0, COND_EQ));
        code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
        code_emit(code, a64_ldr_imm(ptr_reg, R12, 0, true));
        code_emit(code, a64_ldr_imm(len_reg, R12, 8, false));
        int32_t done_jump = code->count;
        code_emit(code, a64_b(0));
        int32_t null_label = code->count;
        a64_patch_bcond(code, null_jump, null_label);
        code_emit(code, a64_movz_x(ptr_reg, 0, 0));
        code_emit(code, a64_movz(len_reg, 0, 0));
        a64_patch_b(code, done_jump, code->count);
        return;
    }
    if (kind != SLOT_OBJECT && kind != SLOT_OPAQUE) die("Bytes operation expects object slot");
    a64_emit_ldr_sp_off(code, ptr_reg, body->slot_offset[slot] + 0, true);
    a64_emit_ldr_sp_off(code, len_reg, body->slot_offset[slot] + 8, false);
}

static void codegen_hex_nibble_reg(Code *code, int reg) {
    code_emit(code, a64_movz(R11, 15, 0));
    code_emit(code, a64_and_reg(reg, reg, R11));
    code_emit(code, a64_cmp_imm(reg, 10));
    int32_t letter = code->count;
    code_emit(code, a64_bcond(0, COND_GE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_imm(reg, reg, (uint16_t)'0', false));
    int32_t done_jump = code->count;
    code_emit(code, a64_b(0));
    int32_t letter_label = code->count;
    a64_patch_bcond(code, letter, letter_label);
    code_emit(code, a64_add_imm(reg, reg, (uint16_t)('a' - 10), false));
    a64_patch_b(code, done_jump, code->count);
}

static void codegen_bytes_to_hex(Code *code, BodyIR *body, int32_t dst, int32_t bytes_slot) {
    codegen_store_empty_str(code, body, dst);
    codegen_load_bytes_pair(code, body, bytes_slot, R3, R4);
    code_emit(code, a64_cmp_reg_x(R3, 31));
    int32_t null_done = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm(R4, 0));
    int32_t empty_done = code->count;
    code_emit(code, a64_bcond(0, COND_LE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */

    code_emit(code, a64_add_reg(R1, R4, R4));
    a64_emit_str_sp_off(code, R1, body->slot_offset[dst] + COLD_STR_LEN_OFFSET, false);
    codegen_mmap_len_reg(code, R1, R6, 58);
    a64_emit_str_sp_off(code, R6, body->slot_offset[dst] + COLD_STR_DATA_OFFSET, true);
    code_emit(code, a64_movz(R0, 0, 0));
    a64_emit_str_sp_off(code, R0, body->slot_offset[dst] + COLD_STR_STORE_ID_OFFSET, false);
    a64_emit_str_sp_off(code, R0, body->slot_offset[dst] + COLD_STR_FLAGS_OFFSET, true);

    codegen_load_bytes_pair(code, body, bytes_slot, R3, R4);
    a64_emit_ldr_sp_off(code, R6, body->slot_offset[dst] + COLD_STR_DATA_OFFSET, true);
    int32_t loop = code->count;
    code_emit(code, a64_cmp_imm(R4, 0));
    int32_t done_loop = code->count;
    code_emit(code, a64_bcond(0, COND_LE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_ldrb_imm(R7, R3, 0));
    code_emit(code, a64_lsr_imm(R8, R7, 4, false));
    codegen_hex_nibble_reg(code, R8);
    code_emit(code, a64_strb_imm(R8, R6, 0));
    code_emit(code, a64_add_imm(R8, R7, 0, false));
    codegen_hex_nibble_reg(code, R8);
    code_emit(code, a64_strb_imm(R8, R6, 1));
    code_emit(code, a64_add_imm(R3, R3, 1, true));
    code_emit(code, a64_add_imm(R6, R6, 2, true));
    code_emit(code, a64_sub_imm(R4, R4, 1, false));
    code_emit(code, a64_b(loop - code->count));
    int32_t done = code->count;
    a64_patch_bcond(code, null_done, done);
    a64_patch_bcond(code, empty_done, done);
    a64_patch_bcond(code, done_loop, done);
}


static void codegen_mmap_len_reg_raw(Code *code, int len_reg, int dst_reg, int brk_imm) {
    if (len_reg != R1) code_emit(code, a64_add_imm(R1, len_reg, 0, true));
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_movz_x(R2, 3, 0));
    code_emit(code, a64_movz_x(R3, code->linux_syscalls ? 0x22 : 0x1002, 0));
    code_emit(code, a64_movz_x(4, 0, 0));
    code_emit(code, a64_sub_imm(4, 4, 1, true));
    code_emit(code, a64_movz_x(5, 0, 0));
    if (code->linux_syscalls) {
        code_emit(code, a64_movz_x(8, 222, 0));
        code_emit(code, a64_svc(0));
        code_emit(code, a64_cmp_reg_x(R0, 31));
    } else {
        code_emit(code, a64_movz_x(16, 0x00c5, 0));
        code_emit(code, a64_movk_x(16, 0x0002, 2));
        code_emit(code, a64_svc(0x80));
        code_emit(code, a64_cmp_reg_x(R0, 4));
    }
    int32_t mmap_ok = code->count;
    code_emit(code, a64_bcond(0, code->linux_syscalls ? COND_GE : COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_brk(brk_imm));
    a64_patch_bcond(code, mmap_ok, code->count);
    if (dst_reg != R0) code_emit(code, a64_add_imm(dst_reg, R0, 0, true));
}

/* Allocation entry used by string/array/buffer codegen. When the shared
   bump-allocator routine is present (whole-program codegen), emit a BL to it
   instead of an inline per-allocation mmap: Apple Silicon rounds every
   anonymous mmap to a 16KB page, so per-operation mmaps amplified small
   string allocations by ~100x RSS and were never unmapped. The bump routine
   carves 16-byte-aligned blocks out of 4MB arena chunks. HEAP_ALLOC keeps the
   raw mmap path because HEAP_FREE munmaps those pointers individually. */
static void codegen_mmap_len_reg(Code *code, int len_reg, int dst_reg, int brk_imm) {
    if (code->heap_runtime_calls && code->heap_alloc_shim_pos >= 0) {
        /* Object emission: allocate through the libc calloc shim instead of
           one anonymous mmap per allocation (16KiB page floor on Apple
           Silicon made small allocations explode RSS ~100x). */
        if (len_reg != R1) code_emit(code, a64_add_imm(R1, len_reg, 0, true));
        code_emit(code, a64_bl(code->heap_alloc_shim_pos - code->count));
        if (dst_reg != R0) code_emit(code, a64_add_imm(dst_reg, R0, 0, true));
        return;
    }
    if (code->bump_alloc_pos >= 0) {
        if (len_reg != R1) code_emit(code, a64_add_imm(R1, len_reg, 0, true));
        code_emit(code, a64_bl(code->bump_alloc_pos - code->count));
        if (dst_reg != R0) code_emit(code, a64_add_imm(dst_reg, R0, 0, true));
        return;
    }
    codegen_mmap_len_reg_raw(code, len_reg, dst_reg, brk_imm);
}

/* Dynamic sequence storage participates in Cheng ownership accounting. Cold
   hosted-object code therefore calls cheng_malloc only at a real managed
   allocation site. Keeping the external call inside the owning function is
   important for canonical CSG: the relocation then belongs to that function
   record instead of to an unattributed prefix shim. x6-x15 are cold's live
   scratch-register set across allocation helpers, so preserve them around the
   AAPCS64 call exactly as the old shared shim did. */
static void codegen_managed_len_reg(Code *code, Symbols *symbols,
                                    FunctionPatchList *function_patches,
                                    int len_reg, int dst_reg, int brk_imm) {
    if (code->heap_runtime_calls) {
        int32_t malloc_fn = symbols_require_external_runtime_fn(
            symbols, "cheng_malloc", 1, "ptr");
        if (len_reg != R1) code_emit(code, a64_add_imm(R1, len_reg, 0, true));
        code_emit(code, a64_stp_pre(6, 7, SP, -16));
        code_emit(code, a64_stp_pre(8, 9, SP, -16));
        code_emit(code, a64_stp_pre(10, 11, SP, -16));
        code_emit(code, a64_stp_pre(12, 13, SP, -16));
        code_emit(code, a64_stp_pre(14, 15, SP, -16));
        code_emit(code, a64_add_imm(R0, R1, 0, true));
        int32_t call_pos = code->count;
        code_emit(code, a64_bl(0));
        function_patches_add(function_patches, call_pos, malloc_fn);
        code_emit(code, a64_cmp_imm_x(R0, 0));
        int32_t alloc_ok = code->count;
        code_emit(code, a64_bcond(0, COND_NE));
        code_emit(code, a64_nop());
        code_emit(code, a64_brk(0x7f02));
        a64_patch_bcond(code, alloc_ok, code->count);
        code_emit(code, a64_ldp_post(14, 15, SP, 16));
        code_emit(code, a64_ldp_post(12, 13, SP, 16));
        code_emit(code, a64_ldp_post(10, 11, SP, 16));
        code_emit(code, a64_ldp_post(8, 9, SP, 16));
        code_emit(code, a64_ldp_post(6, 7, SP, 16));
        if (dst_reg != R0) code_emit(code, a64_add_imm(dst_reg, R0, 0, true));
        return;
    }
    codegen_mmap_len_reg(code, len_reg, dst_reg, brk_imm);
}

/* Emit the shared bump-allocator routine. Contract: input x1 = byte length,
   output x0 = allocation; clobbers x0-x5, x16, flags (callee-saved regs and
   LR untouched beyond the BL itself; generated prologues always save LR).
   State lives in a reserved 24-byte global: [0]=bump ptr, [8]=bump end,
   [16]=spinlock word. A spinlock keeps ptr/end updates coherent for fill
   worker threads; chunks are never freed by design. */
static void codegen_emit_bump_alloc_routine(Code *code, int32_t state_global_index) {
    /* round len up to 16 bytes, keep in x5 */
    code_emit(code, a64_add_imm(R1, R1, 15, true));
    code_emit(code, a64_lsr_imm(R1, R1, 4, true));
    code_emit(code, a64_lsl_imm(R1, R1, 4, true));
    code_emit(code, a64_add_imm(5, R1, 0, true));
    /* x0 = &state via GLOBAL_ADDR patch pair (resolves to ADRP+ADD x0) */
    code_record_global_patch(code, code->count, state_global_index, -1);
    code_emit(code, 0);
    code_emit(code, 0);
    code_emit(code, a64_add_imm(R2, R0, 0, true));
    code_emit(code, a64_add_imm(4, R2, 16, true));
    /* spinlock acquire */
    int32_t lock_retry = code->count;
    code_emit(code, a64_ldaxr_w(R3, 4));
    code_emit(code, a64_cbz(R3, lock_retry - code->count, true));
    code_emit(code, a64_movz(R3, 1, 0));
    code_emit(code, a64_stlxr_w(R0, R3, 4));
    code_emit(code, a64_cbz(R0, lock_retry - code->count, true));
    /* fast path: fit in current chunk */
    code_emit(code, a64_ldr_imm(R0, R2, 0, true));
    code_emit(code, a64_ldr_imm(R3, R2, 8, true));
    code_emit(code, a64_add_reg_x(4, R0, 5));
    code_emit(code, a64_cmp_reg_x(4, R3));
    int32_t to_slow = code->count;
    code_emit(code, a64_bcond(0, COND_GT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_str_imm(4, R2, 0, true));
    code_emit(code, a64_add_imm(4, R2, 16, true));
    code_emit(code, a64_stlr_w(31, 4));
    code_emit(code, a64_ret());
    /* slow path: mmap a fresh 4MB+len chunk */
    a64_patch_bcond(code, to_slow, code->count);
    code_emit(code, a64_movz_x(R1, 0x40, 1));
    code_emit(code, a64_add_reg_x(R1, R1, 5));
    code_emit(code, a64_stp_pre(R2, 5, SP, -16));
    codegen_mmap_len_reg_raw(code, R1, R0, 0x7e);
    code_emit(code, a64_ldp_post(R2, 5, SP, 16));
    /* end = base + 4MB + len; newptr = base + len (x1 not trusted after svc) */
    code_emit(code, a64_movz_x(R3, 0x40, 1));
    code_emit(code, a64_add_reg_x(R3, R0, R3));
    code_emit(code, a64_add_reg_x(R3, R3, 5));
    code_emit(code, a64_add_reg_x(4, R0, 5));
    code_emit(code, a64_str_imm(4, R2, 0, true));
    code_emit(code, a64_str_imm(R3, R2, 8, true));
    code_emit(code, a64_add_imm(4, R2, 16, true));
    code_emit(code, a64_stlr_w(31, 4));
    code_emit(code, a64_ret());
}

/* Emit the libc-calloc allocation shim used by object emission. Contract
   matches the bump routine: input x1 = byte length, output x0 = zeroed
   allocation; clobbers x0-x5, x16/x17 (BL), preserves x6-x15. The calloc
   call itself is recorded as a FunctionPatch so the object writer resolves
   it into an external branch relocation. */
static void codegen_emit_heap_alloc_shim(Code *code, FunctionPatchList *patches,
                                         int32_t calloc_fn) {
    code_emit(code, a64_stp_pre(29, 30, SP, -16));
    code_emit(code, a64_stp_pre(6, 7, SP, -16));
    code_emit(code, a64_stp_pre(8, 9, SP, -16));
    code_emit(code, a64_stp_pre(10, 11, SP, -16));
    code_emit(code, a64_stp_pre(12, 13, SP, -16));
    code_emit(code, a64_stp_pre(14, 15, SP, -16));
    code_emit(code, a64_add_imm(R0, R1, 0, true));  /* nmemb = len */
    code_emit(code, a64_movz_x(R1, 1, 0));          /* size = 1 */
    int32_t call_pos = code->count;
    code_emit(code, a64_bl(0));
    function_patches_add(patches, call_pos, calloc_fn);
    /* 64-bit null check: a W-form cmp truncates pointers whose low 32 bits
       are zero (e.g. an allocation landing exactly at 0xa00000000) into a
       false OOM trap. */
    code_emit(code, a64_cmp_imm_x(R0, 0));
    int32_t alloc_ok = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_brk(0x7f01));               /* OOM: fail fast */
    a64_patch_bcond(code, alloc_ok, code->count);
    code_emit(code, a64_ldp_post(14, 15, SP, 16));
    code_emit(code, a64_ldp_post(12, 13, SP, 16));
    code_emit(code, a64_ldp_post(10, 11, SP, 16));
    code_emit(code, a64_ldp_post(8, 9, SP, 16));
    code_emit(code, a64_ldp_post(6, 7, SP, 16));
    code_emit(code, a64_ldp_post(29, 30, SP, 16));
    code_emit(code, a64_ret());
}

/* Emit the libc-free shim: input x0 = pointer; clobbers x0-x5, x16/x17,
   preserves x6-x15. */
static void codegen_emit_heap_free_shim(Code *code, FunctionPatchList *patches,
                                        int32_t free_fn) {
    code_emit(code, a64_stp_pre(29, 30, SP, -16));
    code_emit(code, a64_stp_pre(6, 7, SP, -16));
    code_emit(code, a64_stp_pre(8, 9, SP, -16));
    code_emit(code, a64_stp_pre(10, 11, SP, -16));
    code_emit(code, a64_stp_pre(12, 13, SP, -16));
    code_emit(code, a64_stp_pre(14, 15, SP, -16));
    int32_t call_pos = code->count;
    code_emit(code, a64_bl(0));
    function_patches_add(patches, call_pos, free_fn);
    code_emit(code, a64_ldp_post(14, 15, SP, 16));
    code_emit(code, a64_ldp_post(12, 13, SP, 16));
    code_emit(code, a64_ldp_post(10, 11, SP, 16));
    code_emit(code, a64_ldp_post(8, 9, SP, 16));
    code_emit(code, a64_ldp_post(6, 7, SP, 16));
    code_emit(code, a64_ldp_post(29, 30, SP, 16));
    code_emit(code, a64_ret());
}

/* Darwin/XNU arm64 syscalls signal failure with the carry flag SET and x0
   holding a POSITIVE errno; Linux returns a negative -errno in x0 with no carry
   convention. The generated file-IO result checks below classify success vs
   failure with a signed compare against 0 (b.ge for open, b.gt for write), so a
   positive Darwin errno would pass as if it were a valid fd / bytes-written and
   drive the write loop into an unterminating decrement (errno taken as progress
   until the remaining count underflows). Normalize the Darwin result to the
   Linux convention: when the carry flag is set (error) negate x0 to -errno; on
   success (carry clear) x0 is unchanged. Emitted right after a file-IO
   svc(0x80); a no-op on the Linux syscall path. */
static void codegen_emit_darwin_errno_normalize(Code *code) {
    if (code->linux_syscalls) return;
    code_emit(code, 0xDA803400u); /* cneg x0, x0, hs : x0 = carry-set ? -x0 : x0 */
}

/* Target-aware syscall emission for the inline file/process/exit codegen.
   Linux aarch64 puts the call number in x8 and traps with `svc #0`; Darwin/XNU
   uses x16 and `svc #0x80`. Linux returns -errno in x0 (so the existing signed
   result checks plus codegen_emit_darwin_errno_normalize work unchanged). These
   helpers gate purely on code->linux_syscalls so a single source builds correct
   syscalls for both the macOS host self-compile and aarch64-linux/android/ohos
   targets. For ops whose argument registers are identical across both ABIs the
   caller stages x0..xN and calls cold_a64_syscall; legacy syscalls dropped from
   the aarch64 generic ABI (open/mkdir/unlink/chmod) get the *at form with a
   prepended AT_FDCWD and the shifted arguments. */
static void cold_a64_syscall(Code *code, int linux_nr, int darwin_nr) {
    if (code->linux_syscalls) {
        code_emit(code, a64_movz_x(8, (uint16_t)linux_nr, 0));
        code_emit(code, a64_svc(0));
    } else {
        code_emit(code, a64_movz_x(16, (uint16_t)darwin_nr, 0));
        code_emit(code, a64_svc(0x80));
    }
}

/* Darwin open(path=x0, flags=x1, mode=x2) -> Linux openat(AT_FDCWD, path, flags, mode). */
static void cold_a64_open_syscall(Code *code) {
    if (code->linux_syscalls) {
        code_emit(code, a64_add_imm(3, 2, 0, true));  /* mode  -> x3 */
        code_emit(code, a64_add_imm(2, 1, 0, true));  /* flags -> x2 */
        code_emit(code, a64_add_imm(1, 0, 0, true));  /* path  -> x1 */
        code_emit(code, a64_movn(R0, 99, 0));         /* AT_FDCWD = -100 -> x0 */
        code_emit(code, a64_movz_x(8, 56, 0));        /* openat */
        code_emit(code, a64_svc(0));
    } else {
        code_emit(code, a64_movz_x(16, 5, 0));
        code_emit(code, a64_svc(0x80));
    }
}

/* Darwin mkdir(path=x0, mode=x1) -> Linux mkdirat(AT_FDCWD, path, mode). */
static void cold_a64_mkdir_syscall(Code *code) {
    if (code->linux_syscalls) {
        code_emit(code, a64_add_imm(2, 1, 0, true));  /* mode -> x2 */
        code_emit(code, a64_add_imm(1, 0, 0, true));  /* path -> x1 */
        code_emit(code, a64_movn(R0, 99, 0));         /* AT_FDCWD -> x0 */
        code_emit(code, a64_movz_x(8, 34, 0));        /* mkdirat */
        code_emit(code, a64_svc(0));
    } else {
        code_emit(code, a64_movz_x(16, 136, 0));
        code_emit(code, a64_svc(0x80));
    }
}

/* Darwin unlink(path=x0) -> Linux unlinkat(AT_FDCWD, path, flags=0). */
static void cold_a64_unlink_syscall(Code *code) {
    if (code->linux_syscalls) {
        code_emit(code, a64_add_imm(1, 0, 0, true));  /* path -> x1 */
        code_emit(code, a64_movn(R0, 99, 0));         /* AT_FDCWD -> x0 */
        code_emit(code, a64_movz_x(2, 0, 0));         /* flags = 0 */
        code_emit(code, a64_movz_x(8, 35, 0));        /* unlinkat */
        code_emit(code, a64_svc(0));
    } else {
        code_emit(code, a64_movz_x(16, 10, 0));
        code_emit(code, a64_svc(0x80));
    }
}

/* Darwin chmod(path=x0, mode=x1) -> Linux fchmodat(AT_FDCWD, path, mode). */
static void cold_a64_chmod_syscall(Code *code) {
    if (code->linux_syscalls) {
        code_emit(code, a64_add_imm(2, 1, 0, true));  /* mode -> x2 */
        code_emit(code, a64_add_imm(1, 0, 0, true));  /* path -> x1 */
        code_emit(code, a64_movn(R0, 99, 0));         /* AT_FDCWD -> x0 */
        code_emit(code, a64_movz_x(8, 53, 0));        /* fchmodat */
        code_emit(code, a64_svc(0));
    } else {
        code_emit(code, a64_movz_x(16, 15, 0));
        code_emit(code, a64_svc(0x80));
    }
}

/* Open flags differ between the two ABIs: stage the O_WRONLY|O_CREAT|O_TRUNC
   write-open mask into x1 with the target's numeric value before cold_a64_open_syscall. */
static void cold_a64_set_write_open_flags(Code *code) {
    if (code->linux_syscalls) {
        code_emit(code, a64_movz_x(R1, 0x0241, 0)); /* linux O_WRONLY|O_CREAT|O_TRUNC */
    } else {
        code_emit(code, a64_movz_x(R1, 0x0601, 0)); /* darwin O_WRONLY|O_CREAT|O_TRUNC */
    }
}

static void codegen_mmap_const(Code *code, int32_t len, int dst_reg, int brk_imm) {
    code_emit(code, a64_movz_x(R1, (uint16_t)len, 0));
    codegen_mmap_len_reg(code, R1, dst_reg, brk_imm);
}

static void codegen_cstring_from_slot(Code *code, BodyIR *body, int32_t slot,
                                      int dst_reg, int brk_imm) {
    codegen_load_str_pair(code, body, slot, R2, R3);
    code_emit(code, a64_add_imm(R1, R3, 1, true));
    /* Save R0-R1 across mmap (see codegen_cstring_from_slot_at_offset) */
    code_emit(code, 0xa9bf07e0);  /* stp x0, x1, [sp, #-16]! */
    codegen_mmap_len_reg(code, R1, dst_reg, brk_imm);
    code_emit(code, 0xa8c107e0);  /* ldp x0, x1, [sp], #16 */
    codegen_load_str_pair(code, body, slot, R2, R3);
    code_emit(code, a64_add_imm(6, dst_reg, 0, true));
    codegen_copy_bytes(code, R2, R3, 6);
    code_emit(code, a64_movz(5, 0, 0));
    code_emit(code, a64_strb_imm(5, 6, 0));
}

static void codegen_cstring_literal(Code *code, int dst_reg, const char *text) {
    int32_t adr_pos = code->count;
    code_emit(code, a64_adr(dst_reg, 0));
    int32_t skip_pos = code->count;
    code_emit(code, a64_b(0));
    int32_t data_offset = code_append_bytes(code, text, (int32_t)strlen(text) + 1);
    int32_t after_data = code->count;
    code->words[adr_pos] = a64_adr(dst_reg, data_offset - adr_pos * 4);
    a64_patch_b(code, skip_pos, after_data);
}

static bool cold_fn_is_puts(FnDef *fn) {
    if (!fn) return false;
    Span name = fn->link_name.len > 0 ? fn->link_name : fn->name;
    if (span_eq(name, "puts")) return true;
    if (span_eq(name, "system.puts")) return true;
    return false;
}

static bool cold_fn_is_runtime_atomic_add_i32(FnDef *fn) {
    if (!fn) return false;
    Span name = fn->link_name.len > 0 ? span_trim(fn->link_name) : fn->name;
    return span_eq(name, "__cheng_runtime_atomic_add_i32") ||
           span_eq(name, "___cheng_runtime_atomic_add_i32");
}

