        x64_jcc_rel8(x, CC_G, 0);
        x64_int3(x);
        x->buf[sis_lt + 1] = (uint8_t)(x->len - (sis_lt + 2));
        x64_movsxd_r64_r32(x, 3, 3);
        x64_add_r64_r64(x, 1, 3);
