static bool cold_driver_safe_target_enabled(const char *target) {
    return target && strcmp(target, "riscv64-unknown-none-elf") == 0;
}

static bool cold_driver_safe_source_enabled(Span source) {
    return cold_span_contains_cstr(source, "@profile(\"driver_safe\")") ||
           cold_span_contains_cstr(source, "@profile(\"driver_safe\"") ||
           cold_span_contains_cstr(source, "@profile('driver_safe')");
}

static bool cold_driver_safe_line_is_public_fn_with_pointer(Span trimmed) {
    Span name = {0};
    if (!cold_parse_fn_name(trimmed, &name)) return false;
    if (name.len <= 0 || name.ptr[0] < 'A' || name.ptr[0] > 'Z') return false;
    return cold_span_contains_cstr(trimmed, ": ptr") ||
           cold_span_contains_cstr(trimmed, "): ptr") ||
           cold_span_contains_cstr(trimmed, ": void*") ||
           cold_span_contains_cstr(trimmed, "): void*") ||
           cold_span_contains_cstr(trimmed, ": T*") ||
           cold_span_contains_cstr(trimmed, "): T*") ||
           cold_span_contains_cstr(trimmed, ": ref ") ||
           cold_span_contains_cstr(trimmed, "): ref ");
}

static bool cold_driver_safe_line_constructs_trusted_address(Span trimmed) {
    return cold_span_contains_cstr(trimmed, "TrustedPhysAddr(") ||
           cold_span_contains_cstr(trimmed, "TrustedVirtAddr(") ||
           cold_span_contains_cstr(trimmed, "TrustedMmioReg");
}

static bool cold_driver_safe_line_allocates(Span trimmed) {
    return cold_span_contains_cstr(trimmed, "add(") ||
           cold_span_contains_cstr(trimmed, "new(") ||
           cold_span_contains_cstr(trimmed, "Fmt\"") ||
           cold_span_contains_cstr(trimmed, "Fmt\"\"\"") ||
           (cold_span_contains_cstr(trimmed, "var ") &&
            cold_span_contains_cstr(trimmed, "[]"));
}

static bool cold_driver_safe_line_blocks_or_ordinary_locks(Span trimmed) {
    return cold_span_contains_cstr(trimmed, "Mutex") ||
           cold_span_contains_cstr(trimmed, ".lock(") ||
           cold_span_contains_cstr(trimmed, "ReadFile") ||
           cold_span_contains_cstr(trimmed, "WriteFile") ||
           cold_span_contains_cstr(trimmed, "sleep(");
}

static bool cold_driver_safe_line_has_mmio_violation(Span trimmed) {
    return cold_span_contains_cstr(trimmed, "MmioReg[") ||
           cold_span_contains_cstr(trimmed, ".value =") ||
           cold_span_contains_cstr(trimmed, ".addr =");
}

static void cold_driver_safe_finish_stats(ColdCompileStats *stats) {
    if (!stats || !stats->driver_safe_profile) return;
    stats->no_alloc_verified = stats->no_alloc_violations == 0 ? 1 : 0;
    stats->interrupt_safe_verified = stats->interrupt_violations == 0 ? 1 : 0;
    if (stats->driver_safe_error[0] == '\0') {
        if (stats->public_pointer_violations > 0) {
            snprintf(stats->driver_safe_error, sizeof(stats->driver_safe_error),
                     "driver_safe public pointer violation");
        } else if (stats->trusted_abi_violations > 0) {
            snprintf(stats->driver_safe_error, sizeof(stats->driver_safe_error),
                     "driver_safe trusted abi violation");
        } else if (stats->no_alloc_violations > 0) {
            snprintf(stats->driver_safe_error, sizeof(stats->driver_safe_error),
                     "driver_safe no_alloc violation");
        } else if (stats->interrupt_violations > 0) {
            snprintf(stats->driver_safe_error, sizeof(stats->driver_safe_error),
                     "driver_safe interrupt violation");
        } else if (stats->mmio_violations > 0) {
            snprintf(stats->driver_safe_error, sizeof(stats->driver_safe_error),
                     "driver_safe mmio violation");
        } else if (stats->dma_violations > 0) {
            snprintf(stats->driver_safe_error, sizeof(stats->driver_safe_error),
                     "driver_safe dma violation");
        }
    }
}

static bool cold_driver_safe_has_violations(const ColdCompileStats *stats) {
    return stats && stats->driver_safe_profile &&
           (stats->public_pointer_violations > 0 ||
            stats->trusted_abi_violations > 0 ||
            stats->no_alloc_violations > 0 ||
            stats->interrupt_violations > 0 ||
            stats->mmio_violations > 0 ||
            stats->dma_violations > 0);
}

static void cold_driver_safe_scan_source(ColdCompileStats *stats,
                                         const char *source_path,
                                         const char *target) {
    if (!stats || !source_path || source_path[0] == '\0') return;
    Span source = source_open(source_path);
    if (source.len <= 0) return;
    bool enabled = cold_driver_safe_target_enabled(target) ||
                   cold_driver_safe_source_enabled(source);
    if (!enabled) {
        munmap((void *)source.ptr, (size_t)source.len);
        return;
    }
    stats->driver_safe_profile = 1;
    stats->driver_safe_source_count = 1;
    bool pending_trusted_abi = false;
    bool pending_no_alloc = false;
    bool pending_interrupt = false;
    bool in_function = false;
    bool current_trusted_abi = false;
    bool current_no_alloc = false;
    bool current_interrupt = false;
    bool current_dma_device = false;
    bool current_no_alloc_reported = false;
    bool current_interrupt_reported = false;
    int32_t start = 0;
    for (int32_t pos = 0; pos <= source.len; pos++) {
        if (pos < source.len && source.ptr[pos] != '\n') continue;
        int32_t end = pos;
        if (end > start && source.ptr[end - 1] == '\r') end--;
        Span line = {source.ptr + start, end - start};
        Span trimmed = span_trim(line);
        start = pos + 1;
        if (trimmed.len <= 0) continue;
        if (cold_span_starts_with(trimmed, "@trusted_abi")) {
            pending_trusted_abi = true;
            continue;
        }
        if (cold_span_starts_with(trimmed, "@no_alloc")) {
            pending_no_alloc = true;
            continue;
        }
        if (cold_span_starts_with(trimmed, "@interrupt_handler")) {
            pending_interrupt = true;
            pending_no_alloc = true;
            continue;
        }
        Span fn_name = {0};
        if (cold_parse_fn_name(trimmed, &fn_name)) {
            in_function = true;
            current_trusted_abi = pending_trusted_abi;
            current_no_alloc = pending_no_alloc;
            current_interrupt = pending_interrupt;
            current_dma_device = cold_span_contains_cstr(trimmed, "DmaBufferDevice");
            current_no_alloc_reported = false;
            current_interrupt_reported = false;
            pending_trusted_abi = false;
            pending_no_alloc = false;
            pending_interrupt = false;
            if (cold_driver_safe_line_is_public_fn_with_pointer(trimmed)) {
                stats->public_pointer_violations++;
            }
        } else if (cold_line_top_level(line) &&
                   !cold_span_starts_with(trimmed, "@") &&
                   !cold_span_starts_with(trimmed, "import ")) {
            in_function = false;
            current_trusted_abi = false;
            current_no_alloc = false;
            current_interrupt = false;
            current_dma_device = false;
            current_no_alloc_reported = false;
            current_interrupt_reported = false;
        }
        if (cold_driver_safe_line_constructs_trusted_address(trimmed) &&
            !current_trusted_abi) {
            stats->trusted_abi_violations++;
        }
        if (current_no_alloc && !current_no_alloc_reported &&
            cold_driver_safe_line_allocates(trimmed)) {
            stats->no_alloc_violations++;
            current_no_alloc_reported = true;
        }
        if (current_interrupt &&
            !current_interrupt_reported &&
            (cold_driver_safe_line_allocates(trimmed) ||
             cold_driver_safe_line_blocks_or_ordinary_locks(trimmed))) {
            stats->interrupt_violations++;
            current_interrupt_reported = true;
        }
        if (cold_driver_safe_line_has_mmio_violation(trimmed)) {
            stats->mmio_violations++;
        }
        if (in_function && cold_span_contains_cstr(trimmed, "DmaBufferDevice")) {
            current_dma_device = true;
        }
        if (current_dma_device && cold_span_contains_cstr(trimmed, ".payload")) {
            stats->dma_violations++;
        }
    }
    munmap((void *)source.ptr, (size_t)source.len);
    cold_driver_safe_finish_stats(stats);
}

static void cold_driver_safe_merge_stats(ColdCompileStats *dst,
                                         const ColdCompileStats *src) {
    if (!dst || !src || !src->driver_safe_profile) return;
    dst->driver_safe_profile = src->driver_safe_profile;
    dst->driver_safe_source_count = src->driver_safe_source_count;
    dst->public_pointer_violations = src->public_pointer_violations;
    dst->trusted_abi_violations = src->trusted_abi_violations;
    dst->no_alloc_violations = src->no_alloc_violations;
    dst->interrupt_violations = src->interrupt_violations;
    dst->mmio_violations = src->mmio_violations;
    dst->dma_violations = src->dma_violations;
    dst->no_alloc_verified = src->no_alloc_verified;
    dst->interrupt_safe_verified = src->interrupt_safe_verified;
    snprintf(dst->driver_safe_error, sizeof(dst->driver_safe_error),
             "%s", src->driver_safe_error);
}

static void cold_print_exec_phase_report(FILE *file, ColdCompileStats *stats) {
    unsigned long long parse_us = stats ? (unsigned long long)stats->parse_us : 0ULL;
    unsigned long long codegen_us = stats ? (unsigned long long)stats->codegen_us : 0ULL;
    unsigned long long emit_us = stats ? (unsigned long long)stats->emit_us : 0ULL;
    unsigned long long total_us = stats ? (unsigned long long)stats->elapsed_us : 0ULL;
    fprintf(file, "exec_phase_parse_us=%llu\n", parse_us);
    fprintf(file, "exec_phase_codegen_us=%llu\n", codegen_us);
    fprintf(file, "exec_phase_direct_object_emit_us=%llu\n", emit_us);
    fprintf(file, "exec_phase_total_us=%llu\n", total_us);
}

static void cold_print_resource_report(FILE *file) {
    struct rusage usage;
    if (getrusage(RUSAGE_SELF, &usage) != 0) {
        fputs("report_cpu_ms=-1\n", file);
        fputs("report_rss_bytes=-1\n", file);
        return;
    }
    long long cpu_ms =
        (long long)usage.ru_utime.tv_sec * 1000LL +
        (long long)usage.ru_utime.tv_usec / 1000LL +
        (long long)usage.ru_stime.tv_sec * 1000LL +
        (long long)usage.ru_stime.tv_usec / 1000LL;
#if defined(__APPLE__)
    long long rss_bytes = (long long)usage.ru_maxrss;
#else
    long long rss_bytes = (long long)usage.ru_maxrss * 1024LL;
#endif
    fprintf(file, "report_cpu_ms=%lld\n", cpu_ms);
    fprintf(file, "report_rss_bytes=%lld\n", rss_bytes);
}

static uint64_t cold_rusage_cpu_us(struct rusage *usage) {
    if (!usage) return 0;
    return (uint64_t)usage->ru_utime.tv_sec * 1000000ULL +
           (uint64_t)usage->ru_utime.tv_usec +
           (uint64_t)usage->ru_stime.tv_sec * 1000000ULL +
           (uint64_t)usage->ru_stime.tv_usec;
}

static uint64_t cold_process_tree_cpu_us(void) {
    struct rusage self_usage;
    struct rusage child_usage;
    uint64_t total = 0;
    if (getrusage(RUSAGE_SELF, &self_usage) == 0) {
        total += cold_rusage_cpu_us(&self_usage);
    }
    if (getrusage(RUSAGE_CHILDREN, &child_usage) == 0) {
        total += cold_rusage_cpu_us(&child_usage);
    }
    return total;
}

static int64_t cold_hw_sysctl_i64(const char *name) {
#if defined(__APPLE__)
    int64_t value = 0;
    size_t size = sizeof(value);
    if (sysctlbyname(name, &value, &size, NULL, 0) == 0 && size > 0) return value;
    int32_t value32 = 0;
    size = sizeof(value32);
    if (sysctlbyname(name, &value32, &size, NULL, 0) == 0 && size > 0) return value32;
#else
    (void)name;
#endif
    return 0;
}

static int32_t cold_hw_cpu_count(const char *name, long fallback_name) {
    int64_t value = cold_hw_sysctl_i64(name);
    if (value <= 0 && fallback_name > 0) value = sysconf((int)fallback_name);
    if (value <= 0) value = 1;
    if (value > INT32_MAX) value = INT32_MAX;
    return (int32_t)value;
}

static uint64_t cold_hw_memory_bytes(void) {
    int64_t value = cold_hw_sysctl_i64("hw.memsize");
    if (value > 0) return (uint64_t)value;
#ifdef _SC_PHYS_PAGES
    long pages = sysconf(_SC_PHYS_PAGES);
    long page_size = sysconf(_SC_PAGESIZE);
    if (pages > 0 && page_size > 0) return (uint64_t)pages * (uint64_t)page_size;
#endif
    return 0;
}

static uint64_t cold_div_ceil_u64(uint64_t a, uint64_t b) {
    if (b == 0) return 0;
    return a / b + ((a % b) != 0 ? 1ULL : 0ULL);
}

static uint64_t cold_lines_per_second(uint64_t lines, uint64_t elapsed_us) {
    if (lines == 0 || elapsed_us == 0) return 0;
    return cold_div_ceil_u64(lines * 1000000ULL, elapsed_us);
}

static void cold_stats_set_runtime_provider_bundle(ColdCompileStats *stats,
                                                   const char *bundle,
                                                   bool auto_selected,
                                                   int32_t object_count) {
    if (!stats || !bundle || bundle[0] == '\0') return;
    snprintf(stats->runtime_provider_bundle,
             sizeof(stats->runtime_provider_bundle),
             "%s",
             bundle);
    stats->runtime_provider_bundle_auto = auto_selected ? 1 : 0;
    stats->runtime_provider_bundle_object_count = object_count;
}

static void cold_stats_attach_compile_input(ColdCompileStats *stats,
                                            const char *source_path,
                                            const char *runtime_provider_bundle) {
    if (!stats) return;
    static const char *codex_app_server_provider_sources[] = {
        "codex/src/core/runtime/darwin_os_provider.cheng",
        "codex/src/core/runtime/encoding_provider.cheng",
        "codex/src/core/runtime/process_provider.cheng",
        "codex/src/core/runtime/sqlite_provider.cheng",
        "codex/src/core/runtime/http_provider.cheng",
        "codex/src/core/runtime/socket_provider.cheng",
        "codex/src/core/runtime/model_provider.cheng",
        "codex/src/core/runtime/app_server_compat_provider.cheng",
    };
    const char **extra_sources = NULL;
    int32_t extra_source_count = 0;
    if (runtime_provider_bundle && strcmp(runtime_provider_bundle, "codex-app-server") == 0) {
        extra_sources = codex_app_server_provider_sources;
        extra_source_count = (int32_t)(sizeof(codex_app_server_provider_sources) /
                                       sizeof(codex_app_server_provider_sources[0]));
    }
    ColdSourceLineStats line_stats =
        cold_theory_source_tree_stats(source_path, extra_sources, extra_source_count);
    stats->compile_input_source_files = line_stats.file_count;
    stats->compile_input_source_lines = line_stats.line_count;
    stats->compile_input_source_bytes = line_stats.byte_count;
}

static void cold_stats_finalize_compile_theory(ColdCompileStats *stats) {
    if (!stats) return;
    if (stats->compile_real_cpu_us > 0 && stats->hardware_logical_cpus > 0) return;
    stats->hardware_logical_cpus = cold_hw_cpu_count("hw.logicalcpu", _SC_NPROCESSORS_ONLN);
    stats->hardware_physical_cpus = cold_hw_cpu_count("hw.physicalcpu", _SC_NPROCESSORS_ONLN);
    stats->hardware_perf_cpus = (int32_t)cold_hw_sysctl_i64("hw.perflevel0.logicalcpu");
    stats->hardware_efficiency_cpus = (int32_t)cold_hw_sysctl_i64("hw.perflevel1.logicalcpu");
    stats->hardware_memory_bytes = cold_hw_memory_bytes();
    stats->compile_real_cpu_us = cold_process_tree_cpu_us();
    if (stats->compile_real_cpu_us > 0 && stats->hardware_logical_cpus > 0) {
        stats->compile_theory_parallel_limit_us =
            cold_div_ceil_u64(stats->compile_real_cpu_us,
                              (uint64_t)stats->hardware_logical_cpus);
    }
    stats->compile_real_lines_per_second =
        cold_lines_per_second(stats->compile_input_source_lines, stats->elapsed_us);
    stats->compile_theory_lines_per_second =
        cold_lines_per_second(stats->compile_input_source_lines,
                              stats->compile_theory_parallel_limit_us);
}

static void cold_print_ratio_milli(FILE *file,
                                   const char *key,
                                   uint64_t numerator,
                                   uint64_t denominator) {
    if (denominator == 0) {
        fprintf(file, "%s=0.000\n", key);
        return;
    }
    uint64_t milli = (numerator * 1000ULL) / denominator;
    fprintf(file, "%s=%llu.%03llu\n",
            key,
            (unsigned long long)(milli / 1000ULL),
            (unsigned long long)(milli % 1000ULL));
}

static void cold_print_ratio_percent_milli(FILE *file,
                                           const char *key,
                                           uint64_t numerator,
                                           uint64_t denominator) {
    if (denominator == 0) {
        fprintf(file, "%s=0.000\n", key);
        return;
    }
    uint64_t milli = (numerator * 100000ULL) / denominator;
    fprintf(file, "%s=%llu.%03llu\n",
            key,
            (unsigned long long)(milli / 1000ULL),
            (unsigned long long)(milli % 1000ULL));
}

static void cold_print_compile_theory_report(FILE *file, ColdCompileStats *stats) {
    if (!file || !stats) return;
    if (stats->elapsed_us == 0 && cold_system_link_exec_entry_us > 0) {
        uint64_t now = cold_now_us();
        if (now > cold_system_link_exec_entry_us) stats->elapsed_us = now - cold_system_link_exec_entry_us;
    }
    cold_stats_finalize_compile_theory(stats);
    fputs("compile_theory_model=measured_cpu_work_per_line_div_logical_cpu\n", file);
    fprintf(file, "compile_input_source_file_count=%llu\n",
            (unsigned long long)stats->compile_input_source_files);
    fprintf(file, "compile_input_source_line_count=%llu\n",
            (unsigned long long)stats->compile_input_source_lines);
    fprintf(file, "compile_input_source_byte_count=%llu\n",
            (unsigned long long)stats->compile_input_source_bytes);
    fprintf(file, "compile_hardware_logical_cpus=%d\n", stats->hardware_logical_cpus);
    fprintf(file, "compile_hardware_physical_cpus=%d\n", stats->hardware_physical_cpus);
    fprintf(file, "compile_hardware_perf_cpus=%d\n", stats->hardware_perf_cpus);
    fprintf(file, "compile_hardware_efficiency_cpus=%d\n", stats->hardware_efficiency_cpus);
    fprintf(file, "compile_hardware_memory_bytes=%llu\n",
            (unsigned long long)stats->hardware_memory_bytes);
    cold_print_elapsed_ms(file, "compile_real_elapsed_ms", stats->elapsed_us);
    cold_print_elapsed_ms(file, "compile_real_cpu_ms", stats->compile_real_cpu_us);
    cold_print_elapsed_ms(file, "compile_theory_parallel_limit_ms",
                          stats->compile_theory_parallel_limit_us);
    fprintf(file, "compile_real_lines_per_second=%llu\n",
            (unsigned long long)stats->compile_real_lines_per_second);
    fprintf(file, "compile_theory_lines_per_second=%llu\n",
            (unsigned long long)stats->compile_theory_lines_per_second);
    cold_print_ratio_milli(file, "compile_real_over_theory_x",
                           stats->elapsed_us,
                           stats->compile_theory_parallel_limit_us);
    cold_print_ratio_percent_milli(file, "compile_real_over_theory_percent",
                                   stats->elapsed_us,
                                   stats->compile_theory_parallel_limit_us);
}

static void cold_print_compile_theory_stdout(ColdCompileStats *stats) {
    if (!stats) return;
    if (stats->elapsed_us == 0 && cold_system_link_exec_entry_us > 0) {
        uint64_t now = cold_now_us();
        if (now > cold_system_link_exec_entry_us) stats->elapsed_us = now - cold_system_link_exec_entry_us;
    }
    cold_stats_finalize_compile_theory(stats);
    printf("compile_input_source_line_count=%llu\n",
           (unsigned long long)stats->compile_input_source_lines);
    printf("compile_hardware_logical_cpus=%d\n", stats->hardware_logical_cpus);
    cold_print_elapsed_ms(stdout, "compile_theory_parallel_limit_ms",
                          stats->compile_theory_parallel_limit_us);
    cold_print_elapsed_ms(stdout, "compile_real_elapsed_ms", stats->elapsed_us);
    cold_print_elapsed_ms(stdout, "compile_real_cpu_ms", stats->compile_real_cpu_us);
    cold_print_ratio_milli(stdout, "compile_real_over_theory_x",
                           stats->elapsed_us,
                           stats->compile_theory_parallel_limit_us);
    cold_print_ratio_percent_milli(stdout, "compile_real_over_theory_percent",
                                   stats->elapsed_us,
                                   stats->compile_theory_parallel_limit_us);
}

static void cold_collect_body_stats(Symbols *symbols, BodyIR **function_bodies, int32_t function_count,
                                    ColdCompileStats *stats) {
    if (!stats) return;
    /* Count total non-fallback functions and compute canonical hashes */
    uint64_t *canonical_hashes = 0;
    int32_t canonical_cap = 0;
    int32_t canonical_count = 0;
    for (int32_t i = 0; i < function_count; i++) {
        BodyIR *body = function_bodies[i];
        if (!body || (uintptr_t)body < 4096 || body->has_fallback) continue;
        stats->total_function_count++;
        uint64_t h = cold_body_ir_canonical_hash(body);
        bool seen = false;
        for (int32_t j = 0; j < canonical_count; j++) {
            if (canonical_hashes[j] == h) { seen = true; break; }
        }
        if (!seen) {
            if (canonical_count >= canonical_cap) {
                int32_t new_cap = canonical_cap == 0 ? 64 : canonical_cap * 2;
                uint64_t *new_h = realloc(canonical_hashes, (size_t)new_cap * sizeof(uint64_t));
                if (!new_h) { free(canonical_hashes); return; }
                canonical_hashes = new_h;
                canonical_cap = new_cap;
            }
            canonical_hashes[canonical_count++] = h;
        }
    }
    stats->canonical_hash_count = canonical_count;
    free(canonical_hashes);

    /* Compute normalized hash count (with rewrite rules) */
    uint64_t *norm_hashes = 0;
    int32_t norm_cap = 0;
    int32_t norm_count = 0;
    for (int32_t i = 0; i < function_count; i++) {
        BodyIR *body = function_bodies[i];
        if (!body || (uintptr_t)body < 4096 || body->has_fallback) continue;
        uint64_t h = cold_body_ir_canonical_hash_normalized(body);
        bool seen = false;
        for (int32_t j = 0; j < norm_count; j++) {
            if (norm_hashes[j] == h) { seen = true; break; }
        }
        if (!seen) {
            if (norm_count >= norm_cap) {
                int32_t new_cap = norm_cap == 0 ? 64 : norm_cap * 2;
                uint64_t *new_h = realloc(norm_hashes, (size_t)new_cap * sizeof(uint64_t));
                if (!new_h) { free(norm_hashes); norm_count = 0; break; }
                norm_hashes = new_h;
                norm_cap = new_cap;
            }
            norm_hashes[norm_count++] = h;
        }
    }
    stats->canonical_normalized_count = norm_count;
    free(norm_hashes);

    for (int32_t i = 0; i < function_count; i++) {
        BodyIR *body = function_bodies[i];
        if (!body || (uintptr_t)body < 4096 || body->has_fallback) continue;
        int32_t frame_size = align_i32(body->frame_size, 16);
        if (frame_size > stats->max_frame_size) {
            stats->max_frame_size = frame_size;
            stats->max_frame_function[0] = '\0';
            if (symbols && i < symbols->function_count) {
                Span fn_name = symbols->functions[i].name;
                cold_span_copy(stats->max_frame_function,
                               sizeof(stats->max_frame_function),
                               fn_name);
            }
        }
        if (symbols && i < symbols->function_count) {
            Span fn_name = symbols->functions[i].name;
            if (span_eq(fn_name, "BackendDriverDispatchMinRunSystemLinkExecConcretePlanAfterCsg")) {
                stats->after_csg_frame_size = frame_size;
            } else if (span_eq(fn_name, "BackendDriverDispatchMinRunSystemLinkExecConcretePlanAfterSourceBundle")) {
                stats->after_source_bundle_frame_size = frame_size;
            }
        }
        stats->op_count += body->op_count;
        stats->block_count += body->block_count;
        stats->switch_count += body->switch_count;
        /* count parameters and ABI placement */
        int32_t fn_reg = 0;
        int32_t fn_stack = 0;
        if (!body->slot_kind) continue;
        for (int32_t p = 0; p < body->param_count; p++) {
            int32_t slot = body->param_slot[p];
            if (slot < 0 || slot >= body->slot_count) continue;
            int32_t kind = body->slot_kind[slot];
            int32_t size = body->slot_size[slot];
            int32_t base_reg = -1;
            int32_t stack_offset = -1;
            bool in_regs = cold_abi_place_arg(&fn_reg, &fn_stack, kind, size,
                                              &base_reg, &stack_offset);
            stats->param_count++;
            if (in_regs) stats->abi_register_params++;
            else stats->abi_stack_params++;
        }
        for (int32_t op = 0; op < body->op_count; op++) {
            if (body->op_kind[op] == BODY_OP_CALL_I32 ||
                body->op_kind[op] == BODY_OP_CALL_COMPOSITE) {
                stats->call_count++;
            }
        }
    }
}

/* ================================================================
 * CSG canonical primary-object text reader
 * ================================================================ */

typedef struct ColdCsgPrimaryFunction {
    uint32_t item_id;
    int32_t word_offset;
    int32_t word_count;
    Span symbol_name;
    Span body_kind;
} ColdCsgPrimaryFunction;

typedef struct ColdCsgPrimaryReloc {
    uint32_t source_item_id;
    int32_t word_offset;
    Span target_symbol;
} ColdCsgPrimaryReloc;

typedef struct ColdCsgPrimaryData {
    uint32_t item_id;
    Span symbol_name;
    uint32_t align;
    const uint8_t *bytes;
    int32_t byte_count;
} ColdCsgPrimaryData;

typedef struct ColdCsgPrimaryDataReloc {
    uint32_t source_item_id;
    int32_t word_offset;
    uint32_t reloc_kind;
    int32_t addend;
    Span target_symbol;
} ColdCsgPrimaryDataReloc;

typedef struct ColdCsgPrimaryObject {
    Span target_triple;
    Span object_format;
    Span entry_symbol;
    ColdCsgPrimaryFunction *functions;
    int32_t function_count;
    uint32_t *words;
    int32_t word_count;
    ColdCsgPrimaryReloc *relocs;
    int32_t reloc_count;
    ColdCsgPrimaryData *data;
    int32_t data_count;
    ColdCsgPrimaryDataReloc *data_relocs;
    int32_t data_reloc_count;
} ColdCsgPrimaryObject;

typedef struct ColdCsgTextRecord {
    uint16_t kind;
    int32_t payload_bytes;
    const uint8_t *payload_hex;
} ColdCsgTextRecord;

static int32_t cold_csg_hex_value(uint8_t ch) {
    if (ch >= '0' && ch <= '9') return (int32_t)(ch - '0');
    if (ch >= 'A' && ch <= 'F') return (int32_t)(ch - 'A' + 10);
    if (ch >= 'a' && ch <= 'f') return (int32_t)(ch - 'a' + 10);
    return -1;
}

static bool cold_csg_read_fixed_hex(const uint8_t *ptr, int32_t len, uint32_t *out) {
    if (!ptr || len <= 0 || len > 8) return false;
    uint32_t value = 0;
    for (int32_t i = 0; i < len; i++) {
        int32_t digit = cold_csg_hex_value(ptr[i]);
        if (digit < 0) return false;
        value = (value << 4) | (uint32_t)digit;
    }
    *out = value;
    return true;
}

static bool cold_csg_hex_byte(const uint8_t *payload_hex,
                                 int32_t payload_bytes,
                                 int32_t byte_index,
                                 uint8_t *out) {
    if (!payload_hex || byte_index < 0 || byte_index >= payload_bytes) return false;
    int32_t hi = cold_csg_hex_value(payload_hex[byte_index * 2]);
    int32_t lo = cold_csg_hex_value(payload_hex[byte_index * 2 + 1]);
    if (hi < 0 || lo < 0) return false;
    *out = (uint8_t)((hi << 4) | lo);
    return true;
}

static bool cold_csg_hardfail(const char *reason, int32_t offset) {
    fprintf(stderr, "cold_csg: %s at offset %d\n", reason, offset);
    return false;
}

/* Canonical CHENG_CSG header record (kind=0) contract.
 * Fixed 126-byte payload immediately after the magic line:
 *   schema_version:u32 abi_version:u32 pointer_width:u8 endian:u8
 *   producer_version:u32 target_triple:bytes32 entry_symbol:bytes64
 *   schema_hash:u64 plan_hash:u64
 * schema_hash = FNV-1a64 over cold_csg_schema_desc.
 * plan_hash = FNV-1a64 over every serialized file byte after the header
 * record line (i.e. all payload record lines as written). */
#define COLD_CSG_SCHEMA_VERSION 1u
#define COLD_CSG_ABI_VERSION 1u
#define COLD_CSG_PRODUCER_VERSION 1u
#define COLD_CSG_POINTER_WIDTH 8u
#define COLD_CSG_ENDIAN_LITTLE 1u
#define COLD_CSG_HEADER_TRIPLE_BYTES 32
#define COLD_CSG_HEADER_ENTRY_BYTES 64
#define COLD_CSG_HEADER_PAYLOAD_BYTES 126
#define COLD_CSG_FNV64_BASIS 1469598103934665603ULL

static const char cold_csg_schema_desc[] =
    "header(0){schema_version:u32,abi_version:u32,pointer_width:u8,endian:u8,"
    "producer_version:u32,target_triple:bytes32,entry_symbol:bytes64,"
    "schema_hash:u64,plan_hash:u64};"
    "target(1){triple:str};"
    "object_format(2){format:str};"
    "entry(3){symbol:str};"
    "function(4){item_id:u32,word_offset:u32,word_count:u32,symbol:str,body_kind:str};"
    "word(5){word:u32};"
    "reloc(6){source_item_id:u32,word_offset:u32,target_symbol:str};"
    "data(7){item_id:u32,symbol:str,align:u32,byte_count:u32,bytes:raw};"
    "data_reloc(8){source_item_id:u32,word_offset:u32,reloc_kind:u32,addend:u32,target_symbol:str};"
    "call_edge(9){source_item_id:u32,target_symbol:str}";

static uint64_t cold_csg_schema_hash(void) {
    Span desc = {(const uint8_t *)cold_csg_schema_desc,
                 (int32_t)(sizeof(cold_csg_schema_desc) - 1)};
    return cold_fnv1a64_update(COLD_CSG_FNV64_BASIS, desc);
}

static uint64_t cold_csg_plan_hash(Span text, int32_t payload_start) {
    if (payload_start < 0 || payload_start > text.len) return COLD_CSG_FNV64_BASIS;
    Span payload = {text.ptr + payload_start, text.len - payload_start};
    return cold_fnv1a64_update(COLD_CSG_FNV64_BASIS, payload);
}

static bool cold_csg_read_payload_u32le(const uint8_t *payload_hex,
                                           int32_t payload_bytes,
                                           int32_t *pos,
                                           uint32_t *out) {
    if (!pos || !out || *pos < 0 || *pos > payload_bytes - 4) return false;
    uint8_t b0, b1, b2, b3;
    if (!cold_csg_hex_byte(payload_hex, payload_bytes, *pos + 0, &b0)) return false;
    if (!cold_csg_hex_byte(payload_hex, payload_bytes, *pos + 1, &b1)) return false;
    if (!cold_csg_hex_byte(payload_hex, payload_bytes, *pos + 2, &b2)) return false;
    if (!cold_csg_hex_byte(payload_hex, payload_bytes, *pos + 3, &b3)) return false;
    *out = (uint32_t)b0 | ((uint32_t)b1 << 8) |
           ((uint32_t)b2 << 16) | ((uint32_t)b3 << 24);
    *pos += 4;
    return true;
}

static bool cold_csg_read_payload_u64le(const uint8_t *payload_hex,
                                           int32_t payload_bytes,
                                           int32_t *pos,
                                           uint64_t *out) {
    uint32_t lo, hi;
    if (!cold_csg_read_payload_u32le(payload_hex, payload_bytes, pos, &lo)) return false;
    if (!cold_csg_read_payload_u32le(payload_hex, payload_bytes, pos, &hi)) return false;
    *out = (uint64_t)lo | ((uint64_t)hi << 32);
    return true;
}

static bool cold_csg_read_payload_string(const uint8_t *payload_hex,
                                            int32_t payload_bytes,
                                            int32_t *pos,
                                            Arena *arena,
                                            int32_t payload_file_offset,
                                            Span *out) {
    int32_t len_pos = pos ? *pos : 0;
    uint32_t len_u32;
    if (!cold_csg_read_payload_u32le(payload_hex, payload_bytes, pos, &len_u32)) {
        return cold_csg_hardfail("string length out of bounds",
                                    payload_file_offset + len_pos * 2);
    }
    if (len_u32 > (uint32_t)INT32_MAX) {
        return cold_csg_hardfail("string length out of bounds",
                                    payload_file_offset + len_pos * 2);
    }
    int32_t len = (int32_t)len_u32;
    if (*pos < 0 || len < 0 || *pos > payload_bytes - len) {
        return cold_csg_hardfail("string length out of bounds",
                                    payload_file_offset + len_pos * 2);
    }
    char *buf = arena_alloc(arena, (size_t)len + 1);
    for (int32_t i = 0; i < len; i++) {
        uint8_t byte;
        if (!cold_csg_hex_byte(payload_hex, payload_bytes, *pos + i, &byte)) return false;
        buf[i] = (char)byte;
    }
    buf[len] = '\0';
    *pos += len;
    *out = (Span){(const uint8_t *)buf, len};
    return true;
}

static bool cold_csg_next_text_record(Span text,
                                         int32_t *pos,
                                         ColdCsgTextRecord *record) {
    if (!pos || !record || *pos < 0 || *pos >= text.len) return false;
    int32_t start = *pos;
    int32_t end = start;
    while (end < text.len && text.ptr[end] != '\n') end++;
    int32_t line_len = end - start;
    *pos = end < text.len ? end + 1 : end;
    if (line_len < 13) {
        return cold_csg_hardfail(end >= text.len
                                     ? "record length prefix beyond buffer end"
                                     : "record header truncated",
                                 start);
    }
    if (text.ptr[start] != 'R') return false;
    uint32_t kind = 0;
    uint32_t payload_bytes = 0;
    if (!cold_csg_read_fixed_hex(text.ptr + start + 1, 4, &kind)) return false;
    if (!cold_csg_read_fixed_hex(text.ptr + start + 5, 8, &payload_bytes)) return false;
    if (kind > UINT16_MAX) {
        return cold_csg_hardfail("unknown record kind", start);
    }
    if (payload_bytes > (uint32_t)(INT32_MAX / 2)) {
        return cold_csg_hardfail("record payload truncated", start);
    }
    int32_t payload_len = (int32_t)payload_bytes;
    if (payload_len > (INT32_MAX - 13) / 2) {
        return cold_csg_hardfail("record payload truncated", start);
    }
    if (line_len != 13 + payload_len * 2) {
        return cold_csg_hardfail(line_len < 13 + payload_len * 2
                                     ? "record payload truncated"
                                     : "record length mismatch",
                                 start);
    }
    for (int32_t i = 0; i < payload_len * 2; i++) {
        if (cold_csg_hex_value(text.ptr[start + 13 + i]) < 0) return false;
    }
    record->kind = (uint16_t)kind;
    record->payload_bytes = payload_len;
    record->payload_hex = text.ptr + start + 13;
    return true;
}

static bool cold_csg_validate_header_record(Span text, int32_t *pos) {
    int32_t header_start = *pos;
    if (header_start >= text.len) {
        return cold_csg_hardfail("missing header record", header_start);
    }
    ColdCsgTextRecord record;
    if (!cold_csg_next_text_record(text, pos, &record)) return false;
    if (record.kind != 0) {
        return cold_csg_hardfail("missing header record", header_start);
    }
    if (record.payload_bytes != COLD_CSG_HEADER_PAYLOAD_BYTES) {
        return cold_csg_hardfail("header record truncated", header_start);
    }
    int32_t payload_pos = 0;
    uint32_t schema_version = 0, abi_version = 0, producer_version = 0;
    uint8_t pointer_width = 0, endian_byte = 0;
    uint64_t schema_hash = 0, plan_hash = 0;
    if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                        &payload_pos, &schema_version)) return false;
    if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                        &payload_pos, &abi_version)) return false;
    if (!cold_csg_hex_byte(record.payload_hex, record.payload_bytes,
                              payload_pos, &pointer_width)) return false;
    payload_pos++;
    if (!cold_csg_hex_byte(record.payload_hex, record.payload_bytes,
                              payload_pos, &endian_byte)) return false;
    payload_pos++;
    if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                        &payload_pos, &producer_version)) return false;
    (void)producer_version;
    /* target_triple(32B) + entry_symbol(64B) are fixed-size identification
       copies; record kinds 1/3 stay authoritative for decoding. */
    payload_pos += COLD_CSG_HEADER_TRIPLE_BYTES + COLD_CSG_HEADER_ENTRY_BYTES;
    if (!cold_csg_read_payload_u64le(record.payload_hex, record.payload_bytes,
                                        &payload_pos, &schema_hash)) return false;
    if (!cold_csg_read_payload_u64le(record.payload_hex, record.payload_bytes,
                                        &payload_pos, &plan_hash)) return false;
    if (payload_pos != record.payload_bytes) {
        return cold_csg_hardfail("header record truncated", header_start);
    }
    if (schema_version != COLD_CSG_SCHEMA_VERSION) {
        return cold_csg_hardfail("schema_version mismatch", header_start);
    }
    if (abi_version != COLD_CSG_ABI_VERSION) {
        return cold_csg_hardfail("abi_version mismatch", header_start);
    }
    if (pointer_width != COLD_CSG_POINTER_WIDTH) {
        return cold_csg_hardfail("pointer_width mismatch", header_start);
    }
    if (endian_byte != COLD_CSG_ENDIAN_LITTLE) {
        return cold_csg_hardfail("endian mismatch", header_start);
    }
    if (schema_hash != cold_csg_schema_hash()) {
        return cold_csg_hardfail("schema_hash mismatch", header_start);
    }
    if (plan_hash != cold_csg_plan_hash(text, *pos)) {
        return cold_csg_hardfail("plan_hash mismatch", header_start);
    }
    return true;
}

static bool cold_csg_count_primary_records(Span text,
                                              int32_t *out_functions,
                                              int32_t *out_words,
                                              int32_t *out_relocs,
                                              int32_t *out_data,
                                              int32_t *out_data_relocs,
                                              int32_t *out_records) {
    static const char magic[] = "CHENG_CSG\n";
    int32_t magic_len = (int32_t)sizeof(magic) - 1;
    if (text.len < magic_len || memcmp(text.ptr, magic, (size_t)magic_len) != 0) return false;
    bool saw_target = false;
    bool saw_format = false;
    bool saw_entry = false;
    int32_t functions = 0;
    int32_t words = 0;
    int32_t relocs = 0;
    int32_t data = 0;
    int32_t data_relocs = 0;
    int32_t records = 1; /* canonical header record */
    int32_t pos = magic_len;
    if (!cold_csg_validate_header_record(text, &pos)) return false;
    while (pos < text.len) {
        ColdCsgTextRecord record;
        int32_t record_start = pos;
        if (!cold_csg_next_text_record(text, &pos, &record)) return false;
        if (records == INT32_MAX) return false;
        records++;
        switch (record.kind) {
            case 0:
                return cold_csg_hardfail("duplicate header record", record_start);
            case 1:
                if (saw_target) return false;
                saw_target = true;
                break;
            case 2:
                if (saw_format) return false;
                saw_format = true;
                break;
            case 3:
                if (saw_entry) return false;
                saw_entry = true;
                break;
            case 4:
                if (functions == INT32_MAX) return false;
                functions++;
                break;
            case 5:
                if (words == INT32_MAX) return false;
                words++;
                break;
            case 6:
                if (relocs == INT32_MAX) return false;
                relocs++;
                break;
            case 7:
                if (data == INT32_MAX) return false;
                data++;
                break;
            case 8:
                if (data_relocs == INT32_MAX) return false;
                data_relocs++;
                break;
            case 9:
                /* Call-edge facts are decoded below but need no primary-object
                   storage because their call sites are already linked. */
                break;
            default:
                return cold_csg_hardfail("unknown record kind", record_start);
        }
    }
    if (!saw_target || !saw_format || !saw_entry) return false;
    if (functions <= 0) return false;
    *out_functions = functions;
    *out_words = words;
    *out_relocs = relocs;
    if (out_data) *out_data = data;
    if (out_data_relocs) *out_data_relocs = data_relocs;
    if (out_records) *out_records = records;
    return true;
}

static int32_t cold_csg_find_item(const ColdCsgPrimaryObject *facts, uint32_t item_id) {
    for (int32_t i = 0; i < facts->function_count; i++) {
        if (facts->functions[i].item_id == item_id) return i;
    }
    return -1;
}

static int32_t cold_csg_find_symbol(const ColdCsgPrimaryObject *facts, Span symbol) {
    for (int32_t i = 0; i < facts->function_count; i++) {
        if (span_same(facts->functions[i].symbol_name, symbol)) return i;
    }
    return -1;
}

static int32_t cold_csg_find_data_symbol(const ColdCsgPrimaryObject *facts, Span symbol) {
    for (int32_t i = 0; i < facts->data_count; i++) {
        if (span_same(facts->data[i].symbol_name, symbol)) return i;
    }
    return -1;
}

static bool cold_target_is_ohos_aarch64(const char *target) {
    return target &&
           (strcmp(target, "aarch64-unknown-linux-ohos") == 0 ||
            strcmp(target, "aarch64-linux-ohos") == 0);
}

static bool cold_target_is_aarch64_elf_object(const char *target) {
    return target &&
           (strcmp(target, "aarch64-unknown-linux-gnu") == 0 ||
            strcmp(target, "aarch64-linux-android") == 0 ||
            cold_target_is_ohos_aarch64(target));
}

static bool cold_target_is_supported_elf_object(const char *target) {
    if (cold_target_is_aarch64_elf_object(target)) return true;
    return target &&
           (strcmp(target, "x86_64-unknown-linux-gnu") == 0 ||
            strcmp(target, "riscv64-unknown-linux-gnu") == 0 ||
            strcmp(target, "riscv64-unknown-none-elf") == 0);
}

static bool cold_csg_has_defined_symbol(const ColdCsgPrimaryObject *facts, Span symbol) {
    return cold_csg_find_symbol(facts, symbol) >= 0 ||
           cold_csg_find_data_symbol(facts, symbol) >= 0;
}

static const char *cold_csg_object_format_for_target(const char *target) {
    if (!target) return "";
    if (strcmp(target, "arm64-apple-darwin") == 0) return "macho";
    if (cold_target_is_supported_elf_object(target)) return "elf";
    if (strcmp(target, "x86_64-pc-windows-msvc") == 0 ||
        strcmp(target, "aarch64-pc-windows-msvc") == 0) return "coff";
    return "";
}

static bool cold_csg_validate_primary_object(ColdCsgPrimaryObject *facts,
                                                const char *requested_target) {
    if (!facts || facts->function_count <= 0) return false;
    if (facts->target_triple.len <= 0 || facts->object_format.len <= 0) return false;
    if (requested_target && requested_target[0] != '\0') {
        if (!span_eq(facts->target_triple, requested_target)) return false;
        const char *expected_format = cold_csg_object_format_for_target(requested_target);
        if (expected_format[0] == '\0') return false;
        if (!span_eq(facts->object_format, expected_format)) return false;
    }
    for (int32_t i = 0; i < facts->function_count; i++) {
        ColdCsgPrimaryFunction *fn = &facts->functions[i];
        if (fn->symbol_name.len <= 0) return false;
        if (fn->word_offset < 0 || fn->word_count < 0) return false;
        if (fn->word_offset > facts->word_count) return false;
        if (fn->word_count > facts->word_count - fn->word_offset) return false;
        for (int32_t j = i + 1; j < facts->function_count; j++) {
            if (facts->functions[j].item_id == fn->item_id) return false;
            if (span_same(facts->functions[j].symbol_name, fn->symbol_name)) return false;
        }
    }
    if (facts->entry_symbol.len > 0 &&
        cold_csg_find_symbol(facts, facts->entry_symbol) < 0) {
        return false;
    }
    for (int32_t i = 0; i < facts->reloc_count; i++) {
        ColdCsgPrimaryReloc *reloc = &facts->relocs[i];
        if (reloc->target_symbol.len <= 0) return false;
        int32_t source_index = cold_csg_find_item(facts, reloc->source_item_id);
        if (source_index < 0) return false;
        ColdCsgPrimaryFunction *source_fn = &facts->functions[source_index];
        if (reloc->word_offset < source_fn->word_offset) return false;
            if (reloc->word_offset >= source_fn->word_offset + source_fn->word_count) return false;
    }
    for (int32_t i = 0; i < facts->data_count; i++) {
        ColdCsgPrimaryData *data = &facts->data[i];
        if (data->symbol_name.len <= 0) return false;
        if (data->byte_count <= 0 || !data->bytes) return false;
        if (data->align != 1 && data->align != 2 && data->align != 4 &&
            data->align != 8 && data->align != 16) return false;
        for (int32_t j = i + 1; j < facts->data_count; j++) {
            if (facts->data[j].item_id == data->item_id) return false;
            if (span_same(facts->data[j].symbol_name, data->symbol_name)) return false;
        }
        if (cold_csg_find_symbol(facts, data->symbol_name) >= 0) return false;
    }
    for (int32_t i = 0; i < facts->data_reloc_count; i++) {
        ColdCsgPrimaryDataReloc *reloc = &facts->data_relocs[i];
        if (reloc->target_symbol.len <= 0) return false;
        if (reloc->reloc_kind != 1 || reloc->addend != 0) return false;
        if (!cold_csg_has_defined_symbol(facts, reloc->target_symbol)) return false;
        int32_t source_index = cold_csg_find_item(facts, reloc->source_item_id);
        if (source_index < 0) return false;
        ColdCsgPrimaryFunction *source_fn = &facts->functions[source_index];
        if (reloc->word_offset < source_fn->word_offset) return false;
        if (reloc->word_offset + 1 >= source_fn->word_offset + source_fn->word_count) return false;
        uint32_t adrp = facts->words[reloc->word_offset];
        uint32_t add = facts->words[reloc->word_offset + 1];
        if ((adrp & 0x9F000000u) != 0x90000000u) return false;
        if ((add & 0xFFC00000u) != 0x91000000u) return false;
        uint32_t reg = adrp & 31u;
        if (reg == 31u) return false;
        if ((add & 31u) != reg || ((add >> 5) & 31u) != reg) return false;
    }
    return true;
}

static bool cold_csg_decode_primary_object(Span text,
                                              Arena *arena,
                                              int32_t function_count,
                                              int32_t word_count,
                                              int32_t reloc_count,
                                              int32_t data_count,
                                              int32_t data_reloc_count,
                                              const char *target,
                                              ColdCsgPrimaryObject *out) {
    static const char magic[] = "CHENG_CSG\n";
    int32_t magic_len = (int32_t)sizeof(magic) - 1;
    memset(out, 0, sizeof(*out));
    out->function_count = function_count;
    out->word_count = word_count;
    out->reloc_count = reloc_count;
    out->data_count = data_count;
    out->data_reloc_count = data_reloc_count;
    out->functions = arena_alloc(arena, (size_t)function_count * sizeof(ColdCsgPrimaryFunction));
    out->words = word_count > 0
        ? arena_alloc(arena, (size_t)word_count * sizeof(uint32_t))
        : 0;
    out->relocs = reloc_count > 0
        ? arena_alloc(arena, (size_t)reloc_count * sizeof(ColdCsgPrimaryReloc))
        : 0;
    out->data = data_count > 0
        ? arena_alloc(arena, (size_t)data_count * sizeof(ColdCsgPrimaryData))
        : 0;
    out->data_relocs = data_reloc_count > 0
        ? arena_alloc(arena, (size_t)data_reloc_count * sizeof(ColdCsgPrimaryDataReloc))
        : 0;

    bool saw_target = false;
    bool saw_format = false;
    bool saw_entry = false;
    int32_t fn_index = 0;
    int32_t word_index = 0;
    int32_t reloc_index = 0;
    int32_t data_index = 0;
    int32_t data_reloc_index = 0;
    int32_t pos = magic_len;
    while (pos < text.len) {
        ColdCsgTextRecord record;
        int32_t record_start = pos;
        if (!cold_csg_next_text_record(text, &pos, &record)) return false;
        int32_t payload_file_offset = record_start + 13;
        int32_t payload_pos = 0;
        switch (record.kind) {
            case 0:
                /* Header record: fully validated by
                   cold_csg_validate_header_record during the count pass. */
                break;
            case 1:
                if (saw_target) return false;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &out->target_triple)) return false;
                if (payload_pos != record.payload_bytes) return false;
                saw_target = true;
                break;
            case 2:
                if (saw_format) return false;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &out->object_format)) return false;
                if (payload_pos != record.payload_bytes) return false;
                saw_format = true;
                break;
            case 3:
                if (saw_entry) return false;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &out->entry_symbol)) return false;
                if (payload_pos != record.payload_bytes) return false;
                saw_entry = true;
                break;
            case 4: {
                if (fn_index >= function_count) return false;
                uint32_t item_id, word_offset, fn_word_count;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &item_id)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &word_offset)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &fn_word_count)) return false;
                if (item_id > (uint32_t)INT32_MAX ||
                    word_offset > (uint32_t)INT32_MAX ||
                    fn_word_count > (uint32_t)INT32_MAX) return false;
                ColdCsgPrimaryFunction *fn = &out->functions[fn_index++];
                fn->item_id = item_id;
                fn->word_offset = (int32_t)word_offset;
                fn->word_count = (int32_t)fn_word_count;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &fn->symbol_name)) return false;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &fn->body_kind)) return false;
                if (payload_pos != record.payload_bytes) return false;
                break;
            }
            case 5: {
                if (word_index >= word_count) return false;
                uint32_t word;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &word)) return false;
                if (payload_pos != record.payload_bytes) return false;
                out->words[word_index++] = word;
                break;
            }
            case 6: {
                if (reloc_index >= reloc_count) return false;
                uint32_t source_item_id, word_offset;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &source_item_id)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &word_offset)) return false;
                if (source_item_id > (uint32_t)INT32_MAX ||
                    word_offset > (uint32_t)INT32_MAX) return false;
                ColdCsgPrimaryReloc *reloc = &out->relocs[reloc_index++];
                reloc->source_item_id = source_item_id;
                reloc->word_offset = (int32_t)word_offset;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &reloc->target_symbol)) return false;
                if (payload_pos != record.payload_bytes) return false;
                break;
            }
            case 7: {
                if (data_index >= data_count) return false;
                uint32_t item_id, align, byte_count;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &item_id)) return false;
                ColdCsgPrimaryData *data = &out->data[data_index++];
                data->item_id = item_id;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &data->symbol_name)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &align)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &byte_count)) return false;
                if (align != 1 && align != 2 && align != 4 && align != 8 && align != 16) return false;
                if (byte_count > (uint32_t)INT32_MAX) return false;
                if (record.payload_bytes - payload_pos != (int32_t)byte_count) return false;
                uint8_t *bytes = arena_alloc(arena, byte_count > 0 ? (size_t)byte_count : 1u);
                for (uint32_t bi = 0; bi < byte_count; bi++) {
                    uint8_t byte = 0;
                    if (!cold_csg_hex_byte(record.payload_hex, record.payload_bytes,
                                              payload_pos + (int32_t)bi, &byte)) return false;
                    bytes[bi] = byte;
                }
                payload_pos += (int32_t)byte_count;
                data->align = align;
                data->byte_count = (int32_t)byte_count;
                data->bytes = bytes;
                if (payload_pos != record.payload_bytes) return false;
                break;
            }
            case 8: {
                if (data_reloc_index >= data_reloc_count) return false;
                uint32_t source_item_id, word_offset, reloc_kind, addend;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &source_item_id)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &word_offset)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &reloc_kind)) return false;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &addend)) return false;
                if (source_item_id > (uint32_t)INT32_MAX ||
                    word_offset > (uint32_t)INT32_MAX ||
                    addend > (uint32_t)INT32_MAX) return false;
                ColdCsgPrimaryDataReloc *reloc = &out->data_relocs[data_reloc_index++];
                reloc->source_item_id = source_item_id;
                reloc->word_offset = (int32_t)word_offset;
                reloc->reloc_kind = reloc_kind;
                reloc->addend = (int32_t)addend;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &reloc->target_symbol)) return false;
                if (payload_pos != record.payload_bytes) return false;
                break;
            }
            case 9: {
                /* Call-edge facts are metadata, but their payload remains part
                   of the canonical CSG contract and must decode exactly. */
                uint32_t source_item_id;
                Span target_symbol;
                if (!cold_csg_read_payload_u32le(record.payload_hex, record.payload_bytes,
                                                    &payload_pos, &source_item_id)) return false;
                if (source_item_id > (uint32_t)INT32_MAX) return false;
                if (!cold_csg_read_payload_string(record.payload_hex, record.payload_bytes,
                                                     &payload_pos, arena, payload_file_offset,
                                                     &target_symbol)) return false;
                if (target_symbol.len <= 0 || payload_pos != record.payload_bytes) return false;
                break;
            }
            default:
                return false;
        }
    }
    if (!saw_target || !saw_format || !saw_entry) return false;
    if (fn_index != function_count || word_index != word_count ||
        reloc_index != reloc_count || data_index != data_count ||
        data_reloc_index != data_reloc_count) return false;
    return cold_csg_validate_primary_object(out, target);
}

static char *cold_span_to_cstr(Arena *arena, Span span) {
    char *buf = arena_alloc(arena, (size_t)span.len + 1);
    if (span.len > 0) memcpy(buf, span.ptr, (size_t)span.len);
    buf[span.len] = '\0';
    return buf;
}

static int32_t cold_csg_symbol_index_for_reloc(ColdCsgPrimaryObject *facts,
                                                  Span target_symbol,
                                                  const char **names,
                                                  int32_t *offsets,
                                                  int32_t *name_count,
                                                  int32_t max_names,
                                                  Arena *arena) {
    int32_t defined = cold_csg_find_symbol(facts, target_symbol);
    if (defined >= 0) return defined;
    for (int32_t i = facts->function_count; i < *name_count; i++) {
        Span existing = {(const uint8_t *)names[i], (int32_t)strlen(names[i])};
        if (span_same(existing, target_symbol)) return i;
    }
    if (*name_count >= max_names) return -1;
    int32_t index = *name_count;
    names[index] = cold_span_to_cstr(arena, target_symbol);
    offsets[index] = -1;
    *name_count = *name_count + 1;
    return index;
}

static int32_t cold_csg_name_index(const char **names, int32_t name_count, Span target) {
    for (int32_t i = 0; i < name_count; i++) {
        if (!names[i]) continue;
        int32_t len = (int32_t)strlen(names[i]);
        if (len == target.len && memcmp(names[i], target.ptr, (size_t)target.len) == 0) return i;
    }
    return -1;
}

static bool cold_csg_emit_primary_object(const char *out_path,
                                            const char *target,
                                            ColdCsgPrimaryObject *facts,
                                            Arena *arena) {
    bool is_elf = cold_target_is_supported_elf_object(target);
    bool is_coff = target && (strcmp(target, "x86_64-pc-windows-msvc") == 0 ||
                              strcmp(target, "aarch64-pc-windows-msvc") == 0);
    bool is_macho = target && strcmp(target, "arm64-apple-darwin") == 0;
    if (!is_macho && !is_elf && !is_coff) return false;

    uint16_t elf_machine = 0;
    uint16_t coff_machine = 0;
    if (is_elf) {
        if (strstr(target, "aarch64")) elf_machine = EM_AARCH64;
        else if (strstr(target, "riscv64")) elf_machine = EM_RISCV;
        else if (strstr(target, "x86_64")) elf_machine = EM_X86_64;
        else return false;
    }
    if (is_coff) {
        if (strstr(target, "aarch64")) coff_machine = IMAGE_FILE_MACHINE_ARM64;
        else if (strstr(target, "x86_64")) coff_machine = IMAGE_FILE_MACHINE_AMD64;
        else return false;
    }

    if (facts->data_count > 0 || facts->data_reloc_count > 0) {
        if (!is_macho) return false;
        if (facts->data_count <= 0) return false;
        int32_t max_names = facts->function_count + facts->data_count +
                            facts->reloc_count + facts->data_reloc_count;
        if (max_names <= 0) return false;
        const char **names = arena_alloc(arena, (size_t)max_names * sizeof(const char *));
        uint64_t *symbol_values = arena_alloc(arena, (size_t)max_names * sizeof(uint64_t));
        uint8_t *symbol_sections = arena_alloc(arena, (size_t)max_names * sizeof(uint8_t));
        int32_t name_count = 0;
        for (int32_t i = 0; i < facts->function_count; i++) {
            names[name_count] = cold_span_to_cstr(arena, facts->functions[i].symbol_name);
            symbol_values[name_count] = (uint64_t)(facts->functions[i].word_offset * 4);
            symbol_sections[name_count] = 1;
            name_count++;
        }

        int32_t *data_offsets = arena_alloc(arena, (size_t)facts->data_count * sizeof(int32_t));
        int32_t data_size = 0;
        for (int32_t i = 0; i < facts->data_count; i++) {
            int32_t align = (int32_t)facts->data[i].align;
            data_size = macho_align_i32(data_size, align);
            data_offsets[i] = data_size;
            if (facts->data[i].byte_count < 0 ||
                data_size > INT32_MAX - facts->data[i].byte_count) return false;
            data_size += facts->data[i].byte_count;
        }
        if (data_size <= 0) return false;
        uint8_t *data = arena_alloc(arena, (size_t)data_size);
        memset(data, 0, (size_t)data_size);
        for (int32_t i = 0; i < facts->data_count; i++) {
            memcpy(data + data_offsets[i], facts->data[i].bytes, (size_t)facts->data[i].byte_count);
        }

        int32_t data_addr = macho_align_i32(facts->word_count * 4, 8);
        for (int32_t i = 0; i < facts->data_count; i++) {
            names[name_count] = cold_span_to_cstr(arena, facts->data[i].symbol_name);
            symbol_values[name_count] = (uint64_t)(data_addr + data_offsets[i]);
            symbol_sections[name_count] = 2;
            name_count++;
        }

        int32_t total_relocs = facts->reloc_count + facts->data_reloc_count * 2;
        int32_t *reloc_offsets = total_relocs > 0
            ? arena_alloc(arena, (size_t)total_relocs * sizeof(int32_t))
            : 0;
        int32_t *reloc_symbols = total_relocs > 0
            ? arena_alloc(arena, (size_t)total_relocs * sizeof(int32_t))
            : 0;
        uint8_t *reloc_types = total_relocs > 0
            ? arena_alloc(arena, (size_t)total_relocs * sizeof(uint8_t))
            : 0;
        uint8_t *reloc_pcrel = total_relocs > 0
            ? arena_alloc(arena, (size_t)total_relocs * sizeof(uint8_t))
            : 0;
        int32_t reloc_index = 0;
        for (int32_t i = 0; i < facts->reloc_count; i++) {
            if (facts->relocs[i].word_offset > INT32_MAX / 4) return false;
            int32_t sym = cold_csg_name_index(names, name_count, facts->relocs[i].target_symbol);
            if (sym < 0) {
                if (name_count >= max_names) return false;
                sym = name_count;
                names[name_count] = cold_span_to_cstr(arena, facts->relocs[i].target_symbol);
                symbol_values[name_count] = 0;
                symbol_sections[name_count] = 0;
                name_count++;
            }
            reloc_offsets[reloc_index] = facts->relocs[i].word_offset * 4;
            reloc_symbols[reloc_index] = sym;
            reloc_types[reloc_index] = ARM64_RELOC_BRANCH26;
            reloc_pcrel[reloc_index] = 1;
            reloc_index++;
        }
        for (int32_t i = 0; i < facts->data_reloc_count; i++) {
            ColdCsgPrimaryDataReloc *dr = &facts->data_relocs[i];
            if (dr->word_offset > (INT32_MAX / 4) - 1) return false;
            int32_t sym = cold_csg_name_index(names, name_count, dr->target_symbol);
            if (sym < 0) return false;
            reloc_offsets[reloc_index] = dr->word_offset * 4;
            reloc_symbols[reloc_index] = sym;
            reloc_types[reloc_index] = ARM64_RELOC_PAGE21;
            reloc_pcrel[reloc_index] = 1;
            reloc_index++;
            reloc_offsets[reloc_index] = (dr->word_offset + 1) * 4;
            reloc_symbols[reloc_index] = sym;
            reloc_types[reloc_index] = ARM64_RELOC_PAGEOFF12;
            reloc_pcrel[reloc_index] = 0;
            reloc_index++;
        }
        if (reloc_index != total_relocs) return false;
        return macho_write_text_data_object(out_path, facts->words, facts->word_count,
                                            data, data_size,
                                            names, symbol_values, symbol_sections,
                                            name_count, 0,
                                            reloc_offsets, reloc_symbols,
                                            reloc_types, reloc_pcrel,
                                            total_relocs);
    }

    int32_t max_names = facts->function_count + facts->reloc_count;
    if (max_names <= 0) return false;
    const char **names = arena_alloc(arena, (size_t)max_names * sizeof(const char *));
    int32_t *offsets = arena_alloc(arena, (size_t)max_names * sizeof(int32_t));
    int32_t name_count = facts->function_count;
    for (int32_t i = 0; i < facts->function_count; i++) {
        names[i] = cold_span_to_cstr(arena, facts->functions[i].symbol_name);
        offsets[i] = facts->functions[i].word_offset;
    }

    int32_t *reloc_offsets = facts->reloc_count > 0
        ? arena_alloc(arena, (size_t)facts->reloc_count * sizeof(int32_t))
        : 0;
    int32_t *reloc_symbols = facts->reloc_count > 0
        ? arena_alloc(arena, (size_t)facts->reloc_count * sizeof(int32_t))
        : 0;
    for (int32_t i = 0; i < facts->reloc_count; i++) {
        if (facts->relocs[i].word_offset > INT32_MAX / 4) return false;
        int32_t byte_offset = facts->relocs[i].word_offset * 4;
        int32_t symbol_index = cold_csg_symbol_index_for_reloc(facts,
                                                                  facts->relocs[i].target_symbol,
                                                                  names, offsets,
                                                                  &name_count, max_names,
                                                                  arena);
        if (symbol_index < 0) return false;
        reloc_offsets[i] = byte_offset;
        reloc_symbols[i] = symbol_index;
    }
    int32_t local_count = 0;
    if (is_elf) {
        return elf64_write_object(out_path, facts->words, facts->word_count,
                                  names, offsets, name_count, local_count,
                                  reloc_offsets, reloc_symbols, facts->reloc_count,
                                  elf_machine);
    }
    if (is_coff) {
        return coff_write_object(out_path, facts->words, facts->word_count,
                                 names, offsets, name_count, local_count,
                                 reloc_offsets, reloc_symbols, facts->reloc_count,
                                 coff_machine);
    }
    return macho_write_object(out_path, facts->words, facts->word_count,
                              names, offsets, name_count, local_count,
                              reloc_offsets, reloc_symbols, facts->reloc_count);
}

static bool cold_compile_canonical_csg_primary_object(const char *out_path,
                                                         const char *target,
                                                         Span csg_text,
                                                         Arena *arena,
                                                         ColdCompileStats *stats,
                                                         uint64_t start_us,
                                                         uint64_t mmap_done_us) {
    if (csg_text.len <= 0) {
        return cold_csg_hardfail("empty canonical facts", 0);
    }
    if (csg_text.len > (int32_t)COLD_FACTS_BUDGET_MAX_BYTES) {
        fprintf(stderr, "cold_csg: facts budget exceeded: bytes=%d max=%d\n",
                csg_text.len, COLD_FACTS_BUDGET_MAX_BYTES);
        return false;
    }
    int32_t function_count = 0;
    int32_t word_count = 0;
    int32_t reloc_count = 0;
    int32_t data_count = 0;
    int32_t data_reloc_count = 0;
    int32_t record_count = 0;
    uint64_t verify_start_us = cold_now_us();
    if (!cold_csg_count_primary_records(csg_text, &function_count, &word_count, &reloc_count, &data_count, &data_reloc_count, &record_count)) {
        fprintf(stderr, "cold_csg: canonical record verification failed\n");
        return false;
    }
    if (function_count <= 0 || function_count > COLD_FACTS_BUDGET_MAX_FUNCTIONS) {
        fprintf(stderr, "cold_csg: function budget exceeded: count=%d max=%d\n",
                function_count, COLD_FACTS_BUDGET_MAX_FUNCTIONS);
        return false;
    }
    if (word_count < 0 || word_count > COLD_FACTS_BUDGET_MAX_OPS ||
        reloc_count < 0 || reloc_count > COLD_FACTS_BUDGET_MAX_OPS ||
        data_count < 0 || data_count > COLD_FACTS_BUDGET_MAX_OPS ||
        data_reloc_count < 0 || data_reloc_count > COLD_FACTS_BUDGET_MAX_OPS) {
        fprintf(stderr,
                "cold_csg: record budget exceeded: words=%d relocs=%d data=%d data_relocs=%d max=%d\n",
                word_count, reloc_count, data_count, data_reloc_count,
                COLD_FACTS_BUDGET_MAX_OPS);
        return false;
    }
    uint64_t verify_end_us = cold_now_us();
    ColdCsgPrimaryObject facts;
    if (!cold_csg_decode_primary_object(csg_text, arena,
                                           function_count, word_count, reloc_count,
                                           data_count, data_reloc_count,
                                           target, &facts)) {
        fprintf(stderr,
                "cold_csg: canonical decode failed: functions=%d words=%d relocs=%d data=%d data_relocs=%d\n",
                function_count, word_count, reloc_count, data_count, data_reloc_count);
        return false;
    }
    uint64_t decode_end_us = cold_now_us();
    bool ok = cold_csg_emit_primary_object(out_path, target, &facts, arena);
    if (!ok) {
        fprintf(stderr,
                "cold_csg: canonical object emit failed: target=%s functions=%d words=%d relocs=%d data=%d data_relocs=%d\n",
                target ? target : "", facts.function_count, facts.word_count,
                facts.reloc_count, facts.data_count, facts.data_reloc_count);
    }
    uint64_t emit_end_us = cold_now_us();
    if (stats) {
        stats->function_count = facts.function_count;
        stats->csg_lowering = 1;
        stats->code_words = facts.word_count;
        stats->arena_kb = arena_retained_bytes(arena) / 1024;
        stats->facts_bytes = (uint64_t)csg_text.len;
        stats->facts_mmap_us = mmap_done_us >= start_us ? mmap_done_us - start_us : 0;
        stats->facts_verify_us = verify_end_us >= verify_start_us ? verify_end_us - verify_start_us : 0;
        stats->facts_decode_us = decode_end_us >= verify_end_us ? decode_end_us - verify_end_us : 0;
        stats->facts_emit_obj_us = emit_end_us >= decode_end_us ? emit_end_us - decode_end_us : 0;
        stats->facts_total_us = emit_end_us >= start_us ? emit_end_us - start_us : 0;
        stats->facts_function_count = facts.function_count;
        stats->facts_word_count = facts.word_count;
        stats->facts_reloc_count = facts.reloc_count;
        stats->facts_data_count = facts.data_count;
        stats->facts_data_reloc_count = facts.data_reloc_count;
        stats->facts_record_count = record_count;
        stats->parse_us = stats->facts_verify_us + stats->facts_decode_us;
        stats->emit_us = stats->facts_emit_obj_us;
        stats->elapsed_us = stats->facts_total_us;
    }
    return ok;
}

/* ================================================================
 * CHENGCSG BodyIR binary reader
 * ================================================================ */

static bool cold_read_u32(const uint8_t *data, int32_t data_len, int32_t *pos, uint32_t *out) {
    if (*pos + 4 > data_len) return false;
    *out = (uint32_t)data[*pos] | ((uint32_t)data[*pos+1] << 8) |
           ((uint32_t)data[*pos+2] << 16) | ((uint32_t)data[*pos+3] << 24);
    *pos += 4;
    return true;
}

static bool cold_read_u64(const uint8_t *data, int32_t data_len, int32_t *pos, uint64_t *out) {
    if (*pos + 8 > data_len) return false;
    *out = (uint64_t)data[*pos] | ((uint64_t)data[*pos+1] << 8) |
           ((uint64_t)data[*pos+2] << 16) | ((uint64_t)data[*pos+3] << 24) |
           ((uint64_t)data[*pos+4] << 32) | ((uint64_t)data[*pos+5] << 40) |
           ((uint64_t)data[*pos+6] << 48) | ((uint64_t)data[*pos+7] << 56);
    *pos += 8;
    return true;
}

static bool cold_read_str(const uint8_t *data, int32_t data_len, int32_t *pos, Span *out) {
    uint32_t len;
    if (!cold_read_u32(data, data_len, pos, &len)) return false;
    if (*pos + (int32_t)len > data_len) return false;
    out->ptr = data + *pos;
    out->len = (int32_t)len;
    *pos += (int32_t)len;
    return true;
}

typedef struct ChengCsgTiming {
    int32_t facts_bytes;
    int32_t verify_us;
    int32_t decode_us;
    int32_t fn_count;
    int32_t op_count;
} ChengCsgTiming;

static bool cold_load_chengcsg_bodyir_facts(
    const uint8_t *data, int32_t data_len,
    ColdFunctionBodyStore *out_store, int32_t *out_count,
    Symbols *symbols, Arena *arena,
    const char *requested_target,
    ChengCsgTiming *timing
) {
    if (!out_store || out_store->items || out_store->frozen)
        die("CHENGCSG loader requires an empty function body store");
    uint64_t t_start = cold_now_us();
    uint64_t t_verify = 0, t_decode = 0;
    int32_t total_op_count = 0;
    int32_t pos = 0;

    /* Budget: total facts size */
    if (data_len > COLD_FACTS_BUDGET_MAX_BYTES) {
        fprintf(stderr, "[CHENGCSG] budget exceeded: facts_bytes=%d > max=%d\n",
                data_len, COLD_FACTS_BUDGET_MAX_BYTES);
        return false;
    }

    /* 1. Parse header (64 bytes) */
    if (pos + 64 > data_len) return false;
    if (memcmp(data + pos, "CHENGCSG", 8) != 0) return false;
    pos += 8;
    t_verify = cold_now_us();

    uint32_t version;
    if (!cold_read_u32(data, data_len, &pos, &version)) return false;
    if (version != CHENGCSG_SCHEMA_VERSION) return false;

    Span facts_target = {data + pos, 0};
    while (facts_target.len < 32 && facts_target.ptr[facts_target.len] != 0)
        facts_target.len++;
    if (requested_target && requested_target[0] != '\0' &&
        !span_eq(facts_target, requested_target)) return false;
    pos += 32;
    uint32_t abi = 0;
    if (!cold_read_u32(data, data_len, &pos, &abi)) return false;
    if (abi != 0) return false;
    if (pos + 16 > data_len) return false;
    uint8_t pointer_width = data[pos++];
    uint8_t endianness = data[pos++];
    if (pointer_width != 8 || endianness != 0) return false;
    for (int32_t ri = 0; ri < 14; ri++) {
        if (data[pos + ri] != 0) return false;
    }
    pos += 14;

    /* 2. Read section index */
    uint32_t section_count;
    if (!cold_read_u32(data, data_len, &pos, &section_count)) return false;
    if (section_count > 10) return false;

    uint32_t sec_kind[10], sec_size[10];
    uint64_t sec_offset[10];
    uint64_t section_data_end = 0;
    for (uint32_t si = 0; si < section_count; si++) {
        if (!cold_read_u32(data, data_len, &pos, &sec_kind[si])) return false;
        if (!cold_read_u64(data, data_len, &pos, &sec_offset[si])) return false;
        if (!cold_read_u32(data, data_len, &pos, &sec_size[si])) return false;
        if (sec_offset[si] > (uint64_t)data_len) return false;
        if ((uint64_t)sec_size[si] > (uint64_t)data_len - sec_offset[si]) return false;
        uint64_t end = sec_offset[si] + (uint64_t)sec_size[si];
        if (end > section_data_end) section_data_end = end;
    }
    if (section_data_end > (uint64_t)data_len) return false;
    if ((uint64_t)data_len - section_data_end != CHENGCSG_TRAILER_SIZE) return false;
    {
        int32_t tpos = (int32_t)section_data_end;
        uint32_t trailer_section_count = 0;
        if (!cold_read_u32(data, data_len, &tpos, &trailer_section_count)) return false;
        if (trailer_section_count != section_count) return false;
        tpos += CHENGCSG_HASH_SIZE;
        if (tpos != data_len) return false;
    }

    /* 3. Parse string section (kind=5) */
    Span *str_spans = 0;
    uint32_t str_count = 0;
    for (uint32_t si = 0; si < section_count; si++) {
        if (sec_kind[si] == CHENGCSG_SEC_STRING_LITERAL) {
            int32_t spos = (int32_t)sec_offset[si];
            int32_t send = (int32_t)(sec_offset[si] + (uint64_t)sec_size[si]);
            if (!cold_read_u32(data, send, &spos, &str_count)) return false;
            if (str_count > 0) {
                str_spans = arena_alloc(arena, (size_t)str_count * sizeof(Span));
                memset(str_spans, 0, (size_t)str_count * sizeof(Span));
                for (uint32_t i = 0; i < str_count; i++) {
                    uint32_t id, slen;
                    if (!cold_read_u32(data, send, &spos, &id)) return false;
                    if (!cold_read_u32(data, send, &spos, &slen)) return false;
                    if (slen > (uint32_t)INT32_MAX) return false;
                    if ((int32_t)(spos + (int32_t)slen) > send) return false;
                    if (id < str_count) {
                        str_spans[id] = (Span){data + spos, (int32_t)slen};
                    }
                    spos += (int32_t)slen;
                }
            }
            if (spos != send) return false;
            break;
        }
    }

    /* 4. Parse function section (kind=1) */
    int32_t sec_pos = 0;
    int32_t fn_sec_end = 0;
    bool found_fn_section = false;
    for (uint32_t si = 0; si < section_count; si++) {
        if (sec_kind[si] == CHENGCSG_SEC_FUNCTION) {
            sec_pos = (int32_t)sec_offset[si];
            fn_sec_end = (int32_t)(sec_offset[si] + (uint64_t)sec_size[si]);
            found_fn_section = true;
            break;
        }
    }
    if (!found_fn_section) return false;

    uint32_t fn_count;
    if (!cold_read_u32(data, fn_sec_end, &sec_pos, &fn_count)) return false;
    if (fn_count == 0) return false;
    if (fn_count > COLD_FACTS_BUDGET_MAX_FUNCTIONS) {
        fprintf(stderr, "[CHENGCSG] budget exceeded: fn_count=%u > max=%d\n",
                fn_count, COLD_FACTS_BUDGET_MAX_FUNCTIONS);
        return false;
    }

    /* Temporary list of (symbol_index, BodyIR*) pairs */
    typedef struct FnBodyPair {
        int32_t symbol_index;
        BodyIR *body;
    } FnBodyPair;

    FnBodyPair *fn_list = arena_alloc(arena, (size_t)fn_count * sizeof(FnBodyPair));
    memset(fn_list, 0, (size_t)fn_count * sizeof(FnBodyPair));

    for (uint32_t fi = 0; fi < fn_count; fi++) {
        /* Read function name */
        Span fn_name;
        if (!cold_read_str(data, fn_sec_end, &sec_pos, &fn_name)) return false;

        uint32_t param_count, return_kind, frame_size, op_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &param_count)) return false;
        if (param_count > COLD_MAX_I32_PARAMS) return false;
        int32_t param_kinds[COLD_MAX_I32_PARAMS];
        int32_t param_sizes[COLD_MAX_I32_PARAMS];
        int32_t param_slots[COLD_MAX_I32_PARAMS];
        for (uint32_t pi = 0; pi < param_count; pi++) {
            uint32_t pk, pz, ps;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &pk)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &pz)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &ps)) return false;
            if (pk > (uint32_t)INT32_MAX ||
                pz > (uint32_t)INT32_MAX ||
                (ps != UINT32_MAX && ps > (uint32_t)INT32_MAX)) return false;
            param_kinds[pi] = (int32_t)pk;
            param_sizes[pi] = (int32_t)pz;
            param_slots[pi] = ps == UINT32_MAX ? -1 : (int32_t)ps;
        }
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &return_kind)) return false;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &frame_size)) return false;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &op_count)) return false;
        if (op_count > COLD_FACTS_BUDGET_MAX_OPS) {
            fprintf(stderr, "[CHENGCSG] budget exceeded: op_count=%u > max=%d\n",
                    op_count, COLD_FACTS_BUDGET_MAX_OPS);
            return false;
        }
        total_op_count += (int32_t)op_count;

        /* Register function with symbols — map return_kind to type string */
        const char *ret_type_str = "int32";
        switch ((int32_t)return_kind) {
            case SLOT_I64: ret_type_str = "int64"; break;
            case SLOT_F32: ret_type_str = "float32"; break;
            case SLOT_F64: ret_type_str = "float64"; break;
            case SLOT_STR: ret_type_str = "str"; break;
            case SLOT_PTR: ret_type_str = "ptr"; break;
            case SLOT_VARIANT: case SLOT_OBJECT: ret_type_str = "ptr"; break;
            case SLOT_OPAQUE: ret_type_str = "ptr"; break;
            default: ret_type_str = "int32"; break;
        }
        int32_t sym_idx = symbols_add_fn(symbols, fn_name, (int32_t)param_count,
                                          param_kinds, param_sizes, 0,
                                          cold_cstr_span(ret_type_str));

        /* Mark external functions (no ops = @importc declaration) */
        if ((int32_t)op_count == 0 && sym_idx >= 0 && sym_idx < symbols->function_count)
            symbols->functions[sym_idx].is_external = true;

        /* Create BodyIR (null body for external functions) */
        BodyIR *body = body_new(arena);
        body->frame_size = (int32_t)frame_size;
        body->return_kind = (int32_t)return_kind;
        body->return_size = body->return_kind == 0
            ? 0
            : cold_slot_size_for_kind(body->return_kind);
        body->return_type = (Span){0};
        body->sret_slot = -1;
        body->has_fallback = false;
        body->param_count = (int32_t)param_count;
        for (uint32_t pi = 0; pi < param_count; pi++) {
            body->param_slot[pi] = param_slots[pi];
            body->param_name[pi] = (Span){0};
        }

        /* Read ops (5 u32 per op) */
        for (uint32_t oi = 0; oi < op_count; oi++) {
            uint32_t kind, dst, a, b, c;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &kind)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &dst)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &a)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &b)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &c)) return false;
            body_op3(body, (int32_t)kind, (int32_t)dst, (int32_t)a, (int32_t)b, (int32_t)c);
        }

        /* Read slots (4 u32 per slot) */
        uint32_t slot_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &slot_count)) return false;
        if (slot_count > COLD_FACTS_BUDGET_MAX_SLOTS) {
            fprintf(stderr, "[CHENGCSG] budget exceeded: slot_count=%u > max=%d\n",
                    slot_count, COLD_FACTS_BUDGET_MAX_SLOTS);
            return false;
        }
        for (uint32_t si = 0; si < slot_count; si++) {
            uint32_t skind, soff, ssize, saux;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &skind)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &soff)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &ssize)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &saux)) return false;
            body_ensure_slots(body);
            int32_t idx = body->slot_count++;
            body->slot_kind[idx] = (int32_t)skind;
            body->slot_offset[idx] = (int32_t)soff;
            body->slot_size[idx] = (int32_t)ssize;
            body->slot_aux[idx] = (int32_t)saux;
            body->slot_type[idx] = (Span){0};
            body->slot_no_alias[idx] = 0;
        }
        if (op_count > 0) {
            for (uint32_t pi = 0; pi < param_count; pi++) {
                int32_t slot = body->param_slot[pi];
                if (slot < 0 || slot >= body->slot_count) return false;
            }
        }

        /* Read blocks (3 u32 per block) */
        uint32_t block_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &block_count)) return false;
        for (uint32_t bi = 0; bi < block_count; bi++) {
            uint32_t bop_start, bop_cnt, bterm;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &bop_start)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &bop_cnt)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &bterm)) return false;
            body_ensure_blocks(body);
            int32_t idx = body->block_count++;
            body->block_op_start[idx] = (int32_t)bop_start;
            body->block_op_count[idx] = (int32_t)bop_cnt;
            body->block_term[idx] = (int32_t)bterm;
        }

        /* Read terms (6 u32 per term) */
        uint32_t term_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &term_count)) return false;
        for (uint32_t ti = 0; ti < term_count; ti++) {
            uint32_t tkind, tval, tcase_start, tcase_count, ttrue, tfalse;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &tkind)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &tval)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &tcase_start)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &tcase_count)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &ttrue)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &tfalse)) return false;
            body_ensure_terms(body);
            int32_t idx = body->term_count++;
            body->term_kind[idx] = (int32_t)tkind;
            body->term_value[idx] = (int32_t)tval;
            body->term_case_start[idx] = (int32_t)tcase_start;
            body->term_case_count[idx] = (int32_t)tcase_count;
            body->term_true_block[idx] = (int32_t)ttrue;
            body->term_false_block[idx] = (int32_t)tfalse;
        }

        for (uint32_t bi = 0; bi < block_count; bi++) {
            int32_t term = body->block_term[bi];
            if (term >= (int32_t)term_count) return false;
        }

        /* Read switch cases (3 u32 per case) */
        uint32_t switch_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &switch_count)) return false;
        for (uint32_t si = 0; si < switch_count; si++) {
            uint32_t stag, sblock, sterm;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &stag)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &sblock)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &sterm)) return false;
            body_ensure_switches(body);
            int32_t idx = body->switch_count++;
            body->switch_tag[idx] = (int32_t)stag;
            body->switch_block[idx] = (int32_t)sblock;
            body->switch_term[idx] = (int32_t)sterm;
        }

        /* Read and validate call metadata (4 u32 per call) */
        uint32_t call_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &call_count)) return false;
        if (call_count > (uint32_t)((fn_sec_end - sec_pos) / 16)) return false;
        uint32_t *call_arg_starts = call_count > 0
            ? arena_alloc(arena, (size_t)call_count * sizeof(uint32_t))
            : 0;
        uint32_t *call_arg_counts = call_count > 0
            ? arena_alloc(arena, (size_t)call_count * sizeof(uint32_t))
            : 0;
        for (uint32_t ci = 0; ci < call_count; ci++) {
            uint32_t target_fn, arg_start, arg_count, result_slot;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &target_fn)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &arg_start)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &arg_count)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &result_slot)) return false;
            if (target_fn >= fn_count ||
                arg_start > (uint32_t)INT32_MAX ||
                arg_count > (uint32_t)INT32_MAX ||
                result_slot >= slot_count) return false;
            call_arg_starts[ci] = arg_start;
            call_arg_counts[ci] = arg_count;
        }

        /* Read call args (2 u32 per arg) */
        uint32_t call_arg_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &call_arg_count)) return false;
        if (call_arg_count > 65536) return false;
        for (uint32_t cai = 0; cai < call_arg_count; cai++) {
            uint32_t caslot, caoff;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &caslot)) return false;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &caoff)) return false;
            if (caslot >= slot_count || caoff > (uint32_t)INT32_MAX) return false;
            body_ensure_call_args(body);
            int32_t idx = body->call_arg_count++;
            body->call_arg_slot[idx] = (int32_t)caslot;
            body->call_arg_offset[idx] = (int32_t)caoff;
        }
        for (uint32_t ci = 0; ci < call_count; ci++) {
            if (call_arg_starts[ci] > call_arg_count ||
                call_arg_counts[ci] > call_arg_count - call_arg_starts[ci]) return false;
        }

        /* Read string literal ids */
        uint32_t str_lit_count;
        if (!cold_read_u32(data, fn_sec_end, &sec_pos, &str_lit_count)) return false;
        for (uint32_t sli = 0; sli < str_lit_count; sli++) {
            uint32_t str_id;
            if (!cold_read_u32(data, fn_sec_end, &sec_pos, &str_id)) return false;
            if (str_id >= str_count || !str_spans) return false;
            body_ensure_string_literals(body);
            int32_t idx = body->string_literal_count++;
            body->string_literal[idx] = str_spans[str_id];
        }

        fn_list[fi].symbol_index = sym_idx;
        /* External functions: no codegen, left as undefined symbol */
        fn_list[fi].body = (op_count == 0) ? NULL : body;
    }
    if (sec_pos != fn_sec_end) return false;

    /* 4.5. Parse global variable section (kind=6) */
    for (uint32_t si = 0; si < section_count; si++) {
        if (sec_kind[si] != 6) continue;
        int32_t gpos = (int32_t)sec_offset[si];
        int32_t gend = (int32_t)(sec_offset[si] + (uint64_t)sec_size[si]);
        uint32_t global_count;
        if (!cold_read_u32(data, gend, &gpos, &global_count)) return false;
        for (uint32_t gi = 0; gi < global_count; gi++) {
            Span gname, gtype;
            uint32_t gkind, gsize, ginit_len;
            if (!cold_read_str(data, gend, &gpos, &gname)) return false;
            if (!cold_read_str(data, gend, &gpos, &gtype)) return false;
            if (!cold_read_u32(data, gend, &gpos, &gkind)) return false;
            if (!cold_read_u32(data, gend, &gpos, &gsize)) return false;
            if (!cold_read_u32(data, gend, &gpos, &ginit_len)) return false;
            if (ginit_len != gsize || ginit_len > (uint32_t)(gend - gpos)) return false;
            Span ginit = {(uint8_t *)(data + gpos), (int32_t)ginit_len};
            gpos += (int32_t)ginit_len;
            symbols_add_global(symbols, gname, (int32_t)gkind,
                               (int32_t)gsize, gtype, ginit, (Span){0});
        }
        if (gpos != gend) return false;
        break;
    }

    /* 5a. Parse function generics section (kind=7) — optional, old readers ignore it */
    for (uint32_t si = 0; si < section_count; si++) {
        if (sec_kind[si] == CHENGCSG_SEC_FUNCTION_GENERICS) {
            int32_t genpos = (int32_t)sec_offset[si];
            int32_t genend = (int32_t)(sec_offset[si] + (uint64_t)sec_size[si]);
            uint32_t gen_entry_count;
            if (!cold_read_u32(data, genend, &genpos, &gen_entry_count)) return false;
            if (gen_entry_count > fn_count) return false;
            for (uint32_t ei = 0; ei < gen_entry_count; ei++) {
                uint32_t gc;
                if (!cold_read_u32(data, genend, &genpos, &gc)) return false;
                if (gc > 4) return false;
                Span names[4];
                memset(names, 0, sizeof(names));
                for (uint32_t ni = 0; ni < gc; ni++) {
                    if (!cold_read_str(data, genend, &genpos, &names[ni])) return false;
                }
                if (ei < fn_count && gc > 0) {
                    int32_t sym_idx = fn_list[ei].symbol_index;
                    if (sym_idx >= 0 && sym_idx < symbols->function_count) {
                        Span arena_names[4];
                        for (uint32_t ai = 0; ai < gc; ai++) {
                            arena_names[ai] = cold_arena_span_copy(symbols->arena, names[ai]);
                        }
                        symbols_set_fn_generics(symbols, sym_idx, arena_names, (int32_t)gc);
                    }
                }
            }
            if (genpos != genend) return false;
            break;
        }
    }

    /* 5b. Publish decoded bodies through the sole production body store. */
    {
        int32_t cap = symbols->function_cap;
        cold_function_body_store_init(out_store, arena, cap);
        for (uint32_t fi = 0; fi < fn_count; fi++) {
            int32_t si = fn_list[fi].symbol_index;
            if (si >= 0 && si < cap) {
                cold_function_body_store_set(out_store, si, fn_list[fi].body);
            }
        }
    }
    *out_count = (int32_t)symbols->function_count;
    t_decode = cold_now_us();
    if (timing) {
        timing->facts_bytes = data_len;
        timing->verify_us = (int32_t)(t_verify - t_start);
        timing->decode_us = (int32_t)(t_decode - t_verify);
        timing->fn_count = (int32_t)fn_count;
        timing->op_count = total_op_count;
    }
    return true;
}

/* ================================================================
 * CSG record-based binary facts reader (lowered instruction words)
 * ================================================================ */

static uint32_t cold_read_chengcsg_u32_le(const uint8_t *data, int32_t *pos) {
    uint32_t v = (uint32_t)data[*pos] | ((uint32_t)data[*pos+1] << 8) |
                 ((uint32_t)data[*pos+2] << 16) | ((uint32_t)data[*pos+3] << 24);
    *pos += 4;
    return v;
}

static bool cold_read_chengcsg_u32_le_checked(const uint8_t *data,
                                            int32_t data_len,
                                            int32_t *pos,
                                            uint32_t *out) {
    return cold_read_u32(data, data_len, pos, out);
}

static char *cold_read_chengcsg_obj_str(Arena *arena, const uint8_t *data, int32_t *pos) {
    uint32_t len = cold_read_chengcsg_u32_le(data, pos);
    char *s = (char *)(data + *pos);
    *pos += (int32_t)len;
    if (len == 0) return "";
    char *copy = arena_alloc(arena, (size_t)len + 1);
    memcpy(copy, s, (size_t)len);
    copy[len] = '\0';
    return copy;
}

static bool cold_read_chengcsg_obj_str_checked(Arena *arena,
                                             const uint8_t *data,
                                             int32_t payload_end,
                                             int32_t *pos,
                                             char **out) {
    uint32_t len = 0;
    if (!cold_read_chengcsg_u32_le_checked(data, payload_end, pos, &len)) return false;
    if (len > (uint32_t)INT32_MAX) return false;
    if (*pos < 0 || *pos > payload_end - (int32_t)len) return false;
    if (len == 0) {
        *out = "";
        return true;
    }
    char *copy = arena_alloc(arena, (size_t)len + 1);
    memcpy(copy, data + *pos, (size_t)len);
    copy[len] = '\0';
    *pos += (int32_t)len;
    *out = copy;
    return true;
}

typedef struct ChengCsgObjFunction {
    uint32_t item_id;
    uint32_t word_offset;
    uint32_t word_count;
    char *symbol_name;
    char *body_kind;
} ChengCsgObjFunction;

typedef struct ChengCsgObjFacts {
    ChengCsgObjFunction *functions;
    int32_t function_count;
    int32_t function_cap;
    uint32_t *words;
    int32_t word_count;
    uint32_t *reloc_source_item_ids;
    uint32_t *reloc_word_offsets;
    char **reloc_target_symbols;
    int32_t reloc_count;
    int32_t reloc_cap;
    char *entry_symbol;
    char *object_format;
    char *target_triple;
    Arena *arena;
} ChengCsgObjFacts;

static bool cold_load_chengcsg_obj_facts(
    const uint8_t *data, int32_t data_len,
    ChengCsgObjFacts *facts, Arena *arena)
{
    memset(facts, 0, sizeof(*facts));
    facts->arena = arena;
    int32_t pos = 0;

    /* Magic */
    if (data_len < 8 || memcmp(data, "CHENGCSG", 8) != 0) return false;
    if (data_len > COLD_FACTS_BUDGET_MAX_BYTES) return false;
    pos = 8;

    /* Parse records */
    while (pos + 6 <= data_len) {
        uint32_t kind = (uint32_t)data[pos] | ((uint32_t)data[pos+1] << 8);
        pos += 2;
        uint32_t payload_size = 0;
        if (!cold_read_chengcsg_u32_le_checked(data, data_len, &pos, &payload_size)) return false;
        if (payload_size > (uint32_t)INT32_MAX) return false;
        if (pos + (int32_t)payload_size > data_len) return false;
        int32_t payload_end = pos + (int32_t)payload_size;

        switch (kind) {
        case 1: /* target_triple */
            if (!cold_read_chengcsg_obj_str_checked(arena, data, payload_end,
                                                  &pos, &facts->target_triple)) return false;
            break;
        case 2: /* object_format */
            if (!cold_read_chengcsg_obj_str_checked(arena, data, payload_end,
                                                  &pos, &facts->object_format)) return false;
            break;
        case 3: /* entry_symbol */
            if (!cold_read_chengcsg_obj_str_checked(arena, data, payload_end,
                                                  &pos, &facts->entry_symbol)) return false;
            break;
        case 4: { /* function */
            uint32_t item_id = 0, word_offset = 0, word_count = 0;
            char *sym = 0;
            char *kind_str = 0;
            if (!cold_read_chengcsg_u32_le_checked(data, payload_end, &pos, &item_id)) return false;
            if (!cold_read_chengcsg_u32_le_checked(data, payload_end, &pos, &word_offset)) return false;
            if (!cold_read_chengcsg_u32_le_checked(data, payload_end, &pos, &word_count)) return false;
            if (!cold_read_chengcsg_obj_str_checked(arena, data, payload_end, &pos, &sym)) return false;
            if (!cold_read_chengcsg_obj_str_checked(arena, data, payload_end, &pos, &kind_str)) return false;
            if (facts->function_count >= facts->function_cap) {
                int32_t new_cap = facts->function_cap ? facts->function_cap * 2 : 8;
                ChengCsgObjFunction *new_fns = arena_alloc(arena,
                    (size_t)new_cap * sizeof(ChengCsgObjFunction));
                if (facts->function_count > 0)
                    memcpy(new_fns, facts->functions,
                           (size_t)facts->function_count * sizeof(ChengCsgObjFunction));
                facts->functions = new_fns;
                facts->function_cap = new_cap;
            }
            ChengCsgObjFunction *fn = &facts->functions[facts->function_count++];
            fn->item_id = item_id;
            fn->word_offset = word_offset;
            fn->word_count = word_count;
            fn->symbol_name = sym;
            fn->body_kind = kind_str;
            break;
        }
        case 5: { /* instruction_words (batched) */
            if ((payload_size % 4) != 0) return false;
            int32_t word_count = (int32_t)payload_size / 4;
            if (word_count < 0 || word_count > COLD_FACTS_BUDGET_MAX_OPS) return false;
            facts->words = arena_alloc(arena, (size_t)word_count * sizeof(uint32_t));
            for (int32_t i = 0; i < word_count; i++) {
                if (!cold_read_chengcsg_u32_le_checked(data, payload_end,
                                                     &pos, &facts->words[i])) return false;
            }
            facts->word_count = word_count;
            break;
        }
        case 6: { /* reloc */
            uint32_t src_id = 0, word_off = 0;
            char *target = 0;
            if (!cold_read_chengcsg_u32_le_checked(data, payload_end, &pos, &src_id)) return false;
            if (!cold_read_chengcsg_u32_le_checked(data, payload_end, &pos, &word_off)) return false;
            if (!cold_read_chengcsg_obj_str_checked(arena, data, payload_end, &pos, &target)) return false;
            if (facts->reloc_count >= facts->reloc_cap) {
                int32_t new_cap = facts->reloc_cap ? facts->reloc_cap * 2 : 8;
                uint32_t *new_src = arena_alloc(arena,
                    (size_t)new_cap * sizeof(uint32_t));
                uint32_t *new_off = arena_alloc(arena,
                    (size_t)new_cap * sizeof(uint32_t));
                char **new_tgt = arena_alloc(arena,
                    (size_t)new_cap * sizeof(char *));
                if (facts->reloc_count > 0) {
                    memcpy(new_src, facts->reloc_source_item_ids,
                           (size_t)facts->reloc_count * sizeof(uint32_t));
                    memcpy(new_off, facts->reloc_word_offsets,
                           (size_t)facts->reloc_count * sizeof(uint32_t));
                    memcpy(new_tgt, facts->reloc_target_symbols,
                           (size_t)facts->reloc_count * sizeof(char *));
                }
                facts->reloc_source_item_ids = new_src;
                facts->reloc_word_offsets = new_off;
                facts->reloc_target_symbols = new_tgt;
                facts->reloc_cap = new_cap;
            }
            facts->reloc_source_item_ids[facts->reloc_count] = src_id;
            facts->reloc_word_offsets[facts->reloc_count] = word_off;
            facts->reloc_target_symbols[facts->reloc_count] = target;
            facts->reloc_count++;
            break;
        }
        default:
            return false;
        }
        if (pos != payload_end) return false;
    }
    if (pos != data_len) return false;
    if (facts->function_count <= 0 ||
        facts->function_count > COLD_FACTS_BUDGET_MAX_FUNCTIONS) return false;
    if (facts->word_count < 0 ||
        facts->word_count > COLD_FACTS_BUDGET_MAX_OPS) return false;
    if (facts->reloc_count < 0 ||
        facts->reloc_count > COLD_FACTS_BUDGET_MAX_OPS) return false;
    for (int32_t i = 0; i < facts->function_count; i++) {
        ChengCsgObjFunction *fn = &facts->functions[i];
        if (!fn->symbol_name || fn->symbol_name[0] == '\0') return false;
        if (fn->word_count == 0) return false;
        if (fn->word_offset > (uint32_t)facts->word_count) return false;
        if (fn->word_count > (uint32_t)facts->word_count - fn->word_offset) return false;
        for (int32_t j = 0; j < i; j++) {
            if (facts->functions[j].item_id == fn->item_id) return false;
            if (strcmp(facts->functions[j].symbol_name, fn->symbol_name) == 0) return false;
        }
    }
    for (int32_t i = 0; i < facts->reloc_count; i++) {
        if (!facts->reloc_target_symbols[i] ||
            facts->reloc_target_symbols[i][0] == '\0') return false;
        int32_t src_idx = -1;
        for (int32_t j = 0; j < facts->function_count; j++) {
            if (facts->functions[j].item_id == facts->reloc_source_item_ids[i]) {
                src_idx = j;
                break;
            }
        }
        if (src_idx < 0) return false;
        ChengCsgObjFunction *src = &facts->functions[src_idx];
        uint32_t rel_word = facts->reloc_word_offsets[i];
        if (rel_word < src->word_offset ||
            rel_word >= src->word_offset + src->word_count) return false;
    }
    return true;
}

