static bool cold_elf_symbol_is_global_text_definition(ColdElfObjectView *obj,
                                                      int32_t sym_index) {
    if (!obj || sym_index <= 0 || sym_index >= obj->sym_count) return false;
    const Elf64_Sym *sym = &obj->syms[sym_index];
    return sym->st_shndx == (uint16_t)obj->text_idx &&
           (sym->st_info >> 4) == STB_GLOBAL;
}

static int32_t cold_elf_find_global_defined_symbol(ColdElfObjectView *obj,
                                                   const char *name) {
    if (!obj || !name || name[0] == '\0') return -1;
    for (int32_t i = 1; i < obj->sym_count; i++) {
        if (!cold_elf_symbol_is_global_text_definition(obj, i)) continue;
        const char *sn = cold_elf_symbol_name(obj, (uint32_t)i);
        if (sn && strcmp(sn, name) == 0) return i;
    }
    return -1;
}

static bool cold_macho_symbol_is_external_text_definition(ColdMachOObjectView *obj,
                                                          int32_t sym_index) {
    if (!obj || sym_index < 0 || sym_index >= obj->sym_count) return false;
    ColdMachOSymbol symbol;
    if (!cold_macho_symbol_at(obj, sym_index, &symbol)) return false;
    return (symbol.n_type & 0x0e) == 0x0e &&
           (symbol.n_type & N_EXT) != 0 &&
           symbol.n_sect != 0;
}

static int32_t cold_macho_find_external_defined_symbol_exact(ColdMachOObjectView *obj,
                                                             const char *name) {
    if (!obj || !name || name[0] == '\0') return -1;
    for (int32_t i = 0; i < obj->sym_count; i++) {
        if (!cold_macho_symbol_is_external_text_definition(obj, i)) continue;
        const char *sn = cold_macho_symbol_name(obj, (uint32_t)i);
        if (sn && strcmp(sn, name) == 0) return i;
    }
    return -1;
}

static bool cold_selected_elf_providers_conflict_with_primary(ColdElfObjectView *primary,
                                                              ColdProviderArchiveView *archive,
                                                              ColdCompileStats *stats) {
    if (!primary || !archive) return false;
    for (int32_t mi = 0; mi < archive->member_count; mi++) {
        ColdProviderArchiveMember *member = &archive->members[mi];
        if (!member->selected || member->is_macho) continue;
        for (int32_t si = 1; si < member->view.sym_count; si++) {
            if (!cold_elf_symbol_is_global_text_definition(&member->view, si)) continue;
            const char *name = cold_elf_symbol_name(&member->view, (uint32_t)si);
            if (!name || name[0] == '\0') continue;
            if (cold_elf_find_global_defined_symbol(primary, name) >= 0) {
                cold_stats_provider_error_name(stats, "primary/provider symbol conflict", name);
                return true;
            }
        }
    }
    return false;
}

static bool cold_selected_macho_providers_conflict_with_primary(ColdMachOObjectView *primary,
                                                                ColdProviderArchiveView *archive,
                                                                ColdCompileStats *stats) {
    if (!primary || !archive) return false;
    for (int32_t mi = 0; mi < archive->member_count; mi++) {
        ColdProviderArchiveMember *member = &archive->members[mi];
        if (!member->selected || !member->is_macho) continue;
        for (int32_t si = 0; si < member->macho_view.sym_count; si++) {
            if (!cold_macho_symbol_is_external_text_definition(&member->macho_view, si)) continue;
            const char *name = cold_macho_symbol_name(&member->macho_view, (uint32_t)si);
            if (!name || name[0] == '\0') continue;
            if (cold_macho_find_external_defined_symbol_exact(primary, name) >= 0) {
                cold_stats_provider_error_name(stats, "primary/provider symbol conflict", name);
                return true;
            }
        }
    }
    return false;
}

static bool cold_apply_elf_call_reloc(uint32_t *words,
                                      int32_t word_count,
                                      uint16_t machine,
                                      uint32_t type,
                                      int32_t word_pos,
                                      int32_t target_word) {
    if (!words || word_pos < 0 || word_pos >= word_count ||
        target_word < 0 || target_word >= word_count) {
        return false;
    }
    int32_t delta = target_word - word_pos;
    if (machine == EM_AARCH64 && type == R_AARCH64_CALL26) {
        if (delta < -(1 << 25) || delta >= (1 << 25)) return false;
        words[word_pos] = (words[word_pos] & 0xFC000000u) |
                          ((uint32_t)delta & 0x03FFFFFFu);
        return true;
    }
    if (machine == EM_RISCV && (type == R_RISCV_CALL || type == R_RISCV_CALL_PLT)) {
        if (delta < -(1 << 20) || delta >= (1 << 20)) return false;
        words[word_pos] = rv_jal(RV_RA, delta);
        return true;
    }
    return false;
}

static bool cold_apply_aarch64_elf_reloc(uint32_t *words,
                                         int32_t total_words,
                                         uint32_t type,
                                         int32_t place_byte,
                                         int64_t target_byte) {
    if (!words || place_byte < 0 || (place_byte % 4) != 0 ||
        place_byte + 4 > total_words * 4 ||
        target_byte < 0 || target_byte >= (int64_t)total_words * 4LL) {
        return false;
    }
    int32_t word_pos = place_byte / 4;
    if (type == R_AARCH64_CALL26) {
        if ((target_byte % 4) != 0) return false;
        int32_t target_word = (int32_t)(target_byte / 4);
        return cold_apply_elf_call_reloc(words, total_words, EM_AARCH64,
                                         type, word_pos, target_word);
    }
    if (type == R_AARCH64_ADR_PREL_PG_HI21) {
        const uint64_t image_base = 0x400000ULL + 64ULL + 56ULL;
        uint64_t place_addr = image_base + (uint64_t)place_byte;
        uint64_t target_addr = image_base + (uint64_t)target_byte;
        int64_t page_delta = (int64_t)(target_addr >> 12) - (int64_t)(place_addr >> 12);
        if (page_delta < -(1LL << 20) || page_delta >= (1LL << 20)) return false;
        uint32_t imm21 = (uint32_t)page_delta & 0x1FFFFFu;
        uint32_t immlo = imm21 & 0x3u;
        uint32_t immhi = imm21 >> 2;
        words[word_pos] = (words[word_pos] & 0x9F00001Fu) |
                          (immlo << 29) |
                          (immhi << 5);
        return true;
    }
    if (type == R_AARCH64_ADD_ABS_LO12_NC) {
        const uint64_t image_base = 0x400000ULL + 64ULL + 56ULL;
        uint32_t imm12 = (uint32_t)((image_base + (uint64_t)target_byte) & 0xFFFu);
        words[word_pos] = (words[word_pos] & 0xFFC003FFu) | (imm12 << 10);
        return true;
    }
    return false;
}

static bool cold_link_relocs_for_object(ColdElfObjectView *obj,
                                        uint32_t *words,
                                        int32_t total_words,
                                        int32_t base_word,
                                        int32_t data_base_byte,
                                        ColdElfObjectView *primary,
                                        int32_t primary_data_base_byte,
                                        ColdProviderArchiveView *archive,
                                        bool primary_object,
                                        ColdCompileStats *stats) {
    for (int32_t i = 0; i < obj->reloc_count; i++) {
        const Elf64_Rela *reloc = &obj->relas[i];
        uint32_t sym_index = (uint32_t)(reloc->r_info >> 32);
        uint32_t type = (uint32_t)(reloc->r_info & 0xFFFFFFFFu);
        if (obj->machine == EM_X86_64) {
            if (!words || sym_index >= (uint32_t)obj->sym_count ||
                reloc->r_offset + 4 > (uint64_t)obj->word_count * 4ULL) {
                cold_stats_provider_error(stats, "x86_64 relocation range invalid");
                return false;
            }
            if (type != R_X86_64_PLT32 && type != R_X86_64_PC32) {
                char reloc_error[COLD_NAME_CAP];
                snprintf(reloc_error, sizeof(reloc_error),
                         "x86_64 unsupported relocation type: %u", type);
                cold_stats_provider_error(stats, reloc_error);
                return false;
            }
            const Elf64_Sym *sym = &obj->syms[sym_index];
            const char *sym_name = cold_elf_symbol_name(obj, sym_index);
            int64_t target_byte = INT64_MIN;
            if (sym->st_shndx == (uint16_t)obj->text_idx) {
                if (sym->st_value >= (uint64_t)obj->word_count * 4ULL) {
                    cold_stats_provider_error_name(stats, "x86_64 local relocation target invalid",
                                                   sym_name);
                    return false;
                }
                target_byte = (int64_t)base_word * 4LL +
                              (int64_t)sym->st_value + reloc->r_addend;
            } else if (obj->data_idx > 0 &&
                       sym->st_shndx == (uint16_t)obj->data_idx) {
                if (sym->st_value >= (uint64_t)obj->data_size) {
                    cold_stats_provider_error_name(stats, "x86_64 local data relocation target invalid",
                                                   sym_name);
                    return false;
                }
                target_byte = (int64_t)data_base_byte +
                              (int64_t)sym->st_value + reloc->r_addend;
            } else if (sym->st_shndx == 0) {
                if (!sym_name) return false;
                if (primary_object) {
                    int32_t member_index = cold_provider_archive_find_export(archive, sym_name);
                    if (member_index == -2) {
                        cold_stats_provider_error_name(stats, "provider export ambiguous", sym_name);
                        return false;
                    }
                    if (member_index >= 0) {
                        ColdProviderArchiveMember *member = &archive->members[member_index];
                        if (!member->selected) return false;
                        bool provider_is_data = false;
                        int32_t provider_byte = -1;
                        if (!cold_elf_defined_symbol_offset_any(&member->view, sym_name,
                                                                &provider_is_data,
                                                                &provider_byte)) {
                            cold_stats_provider_error_name(stats, "x86_64 provider definition missing",
                                                           sym_name);
                            return false;
                        }
                        target_byte = (provider_is_data
                            ? (int64_t)member->data_base_byte
                            : (int64_t)member->base_word * 4LL) +
                            (int64_t)provider_byte + reloc->r_addend;
                        if (stats) stats->provider_resolved_symbol_count++;
                    }
                } else {
                    int32_t primary_byte = -1;
                    bool primary_is_data = false;
                    if (primary &&
                        cold_elf_defined_symbol_offset_any(primary, sym_name,
                                                           &primary_is_data,
                                                           &primary_byte)) {
                        target_byte = (primary_is_data
                            ? (int64_t)primary_data_base_byte
                            : 0LL) + (int64_t)primary_byte + reloc->r_addend;
                    } else {
                        int32_t selected_byte = -1;
                        if (cold_provider_archive_find_selected_definition_addr(archive,
                                                                                sym_name,
                                                                                &selected_byte)) {
                            target_byte = (int64_t)selected_byte + reloc->r_addend;
                            if (stats) stats->provider_resolved_symbol_count++;
                        }
                    }
                }
                if (target_byte == INT64_MIN) {
                    if (stats) {
                        stats->unresolved_symbol_count++;
                        if (stats->first_unresolved_symbol[0] == '\0') {
                            snprintf(stats->first_unresolved_symbol,
                                     sizeof(stats->first_unresolved_symbol),
                                     "%s", sym_name);
                        }
                        const char *prefix = primary_object
                            ? "provider export missing"
                            : cold_provider_external_dependency_symbol(sym_name)
                                ? "provider external dependency unsupported"
                                : "provider dependency missing";
                        cold_stats_provider_error_name(stats, prefix, sym_name);
                    }
                    continue;
                }
            } else {
                cold_stats_provider_error_name(stats, "x86_64 unsupported relocation symbol section",
                                               sym_name);
                return false;
            }
            int32_t place_byte = base_word * 4 + (int32_t)reloc->r_offset;
            int64_t disp = target_byte - (int64_t)place_byte;
            if (disp < INT32_MIN || disp > INT32_MAX) {
                cold_stats_provider_error_name(stats, "x86_64 relocation displacement out of range",
                                               sym_name);
                return false;
            }
            uint8_t *bytes = (uint8_t *)words;
            bytes[place_byte] = (uint8_t)disp;
            bytes[place_byte + 1] = (uint8_t)(disp >> 8);
            bytes[place_byte + 2] = (uint8_t)(disp >> 16);
            bytes[place_byte + 3] = (uint8_t)(disp >> 24);
            if (stats) stats->link_reloc_count++;
            continue;
        }
        if (obj->machine == EM_AARCH64) {
            if (!words || sym_index >= (uint32_t)obj->sym_count ||
                reloc->r_offset + 4 > (uint64_t)obj->word_count * 4ULL) {
                cold_stats_provider_error(stats, "aarch64 relocation range invalid");
                return false;
            }
            const Elf64_Sym *sym = &obj->syms[sym_index];
            const char *sym_name = cold_elf_symbol_name(obj, sym_index);
            int64_t target_byte = INT64_MIN;
            if (sym->st_shndx == (uint16_t)obj->text_idx) {
                if (sym->st_value >= (uint64_t)obj->word_count * 4ULL) {
                    cold_stats_provider_error_name(stats, "aarch64 local relocation target invalid",
                                                   sym_name);
                    return false;
                }
                target_byte = (int64_t)base_word * 4LL +
                              (int64_t)sym->st_value + reloc->r_addend;
            } else if (obj->data_idx > 0 &&
                       sym->st_shndx == (uint16_t)obj->data_idx) {
                if (data_base_byte < 0 ||
                    sym->st_value >= (uint64_t)obj->data_size) {
                    cold_stats_provider_error_name(stats, "aarch64 local data relocation target invalid",
                                                   sym_name);
                    return false;
                }
                target_byte = (int64_t)data_base_byte +
                              (int64_t)sym->st_value + reloc->r_addend;
            } else if (sym->st_shndx == 0) {
                if (!sym_name) return false;
                if (primary_object) {
                    int32_t member_index = cold_provider_archive_find_export(archive, sym_name);
                    if (member_index == -2) {
                        cold_stats_provider_error_name(stats, "provider export ambiguous", sym_name);
                        return false;
                    }
                    if (member_index >= 0) {
                        ColdProviderArchiveMember *member = &archive->members[member_index];
                        if (!member->selected) return false;
                        bool provider_is_data = false;
                        int32_t provider_byte = -1;
                        if (!cold_elf_defined_symbol_offset_any(&member->view, sym_name,
                                                                &provider_is_data,
                                                                &provider_byte)) {
                            cold_stats_provider_error_name(stats, "aarch64 provider definition missing",
                                                           sym_name);
                            return false;
                        }
                        if (provider_is_data && member->data_base_byte < 0) {
                            cold_stats_provider_error_name(stats, "aarch64 provider data base missing",
                                                           sym_name);
                            return false;
                        }
                        target_byte = (provider_is_data
                            ? (int64_t)member->data_base_byte
                            : (int64_t)member->base_word * 4LL) +
                            (int64_t)provider_byte + reloc->r_addend;
                        if (stats) stats->provider_resolved_symbol_count++;
                    }
                } else {
                    int32_t primary_byte = -1;
                    bool primary_is_data = false;
                    if (primary &&
                        cold_elf_defined_symbol_offset_any(primary, sym_name,
                                                           &primary_is_data,
                                                           &primary_byte)) {
                        if (primary_is_data && primary_data_base_byte < 0) {
                            cold_stats_provider_error_name(stats, "aarch64 primary data base missing",
                                                           sym_name);
                            return false;
                        }
                        target_byte = (primary_is_data
                            ? (int64_t)primary_data_base_byte
                            : 0LL) + (int64_t)primary_byte + reloc->r_addend;
                    } else {
                        int32_t selected_byte = -1;
                        if (cold_provider_archive_find_selected_definition_addr(archive,
                                                                                sym_name,
                                                                                &selected_byte)) {
                            target_byte = (int64_t)selected_byte + reloc->r_addend;
                            if (stats) stats->provider_resolved_symbol_count++;
                        }
                    }
                }
                if (target_byte == INT64_MIN) {
                    if (stats) {
                        stats->unresolved_symbol_count++;
                        if (stats->first_unresolved_symbol[0] == '\0') {
                            snprintf(stats->first_unresolved_symbol,
                                     sizeof(stats->first_unresolved_symbol),
                                     "%s", sym_name);
                        }
                        const char *prefix = primary_object
                            ? "provider export missing"
                            : cold_provider_external_dependency_symbol(sym_name)
                                ? "provider external dependency unsupported"
                                : "provider dependency missing";
                        cold_stats_provider_error_name(stats, prefix, sym_name);
                    }
                    continue;
                }
            } else {
                cold_stats_provider_error_name(stats, "aarch64 unsupported relocation symbol section",
                                               sym_name);
                return false;
            }
            int32_t place_byte = base_word * 4 + (int32_t)reloc->r_offset;
            if (!cold_apply_aarch64_elf_reloc(words, total_words, type, place_byte,
                                              target_byte)) {
                char reloc_error[COLD_NAME_CAP];
                snprintf(reloc_error, sizeof(reloc_error),
                         "aarch64 unsupported relocation type: %u", type);
                cold_stats_provider_error_name(stats, reloc_error, sym_name);
                return false;
            }
            if (stats) stats->link_reloc_count++;
            continue;
        }
        if (sym_index >= (uint32_t)obj->sym_count ||
            (reloc->r_offset % 4) != 0 ||
            reloc->r_offset / 4 >= (uint64_t)obj->word_count) {
            return false;
        }
        const Elf64_Sym *sym = &obj->syms[sym_index];
        int32_t target_word = -1;
        const char *sym_name = cold_elf_symbol_name(obj, sym_index);
        if (sym->st_shndx == (uint16_t)obj->text_idx) {
            if ((sym->st_value % 4) != 0 || sym->st_value / 4 >= (uint64_t)obj->word_count) return false;
            if ((reloc->r_addend % 4) != 0) return false;
            int64_t local_word = (int64_t)(sym->st_value / 4) + (reloc->r_addend / 4);
            if (local_word < 0 || local_word >= obj->word_count) return false;
            target_word = base_word + (int32_t)local_word;
        } else if (sym->st_shndx == 0) {
            if (!sym_name || (reloc->r_addend % 4) != 0) return false;
            if (primary_object) {
                int32_t member_index = cold_provider_archive_find_export(archive, sym_name);
                if (member_index == -2) {
                    cold_stats_provider_error_name(stats, "provider export ambiguous", sym_name);
                    return false;
                }
                if (member_index >= 0) {
                    ColdProviderArchiveMember *member = &archive->members[member_index];
                    if (!member->selected) return false;
                    int32_t provider_word = -1;
                    if (!cold_elf_defined_symbol_word(&member->view, sym_name, &provider_word)) return false;
                    provider_word += (int32_t)(reloc->r_addend / 4);
                    if (provider_word < 0 || provider_word >= member->view.word_count) return false;
                    target_word = member->base_word + provider_word;
                    if (stats) stats->provider_resolved_symbol_count++;
                }
            } else {
                int32_t primary_word = -1;
                if (primary &&
                    cold_elf_defined_symbol_word(primary, sym_name, &primary_word)) {
                    primary_word += (int32_t)(reloc->r_addend / 4);
                    if (primary_word < 0 || primary_word >= primary->word_count) return false;
                    target_word = primary_word;
                } else if (cold_provider_archive_find_selected_definition(archive,
                                                                          sym_name,
                                                                          &target_word)) {
                    target_word += (int32_t)(reloc->r_addend / 4);
                    if (target_word < 0 || target_word >= total_words) return false;
                    if (stats) stats->provider_resolved_symbol_count++;
                }
            }
            if (target_word < 0) {
                if (stats) {
                    stats->unresolved_symbol_count++;
                    if (stats->first_unresolved_symbol[0] == '\0' && sym_name) {
                        snprintf(stats->first_unresolved_symbol,
                                 sizeof(stats->first_unresolved_symbol),
                                 "%s", sym_name);
                    }
                    const char *prefix = primary_object
                        ? "provider export missing"
                        : cold_provider_external_dependency_symbol(sym_name)
                            ? "provider external dependency unsupported"
                            : "provider dependency missing";
                    cold_stats_provider_error_name(stats, prefix, sym_name);
                }
                continue;
            }
        } else {
            return false;
        }
        int32_t word_pos = base_word + (int32_t)(reloc->r_offset / 4);
        if (!cold_apply_elf_call_reloc(words, total_words, obj->machine, type, word_pos, target_word)) return false;
        if (stats) stats->link_reloc_count++;
    }
    return true;
}

#define COLD_MACHO_TEXT_ADDR 0x1000002D8ULL

static bool cold_apply_macho_reloc(uint32_t *words, int32_t word_count,
                                    int32_t word_pos, int32_t target_word,
                                    uint32_t reloc_type) {
    if (!words || word_pos < 0 || word_pos >= word_count ||
        target_word < 0 || target_word >= word_count) {
        return false;
    }
    int32_t delta = target_word - word_pos;

    if (reloc_type == ARM64_RELOC_BRANCH26) {
        if (delta < -(1 << 25) || delta >= (1 << 25)) return false;
        words[word_pos] = (words[word_pos] & 0xFC000000u) |
                          ((uint32_t)delta & 0x03FFFFFFu);
        return true;
    }

    if (reloc_type == ARM64_RELOC_PAGE21) {
        uint64_t src_addr = COLD_MACHO_TEXT_ADDR + (uint64_t)word_pos * 4;
        uint64_t tgt_addr = COLD_MACHO_TEXT_ADDR + (uint64_t)target_word * 4;
        int64_t page_delta = (int64_t)((tgt_addr >> 12) - (src_addr >> 12));
        if (page_delta < -(1LL << 20) || page_delta >= (1LL << 20)) return false;
        uint32_t imm21 = (uint32_t)(page_delta & 0x1FFFFF);
        uint32_t immlo = imm21 & 0x3u;
        uint32_t immhi = imm21 >> 2;
        words[word_pos] = (words[word_pos] & 0x9F00001Fu) |
                          (immlo << 29) | (immhi << 5);
        return true;
    }

    if (reloc_type == ARM64_RELOC_PAGEOFF12) {
        uint64_t tgt_addr = COLD_MACHO_TEXT_ADDR + (uint64_t)target_word * 4;
        uint32_t page_off = (uint32_t)(tgt_addr & 0xFFF);
        words[word_pos] = (words[word_pos] & ~0x003FFC00u) |
                          ((page_off & 0xFFFu) << 10);
        return true;
    }

    return false;
}

typedef struct ColdMachODirectLinkObject {
    Span span;
    ColdMachOObjectView view;
    int32_t base_word;
    const char *path;
} ColdMachODirectLinkObject;

static int32_t cold_macho_direct_import_index(const char **imports,
                                              int32_t import_count,
                                              const char *symbol_name) {
    for (int32_t i = 0; i < import_count; i++) {
        if (strcmp(imports[i], symbol_name) == 0) return i;
    }
    return -1;
}

static bool cold_macho_direct_add_import(const char **imports,
                                         int32_t *import_count,
                                         int32_t import_cap,
                                         const char *symbol_name,
                                         int32_t *index_out) {
    int32_t existing = cold_macho_direct_import_index(imports, *import_count, symbol_name);
    if (existing >= 0) {
        if (index_out) *index_out = existing;
        return true;
    }
    if (*import_count >= import_cap) return false;
    imports[*import_count] = symbol_name;
    if (index_out) *index_out = *import_count;
    (*import_count)++;
    return true;
}

static bool cold_macho_direct_symbol_allowed_import(const char *symbol_name) {
    if (cold_darwin_system_link_symbol_allowed(symbol_name)) return true;
    if (!symbol_name || symbol_name[0] == '\0') return false;
    const char *name = symbol_name;
    if (name[0] == '_' && name[1] != '\0') name++;
    return cold_provider_external_dependency_symbol(name);
}

static bool cold_macho_direct_find_defined_symbol(ColdMachODirectLinkObject *objects,
                                                  int32_t object_count,
                                                  int32_t current_object,
                                                  const char *symbol_name,
                                                  int32_t *word_out) {
    if (!objects || object_count <= 0 || !symbol_name || symbol_name[0] == '\0') return false;
    int32_t found_word = -1;
    int32_t found_count = 0;
    for (int32_t oi = 0; oi < object_count; oi++) {
        int32_t local_word = -1;
        if (!cold_macho_defined_symbol_word(&objects[oi].view, symbol_name, &local_word)) continue;
        if (oi != current_object && local_word < 0) return false;
        found_word = objects[oi].base_word + local_word;
        found_count++;
    }
    if (found_count != 1) return false;
    if (word_out) *word_out = found_word;
    return true;
}

static bool cold_macho_direct_apply_reloc(uint32_t *words,
                                          int32_t word_count,
                                          int32_t word_pos,
                                          int32_t target_word,
                                          uint32_t reloc_type,
                                          uint64_t code_vmaddr) {
    if (!words || word_pos < 0 || word_pos >= word_count ||
        target_word < 0 || target_word >= word_count) {
        return false;
    }
    int32_t delta = target_word - word_pos;
    if (reloc_type == ARM64_RELOC_BRANCH26) {
        if (delta < -(1 << 25) || delta >= (1 << 25)) return false;
        words[word_pos] = (words[word_pos] & 0xFC000000u) |
                          ((uint32_t)delta & 0x03FFFFFFu);
        return true;
    }
    if (reloc_type == ARM64_RELOC_PAGE21) {
        uint64_t src_addr = code_vmaddr + (uint64_t)word_pos * 4ULL;
        uint64_t tgt_addr = code_vmaddr + (uint64_t)target_word * 4ULL;
        int64_t page_delta = (int64_t)((tgt_addr >> 12) - (src_addr >> 12));
        if (page_delta < -(1LL << 20) || page_delta >= (1LL << 20)) return false;
        uint32_t imm21 = (uint32_t)(page_delta & 0x1FFFFF);
        words[word_pos] = (words[word_pos] & 0x9F00001Fu) |
                          ((imm21 & 0x3u) << 29) | ((imm21 >> 2) << 5);
        return true;
    }
    if (reloc_type == ARM64_RELOC_PAGEOFF12) {
        uint64_t tgt_addr = code_vmaddr + (uint64_t)target_word * 4ULL;
        uint32_t page_off = (uint32_t)(tgt_addr & 0xFFFu);
        words[word_pos] = (words[word_pos] & ~0x003FFC00u) |
                          ((page_off & 0xFFFu) << 10);
        return true;
    }
    return false;
}

static uint32_t cold_macho_a64_adrp_reg(uint32_t reg, uint64_t pc, uint64_t target) {
    int64_t page_delta = (int64_t)((target >> 12) - (pc >> 12));
    uint32_t imm21 = (uint32_t)page_delta & 0x1FFFFFu;
    return 0x90000000u | ((imm21 & 0x3u) << 29) | ((imm21 >> 2) << 5) | (reg & 31u);
}

static uint32_t cold_macho_a64_ldr_x_imm(uint32_t rt, uint32_t rn, uint32_t byte_off) {
    return 0xF9400000u | (((byte_off >> 3) & 0xFFFu) << 10) |
           ((rn & 31u) << 5) | (rt & 31u);
}

static void cold_macho_put_uleb(uint8_t *buf, int32_t *pos, uint64_t value) {
    do {
        uint8_t byte = (uint8_t)(value & 0x7Fu);
        value >>= 7;
        if (value) byte |= 0x80u;
        buf[(*pos)++] = byte;
    } while (value);
}

static bool cold_macho_build_bind_info(const char **imports,
                                       int32_t import_count,
                                       uint8_t **bind_out,
                                       int32_t *bind_size_out,
                                       int32_t data_segment_index) {
    if (!bind_out || !bind_size_out || import_count < 0) return false;
    *bind_out = 0;
    *bind_size_out = 0;
    if (import_count == 0) return true;
    int32_t cap = 32 + import_count * 80;
    uint8_t *buf = (uint8_t *)calloc(1, (size_t)cap);
    if (!buf) return false;
    int32_t pos = 0;
    for (int32_t i = 0; i < import_count; i++) {
        const char *name = imports[i];
        if (!name || name[0] == '\0') { free(buf); return false; }
        int32_t need = (int32_t)strlen(name) + 32;
        if (pos + need >= cap) {
            int32_t new_cap = cap * 2 + need;
            uint8_t *next = (uint8_t *)realloc(buf, (size_t)new_cap);
            if (!next) { free(buf); return false; }
            memset(next + cap, 0, (size_t)(new_cap - cap));
            buf = next;
            cap = new_cap;
        }
        buf[pos++] = 0x10u | 1u;                 /* BIND_OPCODE_SET_DYLIB_ORDINAL_IMM */
        buf[pos++] = 0x40u;                      /* BIND_OPCODE_SET_SYMBOL_TRAILING_FLAGS_IMM */
        memcpy(buf + pos, name, strlen(name) + 1);
        pos += (int32_t)strlen(name) + 1;
        buf[pos++] = 0x50u | 1u;                 /* BIND_OPCODE_SET_TYPE_IMM, pointer */
        buf[pos++] = 0x70u | (uint8_t)data_segment_index;
        cold_macho_put_uleb(buf, &pos, (uint64_t)i * 8ULL);
        buf[pos++] = 0x90u;                      /* BIND_OPCODE_DO_BIND */
    }
    buf[pos++] = 0x00u;                          /* BIND_OPCODE_DONE */
    *bind_out = buf;
    *bind_size_out = pos;
    return true;
}

typedef struct {
    uint32_t state[8];
    uint64_t bit_len;
    uint8_t data[64];
    uint32_t data_len;
} ColdSha256;

static uint32_t cold_sha256_rotr(uint32_t x, uint32_t n) {
    return (x >> n) | (x << (32u - n));
}

static void cold_sha256_transform(ColdSha256 *ctx, const uint8_t data[64]) {
    static const uint32_t k[64] = {
        0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u,
        0x3956c25bu, 0x59f111f1u, 0x923f82a4u, 0xab1c5ed5u,
        0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
        0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u,
        0xe49b69c1u, 0xefbe4786u, 0x0fc19dc6u, 0x240ca1ccu,
        0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
        0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u,
        0xc6e00bf3u, 0xd5a79147u, 0x06ca6351u, 0x14292967u,
        0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
        0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u,
        0xa2bfe8a1u, 0xa81a664bu, 0xc24b8b70u, 0xc76c51a3u,
        0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
        0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u,
        0x391c0cb3u, 0x4ed8aa4au, 0x5b9cca4fu, 0x682e6ff3u,
        0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
        0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u
    };
    uint32_t m[64];
    for (int32_t i = 0; i < 16; i++) {
        m[i] = ((uint32_t)data[i * 4] << 24) |
               ((uint32_t)data[i * 4 + 1] << 16) |
               ((uint32_t)data[i * 4 + 2] << 8) |
               (uint32_t)data[i * 4 + 3];
    }
    for (int32_t i = 16; i < 64; i++) {
        uint32_t s0 = cold_sha256_rotr(m[i - 15], 7) ^
                      cold_sha256_rotr(m[i - 15], 18) ^
                      (m[i - 15] >> 3);
        uint32_t s1 = cold_sha256_rotr(m[i - 2], 17) ^
                      cold_sha256_rotr(m[i - 2], 19) ^
                      (m[i - 2] >> 10);
        m[i] = m[i - 16] + s0 + m[i - 7] + s1;
    }
    uint32_t a = ctx->state[0], b = ctx->state[1], c = ctx->state[2], d = ctx->state[3];
    uint32_t e = ctx->state[4], f = ctx->state[5], g = ctx->state[6], h = ctx->state[7];
    for (int32_t i = 0; i < 64; i++) {
        uint32_t s1 = cold_sha256_rotr(e, 6) ^ cold_sha256_rotr(e, 11) ^ cold_sha256_rotr(e, 25);
        uint32_t ch = (e & f) ^ ((~e) & g);
        uint32_t temp1 = h + s1 + ch + k[i] + m[i];
        uint32_t s0 = cold_sha256_rotr(a, 2) ^ cold_sha256_rotr(a, 13) ^ cold_sha256_rotr(a, 22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t temp2 = s0 + maj;
        h = g; g = f; f = e; e = d + temp1;
        d = c; c = b; b = a; a = temp1 + temp2;
    }
    ctx->state[0] += a; ctx->state[1] += b; ctx->state[2] += c; ctx->state[3] += d;
    ctx->state[4] += e; ctx->state[5] += f; ctx->state[6] += g; ctx->state[7] += h;
}

static void cold_sha256_init(ColdSha256 *ctx) {
    ctx->data_len = 0;
    ctx->bit_len = 0;
    ctx->state[0] = 0x6a09e667u; ctx->state[1] = 0xbb67ae85u;
    ctx->state[2] = 0x3c6ef372u; ctx->state[3] = 0xa54ff53au;
    ctx->state[4] = 0x510e527fu; ctx->state[5] = 0x9b05688cu;
    ctx->state[6] = 0x1f83d9abu; ctx->state[7] = 0x5be0cd19u;
}

static void cold_sha256_update(ColdSha256 *ctx, const uint8_t *data, size_t len) {
    for (size_t i = 0; i < len; i++) {
        ctx->data[ctx->data_len++] = data[i];
        if (ctx->data_len == 64) {
            cold_sha256_transform(ctx, ctx->data);
            ctx->bit_len += 512;
            ctx->data_len = 0;
        }
    }
}

static void cold_sha256_final(ColdSha256 *ctx, uint8_t hash[32]) {
    uint32_t i = ctx->data_len;
    ctx->data[i++] = 0x80u;
    if (i > 56) {
        while (i < 64) ctx->data[i++] = 0;
        cold_sha256_transform(ctx, ctx->data);
        i = 0;
    }
    while (i < 56) ctx->data[i++] = 0;
    ctx->bit_len += (uint64_t)ctx->data_len * 8ULL;
    for (int32_t j = 0; j < 8; j++) {
        ctx->data[63 - j] = (uint8_t)(ctx->bit_len >> (j * 8));
    }
    cold_sha256_transform(ctx, ctx->data);
    for (int32_t j = 0; j < 8; j++) {
        hash[j * 4] = (uint8_t)(ctx->state[j] >> 24);
        hash[j * 4 + 1] = (uint8_t)(ctx->state[j] >> 16);
        hash[j * 4 + 2] = (uint8_t)(ctx->state[j] >> 8);
        hash[j * 4 + 3] = (uint8_t)ctx->state[j];
    }
}

static void cold_sha256_bytes(const uint8_t *data, size_t len, uint8_t hash[32]) {
    ColdSha256 ctx;
    cold_sha256_init(&ctx);
    cold_sha256_update(&ctx, data, len);
    cold_sha256_final(&ctx, hash);
}

static void cold_sha256_hex(const uint8_t hash[32], char out[65]) {
    static const char hex[] = "0123456789abcdef";
    for (int32_t i = 0; i < 32; i++) {
        out[i * 2] = hex[(hash[i] >> 4) & 15];
        out[i * 2 + 1] = hex[hash[i] & 15];
    }
    out[64] = '\0';
}

#define COLD_OBJECT_CACHE_VERSION "cold-object-cache-v1"
#define COLD_PROVIDER_OBJECT_CACHE_VERSION "cold-provider-object-cache-v1"

static void cold_sha256_update_cstr(ColdSha256 *ctx, const char *text) {
    if (!ctx || !text) return;
    cold_sha256_update(ctx, (const uint8_t *)text, strlen(text));
    {
        const uint8_t sep = 0;
        cold_sha256_update(ctx, &sep, 1);
    }
}

static bool cold_object_cache_disabled(void) {
    const char *raw = getenv("CHENG_DISABLE_COLD_OBJECT_CACHE");
    return raw && (strcmp(raw, "1") == 0 || strcmp(raw, "true") == 0);
}

static bool cold_object_cache_update_file(ColdSha256 *ctx, const char *path) {
    if (!ctx || !path || path[0] == '\0') return false;
    Span file = source_open(path);
    if (file.len <= 0) return false;
    cold_sha256_update_cstr(ctx, path);
    cold_sha256_update(ctx, file.ptr, (size_t)file.len);
    munmap((void *)file.ptr, (size_t)file.len);
    return true;
}

static bool cold_object_cache_key(char out_hex[65],
                                  const char *src_path,
                                  Span mapped_source,
                                  ColdImportSource *import_sources,
                                  int32_t import_source_count,
                                  const char *target,
                                  const char *export_roots_csv,
                                  const char *symbol_visibility,
                                  bool reachable_entry_only) {
    if (!out_hex || !src_path || mapped_source.len <= 0) return false;
    ColdSha256 ctx;
    uint8_t digest[32];
    cold_sha256_init(&ctx);
    cold_sha256_update_cstr(&ctx, COLD_OBJECT_CACHE_VERSION);
    cold_sha256_update_cstr(&ctx, target ? target : "");
    cold_sha256_update_cstr(&ctx, export_roots_csv ? export_roots_csv : "");
    cold_sha256_update_cstr(&ctx, symbol_visibility ? symbol_visibility : "");
    cold_sha256_update_cstr(&ctx, reachable_entry_only ? "reachable" : "all");
    cold_sha256_update_cstr(&ctx, src_path);
    cold_sha256_update(&ctx, mapped_source.ptr, (size_t)mapped_source.len);
    for (int32_t i = 0; i < import_source_count; i++) {
        if (!cold_object_cache_update_file(&ctx, import_sources[i].path)) return false;
    }
    if (!cold_object_cache_update_file(&ctx, "bootstrap/cheng_cold.c")) return false;
    if (!cold_object_cache_update_file(&ctx, "bootstrap/coff_direct.h")) return false;
    cold_sha256_final(&ctx, digest);
    cold_sha256_hex(digest, out_hex);
    return true;
}

static bool cold_object_cache_path(char *out,
                                   size_t out_cap,
                                   const char *target,
                                   const char cache_key[65]) {
    if (!out || out_cap == 0 || !target || !cache_key) return false;
    char safe_target[128];
    int32_t ti = 0;
    for (const char *p = target; *p && ti < (int32_t)sizeof(safe_target) - 1; p++) {
        char c = *p;
        bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                  (c >= '0' && c <= '9') || c == '_' || c == '-';
        safe_target[ti++] = ok ? c : '_';
    }
    safe_target[ti] = '\0';
    if (safe_target[0] == '\0') return false;
    if (!cold_mkdir_p("artifacts/cold_object_cache")) return false;
    char target_dir[PATH_MAX];
    int nd = snprintf(target_dir, sizeof(target_dir),
                      "artifacts/cold_object_cache/%s", safe_target);
    if (nd <= 0 || nd >= (int)sizeof(target_dir)) return false;
    if (!cold_mkdir_p(target_dir)) return false;
    int n = snprintf(out, out_cap, "%s/%s.o", target_dir, cache_key);
    return n > 0 && n < (int)out_cap;
}

static bool cold_provider_object_cache_path(char *out,
                                            size_t out_cap,
                                            const char *target,
                                            const char cache_key[65]) {
    if (!out || out_cap == 0 || !target || !cache_key) return false;
    char safe_target[128];
    int32_t ti = 0;
    for (const char *p = target; *p && ti < (int32_t)sizeof(safe_target) - 1; p++) {
        char c = *p;
        bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                  (c >= '0' && c <= '9') || c == '_' || c == '-';
        safe_target[ti++] = ok ? c : '_';
    }
    safe_target[ti] = '\0';
    if (safe_target[0] == '\0') return false;
    if (!cold_mkdir_p("artifacts/cold_object_cache")) return false;
    if (!cold_mkdir_p("artifacts/cold_object_cache/windows_provider")) return false;
    char target_dir[PATH_MAX];
    int nd = snprintf(target_dir, sizeof(target_dir),
                      "artifacts/cold_object_cache/windows_provider/%s", safe_target);
    if (nd <= 0 || nd >= (int)sizeof(target_dir)) return false;
    if (!cold_mkdir_p(target_dir)) return false;
    int n = snprintf(out, out_cap, "%s/%s.o", target_dir, cache_key);
    return n > 0 && n < (int)out_cap;
}

static bool cold_windows_provider_cache_key(char out_hex[65],
                                            const char *provider_source,
                                            const char *windows_cc,
                                            const char *windows_toolchain_name,
                                            const char *windows_toolchain_cflags,
                                            const char *windows_cflags) {
    if (!out_hex || !provider_source || !windows_cc ||
        !windows_toolchain_name || !windows_toolchain_cflags || !windows_cflags) {
        return false;
    }
    ColdSha256 ctx;
    uint8_t digest[32];
    cold_sha256_init(&ctx);
    cold_sha256_update_cstr(&ctx, COLD_PROVIDER_OBJECT_CACHE_VERSION);
    cold_sha256_update_cstr(&ctx, provider_source);
    cold_sha256_update_cstr(&ctx, windows_cc);
    cold_sha256_update_cstr(&ctx, windows_toolchain_name);
    cold_sha256_update_cstr(&ctx, windows_toolchain_cflags);
    cold_sha256_update_cstr(&ctx, windows_cflags);
    cold_sha256_final(&ctx, digest);
    cold_sha256_hex(digest, out_hex);
    return true;
}

static void cold_path_with_hex_suffix(char *out, size_t out_cap, const char *path) {
    if (!out || out_cap == 0) return;
    int n = snprintf(out, out_cap, "%s.hex", path ? path : "");
    if (n <= 0 || n >= (int)out_cap) out[0] = '\0';
}

static bool cold_object_cache_restore(const char *cache_path, const char *out_path) {
    if (!cache_path || !out_path || !cold_file_exists_nonempty(cache_path)) return false;
    if (!cold_copy_file_path(cache_path, out_path)) return false;
    char cache_hex[PATH_MAX];
    char out_hex[PATH_MAX];
    cold_path_with_hex_suffix(cache_hex, sizeof(cache_hex), cache_path);
    cold_path_with_hex_suffix(out_hex, sizeof(out_hex), out_path);
    if (cache_hex[0] != '\0' && out_hex[0] != '\0' && cold_file_exists_nonempty(cache_hex)) {
        (void)cold_copy_file_path(cache_hex, out_hex);
    }
    return true;
}

static void cold_object_cache_store(const char *cache_path, const char *out_path) {
    if (!cache_path || !out_path || !cold_file_exists_nonempty(out_path)) return;
    (void)cold_copy_file_path(out_path, cache_path);
    char cache_hex[PATH_MAX];
    char out_hex[PATH_MAX];
    cold_path_with_hex_suffix(cache_hex, sizeof(cache_hex), cache_path);
    cold_path_with_hex_suffix(out_hex, sizeof(out_hex), out_path);
    if (cache_hex[0] != '\0' && out_hex[0] != '\0' && cold_file_exists_nonempty(out_hex)) {
        (void)cold_copy_file_path(out_hex, cache_hex);
    }
}

static void cold_put_u32be(uint8_t *p, uint32_t v) {
    p[0] = (uint8_t)(v >> 24);
    p[1] = (uint8_t)(v >> 16);
    p[2] = (uint8_t)(v >> 8);
    p[3] = (uint8_t)v;
}

static bool cold_macho_write_adhoc_signature(uint8_t *buf,
                                             int32_t file_len,
                                             int32_t code_limit,
                                             int32_t sig_off,
                                             int32_t sig_size,
                                             char *error_buf,
                                             size_t error_cap) {
    static const char ident[] = "cheng.internal-link-probe";
    const int32_t page_size_log2 = 12;
    const int32_t page_size = 1 << page_size_log2;
    const int32_t hash_size = 32;
    if (!buf || code_limit <= 0 || sig_off < code_limit ||
        sig_size <= 0 || sig_off + sig_size > file_len) {
        snprintf(error_buf, error_cap, "invalid Mach-O ad hoc signature input");
        return false;
    }
    int32_t code_slots = (code_limit + page_size - 1) / page_size;
    int32_t cd_off = 20;
    int32_t cd_ident_off = 44;
    int32_t cd_hash_off = macho_align_i32(cd_ident_off + (int32_t)sizeof(ident), 4);
    int32_t cd_len = cd_hash_off + code_slots * hash_size;
    if (20 + cd_len != sig_size) {
        snprintf(error_buf, error_cap, "Mach-O ad hoc signature size mismatch");
        return false;
    }
    uint8_t *sig = buf + sig_off;
    memset(sig, 0, (size_t)sig_size);
    cold_put_u32be(sig, 0xfade0cc0u);          /* CSMAGIC_EMBEDDED_SIGNATURE */
    cold_put_u32be(sig + 4, (uint32_t)sig_size);
    cold_put_u32be(sig + 8, 1u);
    cold_put_u32be(sig + 12, 0u);              /* CSSLOT_CODEDIRECTORY */
    cold_put_u32be(sig + 16, (uint32_t)cd_off);

    uint8_t *cd = sig + cd_off;
    cold_put_u32be(cd, 0xfade0c02u);           /* CSMAGIC_CODEDIRECTORY */
    cold_put_u32be(cd + 4, (uint32_t)cd_len);
    cold_put_u32be(cd + 8, 0x00020001u);       /* earliest CodeDirectory with SHA-256 hash type */
    cold_put_u32be(cd + 12, 0x00000002u);      /* CS_ADHOC */
    cold_put_u32be(cd + 16, (uint32_t)cd_hash_off);
    cold_put_u32be(cd + 20, (uint32_t)cd_ident_off);
    cold_put_u32be(cd + 24, 0u);
    cold_put_u32be(cd + 28, (uint32_t)code_slots);
    cold_put_u32be(cd + 32, (uint32_t)code_limit);
    cd[36] = (uint8_t)hash_size;
    cd[37] = 2u;                               /* CS_HASHTYPE_SHA256 */
    cd[38] = 0u;
    cd[39] = (uint8_t)page_size_log2;
    cold_put_u32be(cd + 40, 0u);
    memcpy(cd + cd_ident_off, ident, sizeof(ident));
    for (int32_t slot = 0; slot < code_slots; slot++) {
        int32_t page_off = slot * page_size;
        int32_t page_len = code_limit - page_off;
        if (page_len > page_size) page_len = page_size;
        if (page_len < 0) page_len = 0;
        cold_sha256_bytes(buf + page_off, (size_t)page_len,
                          cd + cd_hash_off + slot * hash_size);
    }
    return true;
}

static bool cold_macho_write_provider_executable(const char *out_path,
                                                 uint32_t *words,
                                                 int32_t code_words,
                                                 const char **imports,
                                                 int32_t import_count,
                                                 char *error_buf,
                                                 size_t error_cap) {
    if (!out_path || !out_path[0] || !words || code_words <= 0 || import_count < 0) {
        snprintf(error_buf, error_cap, "invalid Mach-O provider executable input");
        return false;
    }
    if (import_count > 512) {
        snprintf(error_buf, error_cap, "too many Darwin imports");
        return false;
    }

    const int32_t code_off = 4096;
    const uint64_t text_addr = 0x100000000ULL;
    const int32_t code_size = code_words * 4;
    const int32_t stub_size = import_count * 12;
    const int32_t text_file_size = macho_align_i32(code_off + code_size + stub_size,
                                                   MACHO_EXEC_PAGE_SIZE);
    const int32_t got_size = import_count * 8;
    const int32_t data_file_size = got_size > 0
        ? macho_align_i32(got_size, MACHO_EXEC_PAGE_SIZE) : 0;
    const uint64_t data_addr = text_addr + (uint64_t)text_file_size;
    const int32_t linkedit_fileoff = text_file_size + data_file_size;
    const uint64_t linkedit_addr = data_addr + (uint64_t)data_file_size;
    const uint64_t code_vmaddr = text_addr + (uint64_t)code_off;

    for (int32_t i = 0; i < import_count; i++) {
        uint64_t ptr_addr = data_addr + (uint64_t)i * 8ULL;
        uint64_t stub_addr = code_vmaddr + (uint64_t)code_size + (uint64_t)i * 12ULL;
        uint32_t *stub = words + code_words + i * 3;
        stub[0] = cold_macho_a64_adrp_reg(16, stub_addr, ptr_addr);
        stub[1] = cold_macho_a64_ldr_x_imm(16, 16, (uint32_t)(ptr_addr & 0xFFFu));
        stub[2] = 0xD61F0200u; /* br x16 */
    }

    uint8_t *bind_info = 0;
    int32_t bind_size = 0;
    if (!cold_macho_build_bind_info(imports, import_count, &bind_info, &bind_size, 2)) {
        snprintf(error_buf, error_cap, "Darwin bind info build failed");
        return false;
    }
    int32_t bind_off = linkedit_fileoff;
    int32_t cur = bind_off + bind_size;
    cur = macho_align_i32(cur, 8);
    int32_t symoff = cur;
    int32_t nsyms = import_count;
    int32_t sym_size = nsyms * 16;
    cur += sym_size;
    cur = macho_align_i32(cur, 4);
    int32_t indirectsymoff = cur;
    int32_t nindirect = import_count * 2;
    int32_t indirect_size = nindirect * 4;
    cur += indirect_size;
    int32_t stroff = cur;
    int32_t strsize = 1;
    for (int32_t i = 0; i < import_count; i++) strsize += (int32_t)strlen(imports[i]) + 1;
    if (strsize < 2) strsize = 2;
    cur += strsize;
    cur = macho_align_i32(cur, 16);
    int32_t code_signature_off = cur;
    const int32_t code_signature_page_size = 4096;
    int32_t code_signature_code_slots =
        (code_signature_off + code_signature_page_size - 1) / code_signature_page_size;
    int32_t code_signature_cd_ident_off = 44;
    int32_t code_signature_cd_hash_off =
        macho_align_i32(code_signature_cd_ident_off +
                        (int32_t)sizeof("cheng.internal-link-probe"), 4);
    int32_t code_signature_cd_len =
        code_signature_cd_hash_off + code_signature_code_slots * 32;
    int32_t code_signature_size = 20 + code_signature_cd_len;
    cur += code_signature_size;
    int32_t linkedit_size = cur - linkedit_fileoff;
    int32_t total_size = cur;
    if (total_size <= 0) {
        free(bind_info);
        snprintf(error_buf, error_cap, "Mach-O provider executable size overflow");
        return false;
    }
    uint8_t *buf = (uint8_t *)calloc(1, (size_t)total_size);
    if (!buf) {
        free(bind_info);
        snprintf(error_buf, error_cap, "Mach-O provider executable allocation failed");
        return false;
    }
    uint32_t *hdr = (uint32_t *)buf;
    hdr[0] = MH_MAGIC_64;
    hdr[1] = CPU_TYPE_ARM64;
    hdr[2] = CPU_SUBTYPE_ARM64_ALL;
    hdr[3] = MH_EXECUTE;
    hdr[6] = 0x00200085u; /* MH_NOUNDEFS | MH_DYLDLINK | MH_TWOLEVEL | MH_PIE */

    int32_t pos = 32;
#define COLD_MACHO_SEGMENT64(NAME, VMADDR, VMSIZE, FILEOFF, FILESIZE, MAXPROT, INITPROT, NSECTS) do { \
        uint32_t *seg = (uint32_t *)(buf + pos); \
        seg[0] = LC_SEGMENT64; \
        seg[1] = 72u + (uint32_t)(NSECTS) * 80u; \
        macho_segname(buf + pos + 8, (NAME)); \
        cold_put_u64le(buf + pos + 24, (uint64_t)(VMADDR)); \
        cold_put_u64le(buf + pos + 32, (uint64_t)(VMSIZE)); \
        cold_put_u64le(buf + pos + 40, (uint64_t)(FILEOFF)); \
        cold_put_u64le(buf + pos + 48, (uint64_t)(FILESIZE)); \
        seg[14] = (uint32_t)(MAXPROT); \
        seg[15] = (uint32_t)(INITPROT); \
        seg[16] = (uint32_t)(NSECTS); \
        pos += 72; \
    } while (0)
#define COLD_MACHO_SECTION64(SECT, SEG, ADDR, SIZE, OFFSET, ALIGN, FLAGS, RESERVED1, RESERVED2) do { \
        uint32_t *sec = (uint32_t *)(buf + pos); \
        macho_segname(buf + pos, (SECT)); \
        macho_segname(buf + pos + 16, (SEG)); \
        cold_put_u64le(buf + pos + 32, (uint64_t)(ADDR)); \
        cold_put_u64le(buf + pos + 40, (uint64_t)(SIZE)); \
        sec[12] = (uint32_t)(OFFSET); \
        sec[13] = (uint32_t)(ALIGN); \
        sec[16] = (uint32_t)(FLAGS); \
        sec[17] = (uint32_t)(RESERVED1); \
        sec[18] = (uint32_t)(RESERVED2); \
        pos += 80; \
    } while (0)
    COLD_MACHO_SEGMENT64("__PAGEZERO", 0, 0x100000000ULL, 0, 0, 0, 0, 0);
    COLD_MACHO_SEGMENT64("__TEXT", text_addr, (uint64_t)text_file_size, 0,
                         (uint64_t)text_file_size, 5, 5, import_count > 0 ? 2 : 1);
    COLD_MACHO_SECTION64("__text", "__TEXT", code_vmaddr, (uint64_t)code_size,
                         code_off, 2, 0x80000400u, 0, 0);
    if (import_count > 0) {
        COLD_MACHO_SECTION64("__stubs", "__TEXT", code_vmaddr + (uint64_t)code_size,
                             (uint64_t)stub_size, code_off + code_size, 2,
                             0x80000408u, 0, 12);
    }
    if (got_size > 0) {
        COLD_MACHO_SEGMENT64("__DATA", data_addr, (uint64_t)data_file_size,
                             (uint64_t)text_file_size, (uint64_t)data_file_size, 3, 3, 1);
        COLD_MACHO_SECTION64("__got", "__DATA", data_addr, (uint64_t)got_size,
                             text_file_size, 3, 0x00000006u, import_count, 0);
    }
    COLD_MACHO_SEGMENT64("__LINKEDIT", linkedit_addr, (uint64_t)linkedit_size,
                         (uint64_t)linkedit_fileoff, (uint64_t)linkedit_size, 1, 1, 0);
#undef COLD_MACHO_SECTION64
#undef COLD_MACHO_SEGMENT64
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_DYLD_INFO; w[1] = 48; w[4] = (uint32_t)bind_off; w[5] = (uint32_t)bind_size; pos += 48; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_LOAD_DYLINKER; w[1] = 32; w[2] = 12; memcpy(buf + pos + 12, "/usr/lib/dyld\0", 14); pos += 32; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_LOAD_DYLIB; w[1] = 56; w[2] = 24; w[3] = 2; w[4] = 0x10000; w[5] = 0x10000; memcpy(buf + pos + 24, "/usr/lib/libSystem.B.dylib\0", 28); pos += 56; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_SYMTAB; w[1] = 24; w[2] = (uint32_t)symoff; w[3] = (uint32_t)nsyms; w[4] = (uint32_t)stroff; w[5] = (uint32_t)strsize; pos += 24; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_DYSYMTAB; w[1] = 80; w[6] = 0; w[7] = (uint32_t)nsyms; w[14] = (uint32_t)indirectsymoff; w[15] = (uint32_t)nindirect; pos += 80; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_UUID; w[1] = 24; for (int i = 0; i < 16; i++) buf[pos + 8 + i] = (uint8_t)(0xD0 + i); pos += 24; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_BUILD_VERSION; w[1] = 24; w[2] = 1; w[3] = 0x000e0000; w[4] = 0x000e0000; pos += 24; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_FUNCTION_STARTS; w[1] = 16; pos += 16; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_DATA_IN_CODE; w[1] = 16; pos += 16; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_MAIN; w[1] = 24; w[2] = code_off; pos += 24; }
    { uint32_t *w = (uint32_t *)(buf + pos); w[0] = LC_CODE_SIGNATURE; w[1] = 16; w[2] = (uint32_t)code_signature_off; w[3] = (uint32_t)code_signature_size; pos += 16; }
    hdr[4] = 14u + (got_size > 0 ? 1u : 0u);
    hdr[5] = (uint32_t)(pos - 32);
    if (pos > code_off) {
        free(bind_info);
        free(buf);
        snprintf(error_buf, error_cap, "Mach-O load commands exceed code offset");
        return false;
    }

    memcpy(buf + code_off, words, (size_t)(code_size + stub_size));
    if (bind_size > 0) memcpy(buf + bind_off, bind_info, (size_t)bind_size);
    int32_t str_pos = stroff + 1;
    for (int32_t i = 0; i < import_count; i++) {
        int32_t sym_pos = symoff + i * 16;
        cold_put_u32le(buf + sym_pos, (uint32_t)(str_pos - stroff));
        buf[sym_pos + 4] = (uint8_t)(N_UNDF | N_EXT);
        buf[sym_pos + 6] = 0;
        buf[sym_pos + 7] = 1; /* dylib ordinal 1: libSystem */
        int32_t len = (int32_t)strlen(imports[i]);
        memcpy(buf + str_pos, imports[i], (size_t)len);
        str_pos += len + 1;
    }
    for (int32_t i = 0; i < import_count; i++) {
        cold_put_u32le(buf + indirectsymoff + i * 4, (uint32_t)i);
        cold_put_u32le(buf + indirectsymoff + (import_count + i) * 4, (uint32_t)i);
    }
    if (!cold_macho_write_adhoc_signature(buf,
                                          total_size,
                                          code_signature_off,
                                          code_signature_off,
                                          code_signature_size,
                                          error_buf,
                                          error_cap)) {
        free(bind_info);
        free(buf);
        return false;
    }

    int fd = open(out_path, O_WRONLY | O_CREAT | O_TRUNC, 0755);
    bool ok = fd >= 0 && cold_write_all_fd(fd, buf, (size_t)total_size);
    if (fd >= 0 && close(fd) != 0) ok = false;
    free(bind_info);
    free(buf);
    if (!ok) {
        snprintf(error_buf, error_cap, "Mach-O provider executable write failed");
        return false;
    }
    chmod(out_path, 0755);
    return true;
}

static bool cold_macho_bounded_contains_cstr(const uint8_t *data,
                                             int32_t len,
                                             const char *needle) {
    if (!data || len <= 0 || !needle || needle[0] == '\0') return false;
    int32_t nlen = (int32_t)strlen(needle);
    if (nlen <= 0 || nlen > len) return false;
    for (int32_t i = 0; i + nlen <= len; i++) {
        if (memcmp(data + i, needle, (size_t)nlen) == 0) return true;
    }
    return false;
}

static uint32_t cold_u32be(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) |
           ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) |
           (uint32_t)p[3];
}

static void cold_write_darwin_validation_script(const char *artifact_path,
                                                ColdCompileStats *stats) {
    if (!stats) return;
    stats->darwin_internal_link_validation_script = 1;
    stats->darwin_internal_link_validation_script_success = 0;
    stats->darwin_internal_link_validation_script_error[0] = '\0';
    if (!artifact_path || artifact_path[0] == '\0') {
        snprintf(stats->darwin_internal_link_validation_script_error,
                 sizeof(stats->darwin_internal_link_validation_script_error),
                 "missing artifact path");
        return;
    }
    int n = snprintf(stats->darwin_internal_link_validation_script_path,
                     sizeof(stats->darwin_internal_link_validation_script_path),
                     "%s.darwin-validate.sh", artifact_path);
    if (n <= 0 || n >= (int)sizeof(stats->darwin_internal_link_validation_script_path)) {
        snprintf(stats->darwin_internal_link_validation_script_error,
                 sizeof(stats->darwin_internal_link_validation_script_error),
                 "script path too long");
        return;
    }
    const char *base = strrchr(artifact_path, '/');
    const char *back = strrchr(artifact_path, '\\');
    if (!base || (back && back > base)) base = back;
    base = base ? base + 1 : artifact_path;
    FILE *f = fopen(stats->darwin_internal_link_validation_script_path, "wb");
    if (!f) {
        snprintf(stats->darwin_internal_link_validation_script_error,
                 sizeof(stats->darwin_internal_link_validation_script_error),
                 "script open failed");
        return;
    }
    fprintf(f, "#!/bin/sh\n");
    fprintf(f, "set -u\n");
    fprintf(f, "SCRIPT_DIR=$(CDPATH= cd \"$(dirname \"$0\")\" && pwd)\n");
    fprintf(f, "ARTIFACT=${1:-\"$SCRIPT_DIR/%s\"}\n", base);
    fprintf(f, "if [ \"$#\" -gt 0 ]; then shift; fi\n");
    fprintf(f, "RESULT=${CHENG_DARWIN_VALIDATION_RESULT_OUT:-\"$ARTIFACT.darwin-result.txt\"}\n");
    fprintf(f, "RESULT_DIR=$(dirname \"$RESULT\")\n");
    fprintf(f, "mkdir -p \"$RESULT_DIR\"\n");
    fprintf(f, "TMP_RESULT=\"$RESULT.tmp.$$\"\n");
    fprintf(f, ": > \"$TMP_RESULT\"\n");
    fprintf(f, "emit() { echo \"$1\"; echo \"$1\" >> \"$TMP_RESULT\"; }\n");
    fprintf(f, "finish() { mv \"$TMP_RESULT\" \"$RESULT\"; }\n");
    fprintf(f, "fail() { emit \"validation_result_success=0\"; emit \"validation_error=$1\"; finish; exit 1; }\n");
    fprintf(f, "EXPECTED_SHA256=%s\n", stats->darwin_internal_link_audit_artifact_sha256);
    fprintf(f, "EXPECTED_SIZE=%lld\n", (long long)stats->darwin_internal_link_audit_artifact_size);
    fprintf(f, "HOST_UNAME_S=$(uname -s 2>/dev/null || echo unknown)\n");
    fprintf(f, "HOST_UNAME_M=$(uname -m 2>/dev/null || echo unknown)\n");
    fprintf(f, "emit \"validation_result_version=1\"\n");
    fprintf(f, "emit \"target=arm64-apple-darwin\"\n");
    fprintf(f, "emit \"host_uname_s=$HOST_UNAME_S\"\n");
    fprintf(f, "emit \"host_uname_m=$HOST_UNAME_M\"\n");
    fprintf(f, "if [ \"$HOST_UNAME_S\" != \"Darwin\" ]; then emit \"host_darwin_arm64=0\"; fail \"host_not_darwin\"; fi\n");
    fprintf(f, "case \"$HOST_UNAME_M\" in arm64|aarch64) emit \"host_darwin_arm64=1\" ;; *) emit \"host_darwin_arm64=0\"; fail \"host_not_arm64\" ;; esac\n");
    fprintf(f, "if [ ! -f \"$ARTIFACT\" ]; then emit \"artifact_exists=0\"; fail \"missing_artifact\"; fi\n");
    fprintf(f, "emit \"artifact_exists=1\"\n");
    fprintf(f, "ACTUAL_SHA256=$(shasum -a 256 \"$ARTIFACT\" 2>/dev/null | awk '{print $1}')\n");
    fprintf(f, "if [ -z \"$ACTUAL_SHA256\" ]; then fail \"sha256_failed\"; fi\n");
    fprintf(f, "ACTUAL_SIZE=$(wc -c < \"$ARTIFACT\" | tr -d ' ')\n");
    fprintf(f, "emit \"artifact_path=$ARTIFACT\"\n");
    fprintf(f, "emit \"artifact_size=$ACTUAL_SIZE\"\n");
    fprintf(f, "if [ \"$ACTUAL_SIZE\" != \"$EXPECTED_SIZE\" ]; then emit \"artifact_size_match=0\"; fail \"artifact_size_mismatch\"; fi\n");
    fprintf(f, "emit \"artifact_size_match=1\"\n");
    fprintf(f, "emit \"artifact_sha256=$ACTUAL_SHA256\"\n");
    fprintf(f, "if [ \"$ACTUAL_SHA256\" != \"$EXPECTED_SHA256\" ]; then emit \"artifact_sha256_match=0\"; fail \"artifact_sha256_mismatch\"; fi\n");
    fprintf(f, "emit \"artifact_sha256_match=1\"\n");
    fprintf(f, "if chmod 755 \"$ARTIFACT\"; then emit \"chmod_755=1\"; else emit \"chmod_755=0\"; fail \"chmod_failed\"; fi\n");
    fprintf(f, "if codesign --verify --verbose=4 \"$ARTIFACT\"; then emit \"codesign_verify=1\"; else emit \"codesign_verify=0\"; fail \"codesign_verify_failed\"; fi\n");
    fprintf(f, "if otool -l \"$ARTIFACT\" | grep -q LC_MAIN; then emit \"lc_main=1\"; else emit \"lc_main=0\"; fail \"lc_main_missing\"; fi\n");
    fprintf(f, "if otool -l \"$ARTIFACT\" | grep -q LC_CODE_SIGNATURE; then emit \"lc_code_signature=1\"; else emit \"lc_code_signature=0\"; fail \"lc_code_signature_missing\"; fi\n");
    fprintf(f, "if otool -L \"$ARTIFACT\" | grep -q '/usr/lib/libSystem.B.dylib'; then emit \"libsystem=1\"; else emit \"libsystem=0\"; fail \"libsystem_missing\"; fi\n");
    fprintf(f, "if [ \"${1:-}\" = \"--run-smoke\" ]; then shift; \"$ARTIFACT\" \"$@\"; rc=$?; if [ \"$rc\" -eq 0 ]; then emit \"runtime_execution_validated=1\"; emit \"runtime_exit_code=0\"; else emit \"runtime_execution_validated=0\"; emit \"runtime_exit_code=$rc\"; fail \"runtime_smoke_failed\"; fi; else emit \"runtime_execution_validated=0\"; emit \"runtime_execution_validation_required=1\"; fail \"runtime_smoke_not_requested\"; fi\n");
    fprintf(f, "emit \"validation_error=\"\n");
    fprintf(f, "emit \"validation_result_success=1\"\n");
    fprintf(f, "finish\n");
    if (fclose(f) != 0) {
        snprintf(stats->darwin_internal_link_validation_script_error,
                 sizeof(stats->darwin_internal_link_validation_script_error),
                 "script close failed");
        return;
    }
    chmod(stats->darwin_internal_link_validation_script_path, 0755);
    stats->darwin_internal_link_validation_script_success = 1;
}

static void cold_write_darwin_validation_readme(const char *artifact_path,
                                                ColdCompileStats *stats) {
    if (!stats) return;
    stats->darwin_internal_link_validation_readme = 1;
    stats->darwin_internal_link_validation_readme_success = 0;
    stats->darwin_internal_link_validation_readme_error[0] = '\0';
    if (!artifact_path || artifact_path[0] == '\0') {
        snprintf(stats->darwin_internal_link_validation_readme_error,
                 sizeof(stats->darwin_internal_link_validation_readme_error),
                 "missing artifact path");
        return;
    }
    int n = snprintf(stats->darwin_internal_link_validation_readme_path,
                     sizeof(stats->darwin_internal_link_validation_readme_path),
                     "%s.darwin-validation.md", artifact_path);
    if (n <= 0 || n >= (int)sizeof(stats->darwin_internal_link_validation_readme_path)) {
        snprintf(stats->darwin_internal_link_validation_readme_error,
                 sizeof(stats->darwin_internal_link_validation_readme_error),
                 "readme path too long");
        return;
    }
    snprintf(stats->darwin_internal_link_validation_result_expected_path,
             sizeof(stats->darwin_internal_link_validation_result_expected_path),
             "%s.darwin-result.txt", artifact_path);
    char map_path[PATH_MAX];
    int nmap = snprintf(map_path, sizeof(map_path), "%s.map", artifact_path);
    if (nmap <= 0 || nmap >= (int)sizeof(map_path)) map_path[0] = '\0';
    char q_artifact[PATH_MAX * 5 + 8];
    char q_script[PATH_MAX * 5 + 8];
    char q_manifest[PATH_MAX * 5 + 8];
    char q_result[PATH_MAX * 5 + 8];
    if (!cold_shell_quote(q_artifact, sizeof(q_artifact), artifact_path) ||
        !cold_shell_quote(q_script, sizeof(q_script), stats->darwin_internal_link_validation_script_path) ||
        !cold_shell_quote(q_manifest, sizeof(q_manifest), stats->darwin_internal_link_validation_manifest_path) ||
        !cold_shell_quote(q_result, sizeof(q_result),
                          stats->darwin_internal_link_validation_result_expected_path)) {
        snprintf(stats->darwin_internal_link_validation_readme_error,
                 sizeof(stats->darwin_internal_link_validation_readme_error),
                 "readme command quote failed");
        return;
    }
    FILE *f = fopen(stats->darwin_internal_link_validation_readme_path, "wb");
    if (!f) {
        snprintf(stats->darwin_internal_link_validation_readme_error,
                 sizeof(stats->darwin_internal_link_validation_readme_error),
                 "readme open failed");
        return;
    }
    fprintf(f, "# Cheng Darwin arm64 validation bundle\n\n");
    fprintf(f, "This bundle was generated by the internal linkerless Mach-O provider-exe probe. ");
    fprintf(f, "It is not considered runtime validated until the result file is produced on arm64 Darwin and imported by a later build run.\n\n");
    fprintf(f, "## Artifact\n\n");
    fprintf(f, "- target: `arm64-apple-darwin`\n");
    fprintf(f, "- artifact: `%s`\n", artifact_path);
    fprintf(f, "- map: `%s`\n", map_path);
    fprintf(f, "- manifest: `%s`\n", stats->darwin_internal_link_validation_manifest_path);
    fprintf(f, "- validation script: `%s`\n", stats->darwin_internal_link_validation_script_path);
    fprintf(f, "- expected result: `%s`\n", stats->darwin_internal_link_validation_result_expected_path);
    fprintf(f, "- expected sha256: `%s`\n", stats->darwin_internal_link_audit_artifact_sha256);
    fprintf(f, "- artifact size: `%lld`\n",
            (long long)stats->darwin_internal_link_audit_artifact_size);
    fprintf(f, "- provenance: `cheng_cold internal Mach-O provider executable probe`\n\n");
    fprintf(f, "## Darwin validation\n\n");
    fprintf(f, "Run this on arm64 Darwin after copying the bundle files together:\n\n");
    fprintf(f, "```sh\n");
    fprintf(f, "CHENG_DARWIN_VALIDATION_RESULT_OUT=%s /bin/sh %s %s --run-smoke\n",
            q_result, q_script, q_artifact);
    fprintf(f, "```\n\n");
    fprintf(f, "If the files were copied into one portable bundle directory, run this from that directory instead:\n\n");
    fprintf(f, "```sh\n");
    const char *base = artifact_path;
    for (const char *p = artifact_path; *p; p++) {
        if (*p == '/' || *p == '\\') base = p + 1;
    }
    fprintf(f, "CHENG_DARWIN_VALIDATION_RESULT_OUT='./%s.darwin-result.txt' /bin/sh './%s.darwin-validate.sh' './%s' --run-smoke\n",
            base, base, base);
    fprintf(f, "```\n\n");
    fprintf(f, "The command checks SHA-256, applies `chmod 755`, verifies the ad hoc signature with `codesign`, checks `LC_MAIN`, `LC_CODE_SIGNATURE`, and libSystem imports with `otool`, then runs the artifact for the smoke step.\n\n");
    fprintf(f, "To create a portable bundle first, run this from the Windows repository root:\n\n");
    fprintf(f, "```sh\n");
    fprintf(f, "powershell -ExecutionPolicy Bypass -File tools/export_darwin_validation_bundle.ps1 -Manifest %s -OutDir .tmp-exec/darwin_arm64_probe/darwin-validation-bundle -ZipPath .tmp-exec/darwin_validation_handoff.zip\n",
            q_manifest);
    fprintf(f, "```\n\n");
    fprintf(f, "## Windows import\n\n");
    fprintf(f, "After the Darwin command succeeds, copy `%s` back with the exact artifact bundle and rerun the same `system-link-exec` command with:\n\n",
            stats->darwin_internal_link_validation_result_expected_path);
    fprintf(f, "```sh\n");
    fprintf(f, "CHENG_DARWIN_VALIDATION_RESULT=%s <same cheng_cold system-link-exec command>\n",
            q_result);
    fprintf(f, "```\n\n");
    fprintf(f, "The importer requires the result SHA to match the current artifact SHA and will keep runtime validation disabled if the result is missing, stale, or incomplete.\n");
    if (fclose(f) != 0) {
        stats->darwin_internal_link_validation_readme_success = 0;
        snprintf(stats->darwin_internal_link_validation_readme_error,
                 sizeof(stats->darwin_internal_link_validation_readme_error),
                 "readme close failed");
        return;
    }
    stats->darwin_internal_link_validation_readme_success = 1;
}

static void cold_write_darwin_validation_manifest(const char *artifact_path,
                                                  ColdCompileStats *stats) {
    if (!stats) return;
    stats->darwin_internal_link_validation_manifest = 1;
    stats->darwin_internal_link_validation_manifest_success = 0;
    stats->darwin_internal_link_validation_manifest_error[0] = '\0';
    if (!artifact_path || artifact_path[0] == '\0') {
        snprintf(stats->darwin_internal_link_validation_manifest_error,
                 sizeof(stats->darwin_internal_link_validation_manifest_error),
                 "missing artifact path");
        return;
    }
    int n = snprintf(stats->darwin_internal_link_validation_manifest_path,
                     sizeof(stats->darwin_internal_link_validation_manifest_path),
                     "%s.darwin-validation.txt", artifact_path);
    if (n <= 0 || n >= (int)sizeof(stats->darwin_internal_link_validation_manifest_path)) {
        snprintf(stats->darwin_internal_link_validation_manifest_error,
                 sizeof(stats->darwin_internal_link_validation_manifest_error),
                 "manifest path too long");
        return;
    }
    char manifest_script_path[PATH_MAX];
    char manifest_result_path[PATH_MAX];
    int nscript = snprintf(manifest_script_path, sizeof(manifest_script_path),
                           "%s.darwin-validate.sh", artifact_path);
    int nresult = snprintf(manifest_result_path, sizeof(manifest_result_path),
                           "%s.darwin-result.txt", artifact_path);
    if (nscript <= 0 || nscript >= (int)sizeof(manifest_script_path) ||
        nresult <= 0 || nresult >= (int)sizeof(manifest_result_path)) {
        snprintf(stats->darwin_internal_link_validation_manifest_error,
                 sizeof(stats->darwin_internal_link_validation_manifest_error),
                 "manifest sidecar path too long");
        return;
    }
    const char *base = strrchr(artifact_path, '/');
    const char *back = strrchr(artifact_path, '\\');
    if (!base || (back && back > base)) base = back;
    base = base ? base + 1 : artifact_path;
    char q_artifact[PATH_MAX * 5 + 8];
    char q_script[PATH_MAX * 5 + 8];
    char q_result[PATH_MAX * 5 + 8];
    if (!cold_shell_quote(q_artifact, sizeof(q_artifact), artifact_path) ||
        !cold_shell_quote(q_script, sizeof(q_script), manifest_script_path) ||
        !cold_shell_quote(q_result, sizeof(q_result), manifest_result_path)) {
        snprintf(stats->darwin_internal_link_validation_manifest_error,
                 sizeof(stats->darwin_internal_link_validation_manifest_error),
                 "manifest command quote failed");
        return;
    }
    FILE *f = fopen(stats->darwin_internal_link_validation_manifest_path, "wb");
    if (!f) {
        snprintf(stats->darwin_internal_link_validation_manifest_error,
                 sizeof(stats->darwin_internal_link_validation_manifest_error),
                 "manifest open failed");
        return;
    }
    fprintf(f, "validation_manifest_version=1\n");
    fprintf(f, "target=arm64-apple-darwin\n");
    fprintf(f, "artifact_path=%s\n", artifact_path);
    fprintf(f, "artifact_size=%lld\n",
            (long long)stats->darwin_internal_link_audit_artifact_size);
    fprintf(f, "artifact_sha256=%s\n",
            stats->darwin_internal_link_audit_artifact_sha256);
    fprintf(f, "static_audit_success=%d\n",
            stats->darwin_internal_link_audit_static_success);
    fprintf(f, "promotion_audit_success=%d\n",
            stats->darwin_internal_link_audit_success);
    fprintf(f, "lc_main=%d\n", stats->darwin_internal_link_audit_lc_main);
    fprintf(f, "entryoff=%d\n", stats->darwin_internal_link_audit_entryoff);
    fprintf(f, "dyld=%d\n", stats->darwin_internal_link_audit_dyld);
    fprintf(f, "libsystem=%d\n", stats->darwin_internal_link_audit_libsystem);
    fprintf(f, "code_signature=%d\n",
            stats->darwin_internal_link_audit_code_signature);
    fprintf(f, "code_signature_dataoff=%d\n",
            stats->darwin_internal_link_audit_code_signature_dataoff);
    fprintf(f, "code_signature_datasize=%d\n",
            stats->darwin_internal_link_audit_code_signature_datasize);
    fprintf(f, "code_signature_hash_type=%d\n",
            stats->darwin_internal_link_audit_code_signature_hash_type);
    fprintf(f, "code_signature_hash_size=%d\n",
            stats->darwin_internal_link_audit_code_signature_hash_size);
    fprintf(f, "code_signature_page_size_log2=%d\n",
            stats->darwin_internal_link_audit_code_signature_page_size);
    fprintf(f, "code_signature_code_slots=%d\n",
            stats->darwin_internal_link_audit_code_signature_code_slots);
    fprintf(f, "code_signature_code_limit=%d\n",
            stats->darwin_internal_link_audit_code_signature_code_limit);
    fprintf(f, "code_signature_hash_coverage=%d\n",
            stats->darwin_internal_link_audit_code_signature_hash_coverage);
    fprintf(f, "code_signature_reason=%s\n",
            stats->darwin_internal_link_audit_code_signature_reason);
    fprintf(f, "executable_bit_observed=%d\n",
            stats->darwin_internal_link_audit_executable_bit);
    fprintf(f, "runtime_execution_validated=0\n");
    fprintf(f, "runtime_execution_validation_required=1\n");
    fprintf(f, "darwin_validation_script=%s.darwin-validate.sh\n", artifact_path);
    fprintf(f, "darwin_validation_result=%s.darwin-result.txt\n", artifact_path);
    fprintf(f, "darwin_validation_readme=%s.darwin-validation.md\n", artifact_path);
    fprintf(f, "darwin_validation_map=%s.map\n", artifact_path);
    fprintf(f, "darwin_validation_darwin_command=CHENG_DARWIN_VALIDATION_RESULT_OUT=%s /bin/sh %s %s --run-smoke\n",
            q_result, q_script, q_artifact);
    fprintf(f, "darwin_validation_portable_darwin_command=CHENG_DARWIN_VALIDATION_RESULT_OUT='./%s.darwin-result.txt' /bin/sh './%s.darwin-validate.sh' './%s' --run-smoke\n",
            base, base, base);
    fprintf(f, "darwin_validation_windows_import_env=CHENG_DARWIN_VALIDATION_RESULT=%s.darwin-result.txt\n",
            artifact_path);
    fprintf(f, "darwin_validation_bundle_command=powershell -ExecutionPolicy Bypass -File tools/export_darwin_validation_bundle.ps1 -Manifest %s.darwin-validation.txt -OutDir .tmp-exec/darwin_arm64_probe/darwin-validation-bundle -ZipPath .tmp-exec/darwin_validation_handoff.zip\n",
            artifact_path);
    fprintf(f, "darwin_validation_bundle_files=%s,%s.darwin-validate.sh,%s.darwin-validation.txt,%s.darwin-validation.md,%s.map\n",
            base, base, base, base, base);
    fprintf(f, "darwin_validation_remote_host_env=CHENG_DARWIN_REMOTE_HOST\n");
    fprintf(f, "darwin_validation_remote_dir_env=CHENG_DARWIN_REMOTE_DIR\n");
    fprintf(f, "darwin_validation_remote_hook=tools/export_darwin_validation_bundle.ps1 -Manifest %s.darwin-validation.txt -RemoteHost <user@darwin-arm64-host> -RunRemote\n",
            artifact_path);
    fprintf(f, "artifact_provenance=cheng_cold_internal_macho_provider_executable_probe\n");
    fprintf(f, "darwin_validation_step_1=chmod 755 artifact_path\n");
    fprintf(f, "darwin_validation_step_2=codesign --verify --verbose=4 artifact_path\n");
    fprintf(f, "darwin_validation_step_3=run target smoke with artifact_path on arm64 Darwin\n");
    fprintf(f, "windows_validation_note=Mach-O runtime execution and executable mode are not authoritative on Windows/MSYS\n");
    if (fclose(f) != 0) {
        stats->darwin_internal_link_validation_manifest_success = 0;
        snprintf(stats->darwin_internal_link_validation_manifest_error,
                 sizeof(stats->darwin_internal_link_validation_manifest_error),
                 "manifest close failed");
        return;
    }
    stats->darwin_internal_link_validation_manifest_success = 1;
    cold_write_darwin_validation_script(artifact_path, stats);
    cold_write_darwin_validation_readme(artifact_path, stats);
}

static void cold_macho_audit_provider_executable(const char *path,
                                                 ColdCompileStats *stats) {
    if (!stats) return;
    stats->darwin_internal_link_audit = 1;
    stats->darwin_internal_link_audit_success = 0;
    stats->darwin_internal_link_audit_static_success = 0;
    stats->darwin_internal_link_audit_error[0] = '\0';
    stats->darwin_internal_link_audit_code_signature_reason[0] = '\0';
    if (!path || path[0] == '\0') {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "missing probe artifact path");
        return;
    }
    struct stat st;
    if (stat(path, &st) == 0 && S_ISREG(st.st_mode) && (st.st_mode & 0111) != 0) {
        stats->darwin_internal_link_audit_executable_bit = 1;
    }
    Span file = source_open(path);
    if (file.len < 32) {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "probe artifact too small");
        return;
    }
    const uint8_t *data = file.ptr;
    stats->darwin_internal_link_audit_artifact_size = file.len;
    {
        uint8_t artifact_hash[32];
        cold_sha256_bytes(data, (size_t)file.len, artifact_hash);
        cold_sha256_hex(artifact_hash, stats->darwin_internal_link_audit_artifact_sha256);
    }
    uint32_t magic = cold_u32le(data);
    uint32_t cputype = cold_u32le(data + 4);
    uint32_t filetype = cold_u32le(data + 12);
    uint32_t ncmds = cold_u32le(data + 16);
    uint32_t sizeofcmds = cold_u32le(data + 20);
    stats->darwin_internal_link_audit_magic = magic == (uint32_t)MH_MAGIC_64 ? 1 : 0;
    stats->darwin_internal_link_audit_cputype = cputype == (uint32_t)CPU_TYPE_ARM64 ? 1 : 0;
    stats->darwin_internal_link_audit_filetype = filetype == (uint32_t)MH_EXECUTE ? 1 : 0;
    if (!stats->darwin_internal_link_audit_magic ||
        !stats->darwin_internal_link_audit_cputype ||
        !stats->darwin_internal_link_audit_filetype ||
        sizeofcmds > (uint32_t)(file.len - 32)) {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "invalid Mach-O executable header");
        munmap((void *)file.ptr, (size_t)file.len);
        return;
    }
    int32_t pos = 32;
    int32_t linkedit_fileoff = 0;
    int32_t linkedit_filesize = 0;
    int32_t code_signature_dataoff = 0;
    int32_t code_signature_datasize = 0;
    for (uint32_t ci = 0; ci < ncmds; ci++) {
        if (pos < 0 || pos + 8 > file.len) {
            snprintf(stats->darwin_internal_link_audit_error,
                     sizeof(stats->darwin_internal_link_audit_error),
                     "Mach-O load command truncated");
            munmap((void *)file.ptr, (size_t)file.len);
            return;
        }
        uint32_t cmd = cold_u32le(data + pos);
        uint32_t cmdsize = cold_u32le(data + pos + 4);
        if (cmdsize < 8 || pos + (int32_t)cmdsize > file.len) {
            snprintf(stats->darwin_internal_link_audit_error,
                     sizeof(stats->darwin_internal_link_audit_error),
                     "Mach-O load command invalid");
            munmap((void *)file.ptr, (size_t)file.len);
            return;
        }
        if (cmd == LC_MAIN && cmdsize >= 24) {
            uint64_t entryoff = cold_u64le(data + pos + 8);
            stats->darwin_internal_link_audit_lc_main = 1;
            if (entryoff > 0 && entryoff <= (uint64_t)file.len) {
                stats->darwin_internal_link_audit_entryoff = (int32_t)entryoff;
            }
        } else if (cmd == LC_LOAD_DYLINKER && cmdsize >= 16) {
            uint32_t name_off = cold_u32le(data + pos + 8);
            if (name_off < cmdsize &&
                cold_macho_bounded_contains_cstr(data + pos + name_off,
                                                 (int32_t)(cmdsize - name_off),
                                                 "/usr/lib/dyld")) {
                stats->darwin_internal_link_audit_dyld = 1;
            }
        } else if (cmd == LC_LOAD_DYLIB && cmdsize >= 24) {
            uint32_t name_off = cold_u32le(data + pos + 8);
            if (name_off < cmdsize &&
                cold_macho_bounded_contains_cstr(data + pos + name_off,
                                                 (int32_t)(cmdsize - name_off),
                                                 "libSystem")) {
                stats->darwin_internal_link_audit_libsystem = 1;
            }
        } else if (cmd == LC_CODE_SIGNATURE && cmdsize >= 16) {
            stats->darwin_internal_link_audit_code_signature = 1;
            code_signature_dataoff = (int32_t)cold_u32le(data + pos + 8);
            code_signature_datasize = (int32_t)cold_u32le(data + pos + 12);
            stats->darwin_internal_link_audit_code_signature_dataoff = code_signature_dataoff;
            stats->darwin_internal_link_audit_code_signature_datasize = code_signature_datasize;
        } else if (cmd == LC_SEGMENT64 && cmdsize >= 72) {
            int32_t initprot = (int32_t)cold_u32le(data + pos + 60);
            if (memcmp(data + pos + 8, "__TEXT", 6) == 0) {
                stats->darwin_internal_link_audit_text_segment = 1;
                stats->darwin_internal_link_audit_text_initprot = initprot;
            } else if (memcmp(data + pos + 8, "__DATA", 6) == 0) {
                stats->darwin_internal_link_audit_data_segment = 1;
                stats->darwin_internal_link_audit_data_initprot = initprot;
            } else if (memcmp(data + pos + 8, "__LINKEDIT", 10) == 0) {
                stats->darwin_internal_link_audit_linkedit_segment = 1;
                stats->darwin_internal_link_audit_linkedit_initprot = initprot;
                linkedit_fileoff = (int32_t)cold_u64le(data + pos + 40);
                linkedit_filesize = (int32_t)cold_u64le(data + pos + 48);
                stats->darwin_internal_link_audit_linkedit_fileoff = linkedit_fileoff;
                stats->darwin_internal_link_audit_linkedit_filesize = linkedit_filesize;
            }
        }
        pos += (int32_t)cmdsize;
    }
    if (stats->darwin_internal_link_audit_code_signature) {
        int32_t sig_end = code_signature_dataoff + code_signature_datasize;
        int32_t linkedit_end = linkedit_fileoff + linkedit_filesize;
        if (code_signature_dataoff > 0 &&
            code_signature_datasize >= 8 &&
            linkedit_fileoff > 0 &&
            linkedit_filesize > 0 &&
            code_signature_dataoff >= linkedit_fileoff &&
            sig_end <= linkedit_end &&
            sig_end <= file.len) {
            stats->darwin_internal_link_audit_code_signature_in_linkedit = 1;
        }
        if (sig_end == file.len) {
            stats->darwin_internal_link_audit_code_signature_at_eof = 1;
        }
        if (code_signature_dataoff >= 0 &&
            code_signature_datasize >= 8 &&
            sig_end <= file.len &&
            cold_u32be(data + code_signature_dataoff) == 0xfade0cc0u) {
            stats->darwin_internal_link_audit_code_signature_superblob = 1;
            uint32_t super_len = cold_u32be(data + code_signature_dataoff + 4);
            uint32_t super_count = cold_u32be(data + code_signature_dataoff + 8);
            int32_t cd_off = -1;
            if (super_len == (uint32_t)code_signature_datasize &&
                super_count >= 1 &&
                code_signature_datasize >= 20) {
                for (uint32_t bi = 0; bi < super_count; bi++) {
                    int32_t index_pos = code_signature_dataoff + 12 + (int32_t)bi * 8;
                    if (index_pos + 8 > sig_end) break;
                    uint32_t blob_type = cold_u32be(data + index_pos);
                    uint32_t blob_off = cold_u32be(data + index_pos + 4);
                    if (blob_type == 0 && blob_off < (uint32_t)code_signature_datasize) {
                        cd_off = code_signature_dataoff + (int32_t)blob_off;
                        break;
                    }
                }
            }
            if (cd_off >= code_signature_dataoff &&
                cd_off + 44 <= sig_end &&
                cold_u32be(data + cd_off) == 0xfade0c02u) {
                int32_t cd_len = (int32_t)cold_u32be(data + cd_off + 4);
                int32_t hash_off = (int32_t)cold_u32be(data + cd_off + 16);
                int32_t n_special = (int32_t)cold_u32be(data + cd_off + 24);
                int32_t n_code = (int32_t)cold_u32be(data + cd_off + 28);
                int32_t code_limit = (int32_t)cold_u32be(data + cd_off + 32);
                int32_t hash_size = data[cd_off + 36];
                int32_t hash_type = data[cd_off + 37];
                int32_t page_size_log2 = data[cd_off + 39];
                stats->darwin_internal_link_audit_code_signature_code_directory = 1;
                stats->darwin_internal_link_audit_code_signature_hash_type = hash_type;
                stats->darwin_internal_link_audit_code_signature_hash_size = hash_size;
                stats->darwin_internal_link_audit_code_signature_page_size = page_size_log2;
                stats->darwin_internal_link_audit_code_signature_code_slots = n_code;
                stats->darwin_internal_link_audit_code_signature_code_limit = code_limit;
                int32_t expected_slots = 0;
                if (page_size_log2 >= 1 && page_size_log2 <= 30 && code_limit >= 0) {
                    int32_t page_size = 1 << page_size_log2;
                    expected_slots = (code_limit + page_size - 1) / page_size;
                    if (hash_type == 2 &&
                        hash_size == 32 &&
                        n_special == 0 &&
                        n_code == expected_slots &&
                        code_limit == code_signature_dataoff &&
                        cd_len >= hash_off + n_code * hash_size &&
                        cd_off + cd_len <= sig_end) {
                        bool hashes_match = true;
                        for (int32_t slot = 0; slot < n_code; slot++) {
                            int32_t page_off = slot * page_size;
                            int32_t page_len = code_limit - page_off;
                            uint8_t digest[32];
                            if (page_len > page_size) page_len = page_size;
                            if (page_len < 0) page_len = 0;
                            cold_sha256_bytes(data + page_off, (size_t)page_len, digest);
                            if (memcmp(digest,
                                       data + cd_off + hash_off + slot * hash_size,
                                       32) != 0) {
                                hashes_match = false;
                                break;
                            }
                        }
                        if (hashes_match) {
                            stats->darwin_internal_link_audit_code_signature_hash_coverage = 1;
                        }
                    }
                }
            }
        }
        if (!stats->darwin_internal_link_audit_code_signature_in_linkedit ||
            !stats->darwin_internal_link_audit_code_signature_at_eof ||
            !stats->darwin_internal_link_audit_code_signature_superblob ||
            !stats->darwin_internal_link_audit_code_signature_code_directory ||
            !stats->darwin_internal_link_audit_code_signature_hash_coverage) {
            snprintf(stats->darwin_internal_link_audit_code_signature_reason,
                     sizeof(stats->darwin_internal_link_audit_code_signature_reason),
                     "invalid_or_incomplete_code_signature_layout");
        } else {
            snprintf(stats->darwin_internal_link_audit_code_signature_reason,
                     sizeof(stats->darwin_internal_link_audit_code_signature_reason),
                     "embedded_adhoc_sha256_code_directory");
        }
    } else {
        snprintf(stats->darwin_internal_link_audit_code_signature_reason,
                 sizeof(stats->darwin_internal_link_audit_code_signature_reason),
                 "not_emitted_internal_link_probe_unsigned");
    }
    if (!stats->darwin_internal_link_audit_lc_main ||
        stats->darwin_internal_link_audit_entryoff <= 0 ||
        !stats->darwin_internal_link_audit_dyld ||
        !stats->darwin_internal_link_audit_libsystem ||
        !stats->darwin_internal_link_audit_text_segment ||
        !stats->darwin_internal_link_audit_linkedit_segment) {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "Mach-O executable audit missing required load command or mode");
        munmap((void *)file.ptr, (size_t)file.len);
        return;
    }
    stats->darwin_internal_link_audit_static_success = 1;
    if (stats->darwin_internal_link_audit_code_signature &&
        stats->darwin_internal_link_audit_code_signature_in_linkedit &&
        stats->darwin_internal_link_audit_code_signature_at_eof &&
        stats->darwin_internal_link_audit_code_signature_superblob &&
        stats->darwin_internal_link_audit_code_signature_code_directory &&
        stats->darwin_internal_link_audit_code_signature_hash_coverage &&
        stats->darwin_internal_link_audit_executable_bit) {
        stats->darwin_internal_link_audit_success = 1;
    } else if (!stats->darwin_internal_link_audit_executable_bit) {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "Mach-O static audit passed; executable mode not observable on this host");
    } else if (!stats->darwin_internal_link_audit_code_signature) {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "Mach-O static audit passed; code signature not emitted");
    } else {
        snprintf(stats->darwin_internal_link_audit_error,
                 sizeof(stats->darwin_internal_link_audit_error),
                 "Mach-O static audit passed; code signature layout invalid");
    }
    cold_write_darwin_validation_manifest(path, stats);
    munmap((void *)file.ptr, (size_t)file.len);
}

static bool cold_darwin_internal_link_static_ready(ColdCompileStats *stats) {
    if (!stats) return false;
    return stats->darwin_internal_link_probe_success &&
           stats->darwin_internal_link_audit_static_success &&
           stats->darwin_internal_link_audit_magic &&
           stats->darwin_internal_link_audit_cputype &&
           stats->darwin_internal_link_audit_filetype &&
           stats->darwin_internal_link_audit_lc_main &&
           stats->darwin_internal_link_audit_dyld &&
           stats->darwin_internal_link_audit_libsystem &&
           stats->darwin_internal_link_audit_code_signature &&
           stats->darwin_internal_link_audit_code_signature_in_linkedit &&
           stats->darwin_internal_link_audit_code_signature_at_eof &&
           stats->darwin_internal_link_audit_code_signature_superblob &&
           stats->darwin_internal_link_audit_code_signature_code_directory &&
           stats->darwin_internal_link_audit_code_signature_hash_coverage &&
           stats->darwin_internal_link_validation_manifest_success &&
           stats->darwin_internal_link_probe_path[0] != '\0' &&
           cold_file_exists_nonempty(stats->darwin_internal_link_probe_path);
}

static void cold_darwin_import_validation_result(ColdCompileStats *stats) {
    if (!stats) return;
    const char *result_path = getenv("CHENG_DARWIN_VALIDATION_RESULT");
    if (!result_path || result_path[0] == '\0') return;
    stats->darwin_internal_link_validation_result = 1;
    stats->darwin_internal_link_validation_result_success = 0;
    stats->darwin_internal_link_validation_result_error[0] = '\0';
    snprintf(stats->darwin_internal_link_validation_result_path,
             sizeof(stats->darwin_internal_link_validation_result_path),
             "%s", result_path);
    if (!cold_file_exists_nonempty(result_path)) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_file_missing");
        return;
    }
    char expected_size[64];
    snprintf(expected_size, sizeof(expected_size), "%lld",
             (long long)stats->darwin_internal_link_audit_artifact_size);
    bool version_ok = cold_file_key_equals(result_path, "validation_result_version", "1");
    bool target_ok = cold_file_key_equals(result_path, "target", "arm64-apple-darwin");
    bool size_match = stats->darwin_internal_link_audit_artifact_size > 0 &&
        cold_file_key_equals(result_path, "artifact_size", expected_size) &&
        cold_file_key_equals(result_path, "artifact_size_match", "1");
    bool sha_match = stats->darwin_internal_link_audit_artifact_sha256[0] != '\0' &&
        cold_file_key_equals(result_path, "artifact_sha256",
                             stats->darwin_internal_link_audit_artifact_sha256) &&
        cold_file_key_equals(result_path, "artifact_sha256_match", "1");
    bool codesign_ok = cold_file_key_equals(result_path, "codesign_verify", "1");
    bool runtime_ok = cold_file_key_equals(result_path, "runtime_execution_validated", "1");
    bool static_ok = cold_file_key_equals(result_path, "artifact_exists", "1") &&
        cold_file_key_equals(result_path, "chmod_755", "1") &&
        cold_file_key_equals(result_path, "lc_main", "1") &&
        cold_file_key_equals(result_path, "lc_code_signature", "1") &&
        cold_file_key_equals(result_path, "libsystem", "1");
    stats->darwin_internal_link_validation_result_version_match = version_ok ? 1 : 0;
    stats->darwin_internal_link_validation_result_target_match = target_ok ? 1 : 0;
    stats->darwin_internal_link_validation_result_sha256_match = sha_match ? 1 : 0;
    stats->darwin_internal_link_validation_result_size_match = size_match ? 1 : 0;
    stats->darwin_internal_link_validation_result_static_checks = static_ok ? 1 : 0;
    stats->darwin_internal_link_validation_result_codesign_verify = codesign_ok ? 1 : 0;
    stats->darwin_internal_link_validation_result_runtime_validated = runtime_ok ? 1 : 0;
    bool success_ok = cold_file_key_equals(result_path, "validation_result_success", "1");
    if (version_ok && target_ok && size_match && sha_match && codesign_ok && runtime_ok && static_ok &&
        success_ok) {
        stats->darwin_internal_link_validation_result_success = 1;
        stats->darwin_internal_link_promote_unverified_runtime_validated = 1;
        return;
    }
    if (!version_ok) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_schema_version_mismatch");
        return;
    }
    if (!target_ok) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_target_mismatch");
        return;
    }
    if (!size_match) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_artifact_size_mismatch");
        return;
    }
    if (!sha_match) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_artifact_sha256_mismatch");
        return;
    }
    if (!static_ok) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_static_checks_incomplete");
        return;
    }
    if (!codesign_ok) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_codesign_verify_missing");
        return;
    }
    if (!runtime_ok) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_runtime_not_validated");
        return;
    }
    if (!success_ok) {
        snprintf(stats->darwin_internal_link_validation_result_error,
                 sizeof(stats->darwin_internal_link_validation_result_error),
                 "result_success_missing");
        return;
    }
    snprintf(stats->darwin_internal_link_validation_result_error,
             sizeof(stats->darwin_internal_link_validation_result_error),
             "result_incomplete_or_mismatched");
}

static bool cold_darwin_promote_internal_link_unverified(const char *out_path,
                                                        ColdCompileStats *stats,
                                                        char *error_buf,
                                                        size_t error_cap) {
    if (!stats || !out_path || out_path[0] == '\0') {
        snprintf(error_buf, error_cap, "Darwin unverified promotion missing output");
        return false;
    }
    stats->darwin_internal_link_promote_unverified = 1;
    stats->darwin_internal_link_promote_unverified_success = 0;
    stats->darwin_internal_link_promote_unverified_runtime_validated = 0;
    stats->darwin_internal_link_promote_unverified_path[0] = '\0';
    stats->darwin_internal_link_promote_unverified_error[0] = '\0';
    if (!cold_darwin_internal_link_static_ready(stats)) {
        snprintf(stats->darwin_internal_link_promote_unverified_error,
                 sizeof(stats->darwin_internal_link_promote_unverified_error),
                 "static_signed_internal_link_audit_not_ready");
        snprintf(error_buf, error_cap, "Darwin unverified promotion static audit not ready");
        return false;
    }
    char probe_sha256[65];
    snprintf(probe_sha256, sizeof(probe_sha256), "%s",
             stats->darwin_internal_link_audit_artifact_sha256);
    int64_t probe_size = stats->darwin_internal_link_audit_artifact_size;
    if (!cold_copy_file_path(stats->darwin_internal_link_probe_path, out_path) ||
        !cold_file_exists_nonempty(out_path)) {
        snprintf(stats->darwin_internal_link_promote_unverified_error,
                 sizeof(stats->darwin_internal_link_promote_unverified_error),
                 "artifact_copy_failed");
        snprintf(error_buf, error_cap, "Darwin unverified promotion artifact copy failed");
        return false;
    }
    chmod(out_path, 0755);
    cold_macho_audit_provider_executable(out_path, stats);
    stats->darwin_internal_link_promote_unverified_sha256_match =
        (probe_sha256[0] != '\0' &&
         strcmp(probe_sha256, stats->darwin_internal_link_audit_artifact_sha256) == 0) ? 1 : 0;
    stats->darwin_internal_link_promote_unverified_size_match =
        (probe_size > 0 && probe_size == stats->darwin_internal_link_audit_artifact_size) ? 1 : 0;
    stats->darwin_internal_link_promote_unverified_manifest_exists =
        cold_file_exists_nonempty(stats->darwin_internal_link_validation_manifest_path) ? 1 : 0;
    stats->darwin_internal_link_promote_unverified_script_exists =
        cold_file_exists_nonempty(stats->darwin_internal_link_validation_script_path) ? 1 : 0;
    if (!cold_darwin_internal_link_static_ready(stats)) {
        snprintf(stats->darwin_internal_link_promote_unverified_error,
                 sizeof(stats->darwin_internal_link_promote_unverified_error),
                 "promoted_artifact_static_audit_failed");
        snprintf(error_buf, error_cap, "Darwin unverified promotion promoted artifact audit failed");
        return false;
    }
    if (!stats->darwin_internal_link_promote_unverified_sha256_match ||
        !stats->darwin_internal_link_promote_unverified_size_match ||
        !stats->darwin_internal_link_promote_unverified_manifest_exists ||
        !stats->darwin_internal_link_promote_unverified_script_exists) {
        snprintf(stats->darwin_internal_link_promote_unverified_error,
                 sizeof(stats->darwin_internal_link_promote_unverified_error),
                 "promotion_preflight_incomplete");
        snprintf(error_buf, error_cap, "Darwin unverified promotion preflight incomplete");
        return false;
    }
    cold_darwin_import_validation_result(stats);
    snprintf(stats->darwin_internal_link_promote_unverified_path,
             sizeof(stats->darwin_internal_link_promote_unverified_path),
             "%s", out_path);
    snprintf(stats->darwin_internal_link_promote_unverified_error,
             sizeof(stats->darwin_internal_link_promote_unverified_error),
             "%s", stats->darwin_internal_link_validation_result_success
                 ? "runtime_validated_by_import"
                 : "runtime_validation_required");
    stats->darwin_internal_link_promote_unverified_success = 1;
    stats->system_link = 0;
    return true;
}

static bool cold_link_macho_objects_with_darwin_imports(const char *primary_object,
                                                        const char *provider_objects,
                                                        const char *out_path,
                                                        const char *target,
                                                        ColdCompileStats *stats,
                                                        char *error_buf,
                                                        size_t error_cap) {
    if (!primary_object || !primary_object[0] || !provider_objects || !provider_objects[0] ||
        !out_path || !out_path[0] || !target || strcmp(target, "arm64-apple-darwin") != 0) {
        snprintf(error_buf, error_cap, "invalid Darwin internal provider link input");
        return false;
    }
    char paths_buf[32768];
    size_t plen = strlen(provider_objects);
    if (plen >= sizeof(paths_buf)) {
        snprintf(error_buf, error_cap, "Darwin provider object list too long");
        return false;
    }
    ColdMachODirectLinkObject objects[129];
    memset(objects, 0, sizeof(objects));
    int32_t object_count = 1;
    int32_t provider_count = 0;
    objects[0].path = primary_object;
    objects[0].span = source_open(primary_object);
    if (objects[0].span.len <= 0 ||
        !cold_read_macho_relocatable_view(objects[0].span.ptr, objects[0].span.len,
                                          target, &objects[0].view)) {
        snprintf(error_buf, error_cap, "primary Mach-O object read failed");
        if (objects[0].span.len > 0) munmap((void *)objects[0].span.ptr, (size_t)objects[0].span.len);
        return false;
    }
    memcpy(paths_buf, provider_objects, plen + 1);
    char *p = paths_buf;
    while (p && *p) {
        char *comma = strchr(p, ',');
        if (comma) *comma = '\0';
        if (*p) {
            if (object_count >= 129) {
                snprintf(error_buf, error_cap, "too many Darwin provider objects");
                goto fail;
            }
            objects[object_count].path = p;
            objects[object_count].span = source_open(p);
            if (objects[object_count].span.len <= 0 ||
                !cold_read_macho_relocatable_view(objects[object_count].span.ptr,
                                                  objects[object_count].span.len,
                                                  target, &objects[object_count].view)) {
                snprintf(error_buf, error_cap, "Darwin provider object read failed");
                goto fail;
            }
            object_count++;
            provider_count++;
        }
        p = comma ? comma + 1 : 0;
    }
    if (provider_count <= 0) {
        snprintf(error_buf, error_cap, "no Darwin provider objects");
        goto fail;
    }
    int32_t total_words = 0;
    for (int32_t oi = 0; oi < object_count; oi++) {
        objects[oi].base_word = total_words;
        total_words += objects[oi].view.word_count;
    }
    const char *imports[512];
    int32_t import_count = 0;
    int32_t unresolved_count = 0;
    char first_unresolved[COLD_NAME_CAP];
    first_unresolved[0] = '\0';
    for (int32_t oi = 0; oi < object_count; oi++) {
        ColdMachOObjectView *obj = &objects[oi].view;
        for (int32_t ri = 0; ri < obj->reloc_count; ri++) {
            ColdMachORelocation reloc;
            if (!cold_macho_reloc_at(obj, ri, &reloc)) {
                snprintf(error_buf, error_cap, "Mach-O relocation decode failed");
                goto fail;
            }
            uint32_t sym_idx = reloc.r_symbolnum;
            if (sym_idx >= (uint32_t)obj->sym_count) {
                snprintf(error_buf, error_cap, "Mach-O relocation symbol out of range");
                goto fail;
            }
            const char *sym_name = cold_macho_symbol_name(obj, sym_idx);
            if (!sym_name || sym_name[0] == '\0') {
                snprintf(error_buf, error_cap, "Mach-O relocation symbol missing");
                goto fail;
            }
            ColdMachOSymbol symbol;
            if (!cold_macho_symbol_at(obj, (int32_t)sym_idx, &symbol)) {
                snprintf(error_buf, error_cap, "Mach-O relocation symbol decode failed");
                goto fail;
            }
            int32_t target_word = -1;
            if ((symbol.n_type & 0x0e) == 0x0e && symbol.n_sect != 0) {
                continue;
            }
            if (cold_macho_direct_find_defined_symbol(objects, object_count, oi, sym_name,
                                                      &target_word)) {
                continue;
            }
            if (cold_macho_direct_symbol_allowed_import(sym_name)) {
                int32_t import_index = -1;
                if (!cold_macho_direct_add_import(imports, &import_count, 512,
                                                  sym_name, &import_index)) {
                    snprintf(error_buf, error_cap, "too many Darwin imports");
                    goto fail;
                }
                (void)import_index;
                continue;
            }
            unresolved_count++;
            if (first_unresolved[0] == '\0') {
                const char *export_name = (sym_name[0] == '_' && sym_name[1] != '\0') ? sym_name + 1 : sym_name;
                snprintf(first_unresolved, sizeof(first_unresolved), "%s", export_name);
            }
        }
    }
    if (unresolved_count > 0) {
        if (stats) {
            stats->unresolved_symbol_count = unresolved_count;
            snprintf(stats->first_unresolved_symbol,
                     sizeof(stats->first_unresolved_symbol),
                     "%s", first_unresolved);
        }
        snprintf(error_buf, error_cap, "Darwin provider dependency missing: %s", first_unresolved);
        goto fail;
    }
    int32_t linked_words = total_words + import_count * 3;
    uint32_t *words = (uint32_t *)calloc((size_t)linked_words, sizeof(uint32_t));
    if (!words) {
        snprintf(error_buf, error_cap, "Darwin provider link allocation failed");
        goto fail;
    }
    for (int32_t oi = 0; oi < object_count; oi++) {
        memcpy(words + objects[oi].base_word, objects[oi].view.words,
               (size_t)objects[oi].view.word_count * sizeof(uint32_t));
    }
    const int32_t code_off = 4096;
    uint64_t code_vmaddr = 0x100000000ULL + (uint64_t)code_off;
    int32_t stub_base_word = total_words;
    for (int32_t oi = 0; oi < object_count; oi++) {
        ColdMachOObjectView *obj = &objects[oi].view;
        for (int32_t ri = 0; ri < obj->reloc_count; ri++) {
            ColdMachORelocation reloc;
            if (!cold_macho_reloc_at(obj, ri, &reloc)) {
                free(words);
                snprintf(error_buf, error_cap, "Mach-O relocation decode failed");
                goto fail;
            }
            uint32_t sym_idx = reloc.r_symbolnum;
            int32_t r_address = reloc.r_address;
            if (sym_idx >= (uint32_t)obj->sym_count || r_address < 0 ||
                (r_address % 4) != 0 || r_address / 4 >= obj->word_count) {
                free(words);
                snprintf(error_buf, error_cap, "Mach-O relocation out of range");
                goto fail;
            }
            const char *sym_name = cold_macho_symbol_name(obj, sym_idx);
            ColdMachOSymbol symbol;
            if (!cold_macho_symbol_at(obj, (int32_t)sym_idx, &symbol)) {
                free(words);
                snprintf(error_buf, error_cap, "Mach-O relocation symbol decode failed");
                goto fail;
            }
            int32_t target_word = -1;
            if ((symbol.n_type & 0x0e) == 0x0e && symbol.n_sect != 0) {
                uint64_t value = symbol.n_value;
                if ((value % 4) != 0 || value / 4 >= (uint64_t)obj->word_count) {
                    free(words);
                    snprintf(error_buf, error_cap, "Mach-O defined relocation target invalid");
                    goto fail;
                }
                target_word = objects[oi].base_word + (int32_t)(value / 4);
            } else if (cold_macho_direct_find_defined_symbol(objects, object_count, oi,
                                                            sym_name, &target_word)) {
                if (stats && oi == 0) stats->provider_resolved_symbol_count++;
            } else {
                int32_t import_index = cold_macho_direct_import_index(imports, import_count, sym_name);
                if (import_index < 0) {
                    free(words);
                    snprintf(error_buf, error_cap, "Darwin import missing after scan");
                    goto fail;
                }
                target_word = stub_base_word + import_index * 3;
            }
            int32_t word_pos = objects[oi].base_word + r_address / 4;
            if (!cold_macho_direct_apply_reloc(words, linked_words, word_pos, target_word,
                                               reloc.r_type, code_vmaddr)) {
                free(words);
                snprintf(error_buf, error_cap,
                         "Mach-O relocation apply failed: object=%d reloc=%d symbol=%s type=%u pcrel=%u length=%u extern=%u address=%d word_pos=%d target_word=%d linked_words=%d",
                         oi,
                         ri,
                         sym_name ? sym_name : "",
                         reloc.r_type,
                         reloc.r_pcrel,
                         reloc.r_length,
                         reloc.r_extern,
                         r_address,
                         word_pos,
                         target_word,
                         linked_words);
                goto fail;
            }
            if (stats) stats->link_reloc_count++;
        }
    }
    if (!cold_macho_write_provider_executable(out_path, words, total_words,
                                              imports, import_count,
                                              error_buf, error_cap)) {
        free(words);
        goto fail;
    }
    free(words);
    if (stats) {
        stats->link_object = 1;
        stats->provider_object_count = provider_count;
        stats->provider_archive = 0;
        stats->provider_archive_member_count = 0;
        stats->provider_export_count = import_count;
        stats->unresolved_symbol_count = 0;
        stats->first_unresolved_symbol[0] = '\0';
        stats->code_words = linked_words;
        stats->system_link = 0;
    }
    for (int32_t oi = 0; oi < object_count; oi++) {
        if (objects[oi].span.len > 0) munmap((void *)objects[oi].span.ptr, (size_t)objects[oi].span.len);
    }
    return true;

fail:
    for (int32_t oi = 0; oi < object_count; oi++) {
        if (objects[oi].span.len > 0) munmap((void *)objects[oi].span.ptr, (size_t)objects[oi].span.len);
    }
    return false;
}

static bool cold_link_relocs_for_macho_object(ColdMachOObjectView *obj,
                                               uint32_t *words,
                                               int32_t total_words,
                                               int32_t base_word,
                                               ColdMachOObjectView *primary,
                                               ColdProviderArchiveView *archive,
                                               bool primary_object,
                                               ColdCompileStats *stats) {
    for (int32_t i = 0; i < obj->reloc_count; i++) {
        ColdMachORelocation reloc;
        if (!cold_macho_reloc_at(obj, i, &reloc)) return false;
        uint32_t sym_idx = reloc.r_symbolnum;
        if (sym_idx >= (uint32_t)obj->sym_count) return false;
        int32_t r_address = reloc.r_address;
        if (r_address < 0 || (r_address % 4) != 0) return false;
        int32_t word_offset = r_address / 4;
        if (word_offset >= obj->word_count) return false;
        ColdMachOSymbol symbol;
        if (!cold_macho_symbol_at(obj, (int32_t)sym_idx, &symbol)) return false;
        int32_t target_word = -1;
        const char *sym_name = cold_macho_symbol_name(obj, sym_idx);
        if (!sym_name || sym_name[0] == '\0') return false;
        const char *export_name = (sym_name[0] == '_' && sym_name[1] != '\0') ? sym_name + 1 : sym_name;

        if ((symbol.n_type & 0x0e) == 0x0e && symbol.n_sect != 0) {
            uint64_t value = symbol.n_value;
            if ((value % 4) != 0 || value / 4 >= (uint64_t)obj->word_count) return false;
            target_word = base_word + (int32_t)(value / 4);
        } else {
            if (primary_object) {
                int32_t member_index = cold_provider_archive_find_export(archive, export_name);
                if (member_index == -2) {
                    cold_stats_provider_error_name(stats, "provider export ambiguous", export_name);
                    return false;
                }
                if (member_index >= 0) {
                    ColdProviderArchiveMember *member = &archive->members[member_index];
                    if (!member->selected) return false;
                    int32_t provider_word = -1;
                    if (!cold_macho_defined_symbol_word(&member->macho_view, sym_name, &provider_word))
                        return false;
                    if (provider_word < 0 || provider_word >= member->macho_view.word_count)
                        return false;
                    target_word = member->base_word + provider_word;
                    if (stats) stats->provider_resolved_symbol_count++;
                }
            } else {
                int32_t primary_word = -1;
                if (primary &&
                    cold_macho_defined_symbol_word(primary, sym_name, &primary_word)) {
                    target_word = primary_word;
                } else if (cold_provider_archive_find_selected_definition(archive,
                                                                          export_name,
                                                                          &target_word)) {
                    if (stats) stats->provider_resolved_symbol_count++;
                }
            }
            if (target_word < 0) {
                if (stats) {
                    stats->unresolved_symbol_count++;
                    if (stats->first_unresolved_symbol[0] == '\0' && export_name) {
                        snprintf(stats->first_unresolved_symbol,
                                 sizeof(stats->first_unresolved_symbol),
                                 "%s", export_name);
                    }
                    const char *prefix = primary_object
                        ? "provider export missing"
                        : cold_provider_external_dependency_symbol(export_name)
                            ? "provider external dependency unsupported"
                            : "provider dependency missing";
                    cold_stats_provider_error_name(stats, prefix, export_name);
                }
                continue;
            }
        }
        int32_t word_pos = base_word + word_offset;
        if (!cold_apply_macho_reloc(words, total_words, word_pos, target_word, reloc.r_type))
            return false;
        if (stats) stats->link_reloc_count++;
    }
    return true;
}

static bool cold_link_elf64_object_with_provider_archive(const char *object_path,
                                                         const char *archive_path,
                                                         const char *out_path,
                                                         const char *target,
                                                         ColdCompileStats *stats) {
    uint64_t start_us = cold_now_us();
    Span primary_span = source_open(object_path);
    Span archive_span = source_open(archive_path);
    uint32_t *words = 0;
    ColdProviderArchiveView archive = {0};
    bool ok = false;
    if (primary_span.len <= 0) {
        cold_stats_provider_error(stats, "link object open failed");
        goto done;
    }
    if (archive_span.len <= 0) {
        cold_stats_provider_error(stats, "provider archive open/header failed");
        goto done;
    }
    ColdElfObjectView primary;
    if (!cold_read_elf64_relocatable_view(primary_span.ptr, primary_span.len, target, &primary)) {
        cold_stats_provider_error(stats, "link object machine mismatch");
        goto done;
    }
    int32_t member_count = 0;
    uint64_t archive_hash = 0;
    char verify_error[COLD_NAME_CAP] = {0};
    if (!cold_verify_provider_archive(archive_path, target, &member_count, &archive_hash,
                                      verify_error, sizeof(verify_error))) {
        cold_stats_provider_error(stats, verify_error);
        goto done;
    }
    if (member_count < 1) goto done;
    char parse_error[COLD_NAME_CAP] = {0};
    if (!cold_parse_provider_archive_view(archive_span, target, member_count,
                                          archive_hash, &archive,
                                          parse_error, sizeof(parse_error))) {
        cold_stats_provider_error(stats, parse_error[0] ? parse_error : "provider archive parse failed");
        goto done;
    }
    bool changed = true;
    int32_t guard = 0;
    while (changed) {
        changed = false;
        guard++;
        if (guard > archive.member_count + 1) goto done;
        for (int32_t ri = 0; ri < primary.reloc_count; ri++) {
            const Elf64_Rela *reloc = &primary.relas[ri];
            uint32_t sym_index = (uint32_t)(reloc->r_info >> 32);
            if (sym_index >= (uint32_t)primary.sym_count) goto done;
            const Elf64_Sym *sym = &primary.syms[sym_index];
            if (sym->st_shndx != 0) continue;
            const char *sym_name = cold_elf_symbol_name(&primary, sym_index);
            int32_t member_index = cold_provider_archive_find_export(&archive, sym_name);
            if (member_index == -2) {
                cold_stats_provider_error_name(stats, "provider export ambiguous", sym_name);
                goto done;
            }
            if (member_index >= 0 && !archive.members[member_index].selected) {
                archive.members[member_index].selected = 1;
                changed = true;
            }
        }
        for (int32_t mi = 0; mi < archive.member_count; mi++) {
            ColdProviderArchiveMember *member = &archive.members[mi];
            if (!member->selected) continue;
            for (int32_t ri = 0; ri < member->view.reloc_count; ri++) {
                const Elf64_Rela *reloc = &member->view.relas[ri];
                uint32_t sym_index = (uint32_t)(reloc->r_info >> 32);
                if (sym_index >= (uint32_t)member->view.sym_count) goto done;
                const Elf64_Sym *sym = &member->view.syms[sym_index];
                if (sym->st_shndx != 0) continue;
                const char *sym_name = cold_elf_symbol_name(&member->view, sym_index);
                int32_t primary_word = -1;
                int32_t primary_byte = -1;
                if (primary.machine == EM_X86_64) {
                    bool primary_is_data = false;
                    if (cold_elf_defined_symbol_offset_any(&primary, sym_name,
                                                           &primary_is_data,
                                                           &primary_byte)) {
                        (void)primary_is_data;
                        continue;
                    }
                } else if (cold_elf_defined_symbol_word(&primary, sym_name, &primary_word)) {
                    continue;
                }
                int32_t dep_index = cold_provider_archive_find_export(&archive, sym_name);
                if (dep_index == -2) {
                    cold_stats_provider_error_name(stats, "provider export ambiguous", sym_name);
                    goto done;
                }
                if (dep_index >= 0 && !archive.members[dep_index].selected) {
                    archive.members[dep_index].selected = 1;
                    changed = true;
                }
            }
        }
    }

    int32_t selected_count = 0;
    int32_t text_words = primary.word_count;
    for (int32_t mi = 0; mi < archive.member_count; mi++) {
        ColdProviderArchiveMember *member = &archive.members[mi];
        if (!member->selected) continue;
        member->base_word = text_words;
        member->data_base_byte = -1;
        text_words += member->view.word_count;
        selected_count++;
    }
    int32_t total_words = text_words;
    int32_t primary_data_base_byte = -1;
    if (primary.machine == EM_X86_64 || primary.machine == EM_AARCH64) {
        int32_t data_cursor = elf64_align_i32(text_words * 4, 8);
        if (primary.data_size > 0) {
            primary_data_base_byte = data_cursor;
            data_cursor = elf64_align_i32(data_cursor + primary.data_size, 8);
        }
        for (int32_t mi = 0; mi < archive.member_count; mi++) {
            ColdProviderArchiveMember *member = &archive.members[mi];
            if (!member->selected) continue;
            if (member->view.data_size > 0) {
                member->data_base_byte = data_cursor;
                data_cursor = elf64_align_i32(data_cursor + member->view.data_size, 8);
            }
        }
        total_words = elf64_align_i32(data_cursor, 4) / 4;
    }
    if (cold_selected_elf_providers_conflict_with_primary(&primary, &archive, stats)) goto done;
    words = (uint32_t *)calloc(total_words > 0 ? (size_t)total_words : 1, sizeof(uint32_t));
    if (!words) {
        cold_stats_provider_error(stats, "provider internal link allocation failed");
        goto done;
    }
    memcpy(words, primary.words, (size_t)primary.word_count * sizeof(uint32_t));
    if ((primary.machine == EM_X86_64 || primary.machine == EM_AARCH64) &&
        primary.data_size > 0) {
        if (primary_data_base_byte < 0 ||
            primary_data_base_byte + primary.data_size > total_words * 4) {
            cold_stats_provider_error(stats, "provider primary data layout invalid");
            goto done;
        }
        if (primary.data_bytes) {
            memcpy((uint8_t *)words + primary_data_base_byte, primary.data_bytes,
                   (size_t)primary.data_size);
        }
    }
    for (int32_t mi = 0; mi < archive.member_count; mi++) {
        ColdProviderArchiveMember *member = &archive.members[mi];
        if (!member->selected) continue;
        memcpy(words + member->base_word, member->view.words,
               (size_t)member->view.word_count * sizeof(uint32_t));
        if ((primary.machine == EM_X86_64 || primary.machine == EM_AARCH64) &&
            member->view.data_size > 0) {
            if (member->data_base_byte < 0 ||
                member->data_base_byte + member->view.data_size > total_words * 4) {
                cold_stats_provider_error(stats, "provider data layout invalid");
                goto done;
            }
            if (member->view.data_bytes) {
                memcpy((uint8_t *)words + member->data_base_byte, member->view.data_bytes,
                       (size_t)member->view.data_size);
            }
        }
    }
    if (stats) {
        stats->link_object = 1;
        stats->provider_archive = 1;
        stats->provider_object_count = selected_count;
        stats->provider_archive_member_count = archive.member_count;
        stats->provider_archive_hash = archive_hash;
        stats->provider_export_count = archive.export_count;
    }
    if (!cold_link_relocs_for_object(&primary, words, total_words, 0,
                                     primary_data_base_byte, &primary,
                                     primary_data_base_byte, &archive,
                                     true, stats)) {
        cold_stats_provider_error(stats, "provider internal primary relocation failed");
        goto done;
    }
    if (stats && stats->unresolved_symbol_count != 0) goto done;
    for (int32_t mi = 0; mi < archive.member_count; mi++) {
        ColdProviderArchiveMember *member = &archive.members[mi];
        if (!member->selected) continue;
        if (!cold_link_relocs_for_object(&member->view, words, total_words,
                                         member->base_word, member->data_base_byte,
                                         &primary, primary_data_base_byte,
                                         &archive, false, stats)) {
            cold_stats_provider_error(stats, "provider internal member relocation failed");
            goto done;
        }
    }
    if (stats && stats->unresolved_symbol_count != 0) goto done;
    if (primary.machine == EM_X86_64) {
        int32_t main_byte = -1;
        if (!cold_elf_defined_symbol_byte(&primary, "main", &main_byte))
            (void)cold_elf_defined_symbol_byte(&primary, "_main", &main_byte);
        if (main_byte < 0) {
            cold_stats_provider_error(stats, "x86_64 linked main symbol missing");
            goto done;
        }
        X64Code shim;
        x64_init(&shim, 128);
        shim.linux_syscalls = true;
        x64_push_r64(&shim, 5);
        x64_mov_r64_r64(&shim, 5, 4);
        x64_mov_r64_r64(&shim, 12, 7);
        x64_mov_r64_r64(&shim, 13, 6);
        int32_t call_pos = shim.len + 1;
        x64_call_rel32(&shim, 0);
        x64_mov_r64_r64(&shim, 7, 0);
        x64_mov_r32_imm32(&shim, 0, 231);
        x64_syscall(&shim);
        while ((shim.len & 3) != 0) x64_emit1(&shim, 0x90);
        x64_patch_call_rel32(&shim, call_pos, shim.len + main_byte);

        int32_t shim_words = (shim.len + 3) / 4;
        int32_t combined_words = shim_words + total_words;
        uint32_t *combined = (uint32_t *)calloc((size_t)combined_words, sizeof(uint32_t));
        if (!combined) {
            cold_stats_provider_error(stats, "x86_64 provider shim allocation failed");
            x64_release(&shim);
            goto done;
        }
        if (x64_pack_words(&shim, combined, shim_words) != shim_words) {
            cold_stats_provider_error(stats, "x86_64 provider shim pack failed");
            x64_release(&shim);
            free(combined);
            goto done;
        }
        memcpy(combined + shim_words, words, (size_t)total_words * sizeof(uint32_t));
        x64_release(&shim);
        free(words);
        words = combined;
        total_words = combined_words;
        if (stats) {
            snprintf(stats->system_link_exec_scope, sizeof(stats->system_link_exec_scope),
                     "cold_elf_x86_64_provider_internal");
        }
    }
    bool write_ok = (primary.machine == EM_X86_64 || primary.machine == EM_AARCH64)
        ? cold_write_elf_exec_image(out_path, (const uint8_t *)words,
                                    total_words * 4, primary.machine, 7)
        : elf_write_exec(out_path, words, total_words, primary.machine);
    if (!write_ok) {
        cold_stats_provider_error(stats, "provider internal ELF write failed");
        goto done;
    }
    if (!cold_write_internal_elf_exec_map(out_path, target, primary.machine,
                                          total_words,
                                          stats ? stats->link_reloc_count : 0)) {
        cold_stats_provider_error(stats, "provider internal ELF map write failed");
        goto done;
    }
    if (stats) {
        stats->code_words = total_words;
        stats->elapsed_us = cold_now_us() - start_us;
        stats->emit_us = stats->elapsed_us;
    }
    ok = true;

done:
    if (words) free(words);
    cold_provider_archive_view_free(&archive);
    if (primary_span.len > 0) munmap((void *)primary_span.ptr, (size_t)primary_span.len);
    if (archive_span.len > 0) munmap((void *)archive_span.ptr, (size_t)archive_span.len);
    return ok;
}

static bool cold_link_macho_object_with_provider_archive(const char *object_path,
                                                          const char *archive_path,
                                                          const char *out_path,
                                                          const char *target,
                                                          ColdCompileStats *stats) {
    uint64_t start_us = cold_now_us();
    Span primary_span = source_open(object_path);
    Span archive_span = source_open(archive_path);
    uint32_t *words = 0;
    ColdProviderArchiveView archive = {0};
    bool ok = false;
    if (primary_span.len <= 0) {
        cold_stats_provider_error(stats, "link object open failed");
        goto done;
    }
    if (archive_span.len <= 0) {
        cold_stats_provider_error(stats, "provider archive open/header failed");
        goto done;
    }
    ColdMachOObjectView primary;
    if (!cold_read_macho_relocatable_view(primary_span.ptr, primary_span.len, target, &primary)) {
        cold_stats_provider_error(stats, "link object machine mismatch");
        goto done;
    }
    int32_t member_count = 0;
    uint64_t archive_hash = 0;
    char verify_error[COLD_NAME_CAP] = {0};
    if (!cold_verify_provider_archive(archive_path, target, &member_count, &archive_hash,
                                      verify_error, sizeof(verify_error))) {
        cold_stats_provider_error(stats, verify_error);
        goto done;
    }
    if (member_count < 1) goto done;
    char parse_error[COLD_NAME_CAP] = {0};
    if (!cold_parse_provider_archive_view(archive_span, target, member_count, archive_hash,
                                          &archive, parse_error, sizeof(parse_error))) {
        cold_stats_provider_error(stats, parse_error[0] ? parse_error : "provider archive parse failed");
        goto done;
    }
    {
        bool changed = true;
        int32_t guard = 0;
        while (changed) {
            changed = false;
            guard++;
            if (guard > archive.member_count + 1) goto done;
            for (int32_t ri = 0; ri < primary.reloc_count; ri++) {
                ColdMachORelocation reloc;
                if (!cold_macho_reloc_at(&primary, ri, &reloc)) goto done;
                uint32_t sym_idx = reloc.r_symbolnum;
                if (sym_idx >= (uint32_t)primary.sym_count) goto done;
                ColdMachOSymbol symbol;
                if (!cold_macho_symbol_at(&primary, (int32_t)sym_idx, &symbol)) goto done;
                if (symbol.n_sect != 0) continue;
                const char *sn = cold_macho_symbol_name(&primary, sym_idx);
                if (!sn || sn[0] == '\0') continue;
                const char *export_name = (sn[0] == '_' && sn[1] != '\0') ? sn + 1 : sn;
                int32_t mi = cold_provider_archive_find_export(&archive, export_name);
                if (mi == -2) {
                    cold_stats_provider_error_name(stats, "provider export ambiguous", export_name);
                    goto done;
                }
                if (mi >= 0 && !archive.members[mi].selected) {
                    archive.members[mi].selected = 1;
                    changed = true;
                }
            }
            for (int32_t mi = 0; mi < archive.member_count; mi++) {
                if (!archive.members[mi].selected) continue;
                ColdMachOObjectView *mview = &archive.members[mi].macho_view;
                for (int32_t ri = 0; ri < mview->reloc_count; ri++) {
                    ColdMachORelocation reloc;
                    if (!cold_macho_reloc_at(mview, ri, &reloc)) goto done;
                    uint32_t sym_idx = reloc.r_symbolnum;
                    if (sym_idx >= (uint32_t)mview->sym_count) goto done;
                    ColdMachOSymbol symbol;
                    if (!cold_macho_symbol_at(mview, (int32_t)sym_idx, &symbol)) goto done;
                    if (symbol.n_sect != 0) continue;
                    const char *sn = cold_macho_symbol_name(mview, sym_idx);
                    if (!sn || sn[0] == '\0') continue;
                    if (cold_macho_find_defined_symbol(&primary, sn) >= 0) continue;
                    bool defined_elsewhere = false;
                    for (int32_t mj = 0; mj < archive.member_count; mj++) {
                        if (mj == mi || !archive.members[mj].selected) continue;
                        if (cold_macho_find_defined_symbol(&archive.members[mj].macho_view, sn) >= 0) {
                            defined_elsewhere = true;
                            break;
                        }
                    }
                    if (defined_elsewhere) continue;
                    const char *export_name = (sn[0] == '_' && sn[1] != '\0') ? sn + 1 : sn;
                    int32_t dep = cold_provider_archive_find_export(&archive, export_name);
                    if (dep == -2) {
                        cold_stats_provider_error_name(stats, "provider export ambiguous", export_name);
                        goto done;
                    }
                    if (dep >= 0 && !archive.members[dep].selected) {
                        archive.members[dep].selected = 1;
                        changed = true;
                    }
                }
            }
        }
    }

    int32_t selected_count = 0;
    int32_t total_words = primary.word_count;
    for (int32_t mi = 0; mi < archive.member_count; mi++) {
        ColdProviderArchiveMember *member = &archive.members[mi];
        if (!member->selected) continue;
        member->base_word = total_words;
        total_words += member->macho_view.word_count;
        selected_count++;
    }
    if (cold_selected_macho_providers_conflict_with_primary(&primary, &archive, stats)) goto done;
    words = (uint32_t *)calloc(total_words > 0 ? (size_t)total_words : 1, sizeof(uint32_t));
    if (!words) goto done;
    memcpy(words, primary.words, (size_t)primary.word_count * sizeof(uint32_t));
    for (int32_t mi = 0; mi < archive.member_count; mi++) {
        ColdProviderArchiveMember *member = &archive.members[mi];
        if (!member->selected) continue;
        memcpy(words + member->base_word, member->macho_view.words,
               (size_t)member->macho_view.word_count * sizeof(uint32_t));
    }
    if (stats) {
        stats->link_object = 1;
        stats->provider_archive = 1;
        stats->provider_object_count = selected_count;
        stats->provider_archive_member_count = archive.member_count;
        stats->provider_archive_hash = archive_hash;
        stats->provider_export_count = archive.export_count;
    }
    if (!cold_link_relocs_for_macho_object(&primary, words, total_words, 0,
                                           &primary, &archive, true, stats)) goto done;
    if (stats && stats->unresolved_symbol_count != 0) goto done;
    for (int32_t mi = 0; mi < archive.member_count; mi++) {
        ColdProviderArchiveMember *member = &archive.members[mi];
        if (!member->selected) continue;
        if (!cold_link_relocs_for_macho_object(&member->macho_view, words, total_words,
                                               member->base_word, &primary,
                                               &archive, false, stats)) goto done;
    }
    if (stats && stats->unresolved_symbol_count != 0) goto done;
    if (!macho_write_exec(out_path, words, total_words,
                          0, 0, 0, 0, 0, 0, 0)) goto done;
    if (stats) {
        stats->code_words = total_words;
        stats->elapsed_us = cold_now_us() - start_us;
        stats->emit_us = stats->elapsed_us;
    }
    ok = true;

done:
    if (words) free(words);
    cold_provider_archive_view_free(&archive);
    if (primary_span.len > 0) munmap((void *)primary_span.ptr, (size_t)primary_span.len);
    if (archive_span.len > 0) munmap((void *)archive_span.ptr, (size_t)archive_span.len);
    return ok;
}


