/* mmap/munmap join the linkerless syscall provider only on x86_64 (real
   syscall wrappers, cf. cold_emit_linux_x86_64_mmap_provider). The aarch64
   emitter stubs raw libc with brk placeholders, so admitting them there would
   silently convert today's honest link-time failure into a runtime trap;
   aarch64 keeps its current failure mode until its emitter grows the same
   wrappers. */
static bool cold_linux_x86_64_syscall_provider_extra_symbol(const char *symbol) {
    if (!symbol || symbol[0] == '\0') return false;
    return strcmp(symbol, "mmap") == 0 || strcmp(symbol, "munmap") == 0;
}

bool cold_darwin_syscall_provider_exports_symbol_len(const char *symbol, int32_t len) {
    if (!symbol || len <= 0) return false;
    /* Strip leading '_' (Darwin Mach-O convention) for matching */
    const char *name = symbol;
    int32_t name_len = len;
    if (name[0] == '_') { name++; name_len--; }
    if (name_len <= 0) return false;
    static const char *syscalls[] = {
        "cheng_getpid", "cheng_gettimeofday",
        "cheng_unlink",
        "kill",
        "__cheng_call_indirect_void",
        "__cheng_call_indirect_i32",
        "__cheng_runtime_atomic_cas_i32",
        "__cheng_runtime_atomic_store_i32",
        "__cheng_runtime_atomic_load_i32",
        "__cheng_runtime_atomic_add_i32",
        "cheng_native_af_inet_bridge",
        "cheng_native_af_inet6_bridge",
    };
    for (size_t i = 0; i < sizeof(syscalls) / sizeof(syscalls[0]); i++) {
        size_t sl = strlen(syscalls[i]);
        if ((int32_t)sl == name_len && memcmp(name, syscalls[i], sl) == 0) return true;
    }
    return false;
}

static bool cold_darwin_syscall_provider_exports_symbol(const char *symbol) {
    if (!symbol || symbol[0] == '\0') return false;
    if (symbol[0] == '_') symbol++;
    if (symbol[0] == '\0') return false;
    static const char *syscalls[] = {
        "cheng_getpid",
        "cheng_gettimeofday",
        "cheng_unlink",
        "kill",
        "__cheng_call_indirect_void",
        "__cheng_call_indirect_i32",
        "__cheng_runtime_atomic_cas_i32",
        "__cheng_runtime_atomic_store_i32",
        "__cheng_runtime_atomic_load_i32",
        "__cheng_runtime_atomic_add_i32",
        "cheng_native_af_inet_bridge",
        "cheng_native_af_inet6_bridge",
    };
    for (size_t i = 0; i < sizeof(syscalls) / sizeof(syscalls[0]); i++) {
        if (strcmp(symbol, syscalls[i]) == 0) return true;
    }
    return false;
}

static bool cold_source_has_exportc_symbol(const char *path, const char *symbol) {
    if (!path || !symbol || symbol[0] == '\0') return false;
    Span source = source_open(path);
    if (source.len <= 0) return false;
    bool found = false;
    int32_t pos = 0;
    while (pos < source.len) {
        int32_t start = pos;
        while (pos < source.len && source.ptr[pos] != '\n') pos++;
        int32_t end = pos;
        if (pos < source.len) pos++;
        Span line = span_trim(span_sub(source, start, end));
        Span export_name = {0};
        bool has_export = cold_parse_c_symbol_attr_anywhere(line, "@exportc", &export_name);
        if (has_export &&
            export_name.len == (int32_t)strlen(symbol) &&
            memcmp(export_name.ptr, symbol, (size_t)export_name.len) == 0) {
            found = true;
            break;
        }
    }
    munmap((void *)source.ptr, (size_t)source.len);
    return found;
}

static bool cold_darwin_host_runtime_forced_symbol(const char *symbol) {
    return symbol && strcmp(symbol, "cheng_mkdir") == 0;
}

/* Symbols the real fixed-ABI C host-runtime provider object defines (compiled
 * by cc from cold_compile_host_runtime_c_provider_object). Besides f64 casts,
 * openat/syscall bridges live here because Darwin arm64 uses a distinct
 * variadic calling convention that a fixed Cheng @importc declaration cannot
 * legally impersonate. */
static bool cold_host_runtime_c_exported_symbol(const char *symbol) {
    if (!symbol) return false;
    return strcmp(symbol, "cheng_f64_to_i32") == 0 ||
           strcmp(symbol, "cheng_f64_to_i64") == 0 ||
           strcmp(symbol, "cheng_host_openat_fixed") == 0 ||
           strcmp(symbol, "cheng_host_getdents_fixed") == 0 ||
           strcmp(symbol, "cheng_host_renameat_noreplace_fixed") == 0;
}

static void cold_emit_linux_aarch64_write_provider(Code *code) {
    code_emit(code, a64_movz_x(R8, 64, 0));
    code_emit(code, a64_svc(0));
    code_emit(code, a64_ret());
}

static void cold_emit_linux_aarch64_get_nprocs_provider(Code *code) {
    code_emit(code, a64_sub_imm(SP, SP, 128, true));
    for (int32_t off = 0; off < 128; off += 8) {
        code_emit(code, a64_str_imm(31, SP, off, true));
    }
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_movz_x(R1, 128, 0));
    code_emit(code, a64_add_imm(R2, SP, 0, true));
    code_emit(code, a64_movz_x(R8, 123, 0));
    code_emit(code, a64_svc(0));
    code_emit(code, a64_cmp_reg_x(R0, 31));
    int32_t fail_lt = code->count;
    code_emit(code, a64_bcond(0, COND_LT));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movz_x(R1, 128, 0));
    code_emit(code, a64_movz_x(R2, 0, 0));
    code_emit(code, a64_movz(R4, 0, 0));
    code_emit(code, a64_movz(R7, 1, 0));

    int32_t byte_loop = code->count;
    code_emit(code, a64_cmp_reg_x(R2, R1));
    int32_t done_ge = code->count;
    code_emit(code, a64_bcond(0, COND_GE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_ldrb_reg(R3, SP, R2));
    int32_t bit_loop = code->count;
    code_emit(code, a64_cmp_imm(R3, 0));
    int32_t byte_done_eq = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_and_reg(R6, R3, R7));
    code_emit(code, a64_add_reg(R4, R4, R6));
    code_emit(code, a64_lsr_imm(R3, R3, 1, false));
    code_emit(code, a64_b(bit_loop - code->count));

    int32_t byte_done = code->count;
    a64_patch_bcond(code, byte_done_eq, byte_done);
    code_emit(code, a64_add_imm(R2, R2, 1, true));
    code_emit(code, a64_b(byte_loop - code->count));

    int32_t done = code->count;
    a64_patch_bcond(code, done_ge, done);
    code_emit(code, a64_cmp_imm(R4, 0));
    int32_t ret_zero_le = code->count;
    code_emit(code, a64_bcond(0, COND_LE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_add_imm(R0, R4, 0, false));
    int32_t ret_count_b = code->count;
    code_emit(code, a64_b(0));

    int32_t ret_zero = code->count;
    a64_patch_bcond(code, fail_lt, ret_zero);
    a64_patch_bcond(code, ret_zero_le, ret_zero);
    code_emit(code, a64_movz(R0, 0, 0));

    int32_t epilogue = code->count;
    a64_patch_b(code, ret_count_b, epilogue);
    code_emit(code, a64_add_imm(SP, SP, 128, true));
    code_emit(code, a64_ret());
}

