static void cold_emit_linux_aarch64_thread_start_provider(Code *code, int32_t initial_state) {
    code_emit(code, a64_orr_reg_x(R9, SP, R0));   /* fn */
    code_emit(code, a64_orr_reg_x(R10, SP, R1));  /* ctx */
    code_emit(code, a64_orr_reg_x(R11, SP, R3));  /* handle */
    code_emit(code, a64_str_imm(R2, R11, 0, true));  /* stackBase */
    code_emit(code, a64_str_imm(31, R11, 8, true));  /* cleanupStackBase */
    codegen_mov_i64_const(code, 14, 1048576);
    code_emit(code, a64_str_imm(14, R11, 16, true)); /* stackSize */
    code_emit(code, a64_str_imm(31, R11, 24, true));  /* cleanupStackSize */
    code_emit(code, a64_str_imm(31, R11, 32, false)); /* tidWord */
    code_emit(code, a64_str_imm(R9, R11, 40, true));  /* fn */
    code_emit(code, a64_str_imm(R10, R11, 48, true)); /* ctx */
    code_emit(code, a64_add_reg_x(R1, R2, 14));       /* child stack top */
    code_emit(code, a64_sub_imm(R1, R1, 16, true));
    code_emit(code, a64_str_imm(R11, R1, 0, true));   /* bootstrap handle */
    code_emit(code, a64_movz(14, (uint32_t)initial_state, 0));
    code_emit(code, a64_str_imm(14, R11, 36, false)); /* state */
    code_emit(code, a64_add_imm(R12, R11, 32, true)); /* &handle->tidWord */
    code_emit(code, a64_add_imm(13, R11, 36, true));  /* &handle->state */
    codegen_mov_i64_const(code, R0, 0x01350F00u); /* CLONE_* pthread-like flags */
    code_emit(code, a64_orr_reg_x(R2, SP, R12));  /* parent_tid */
    code_emit(code, a64_movz_x(R3, 0, 0));        /* tls */
    code_emit(code, a64_orr_reg_x(R4, SP, R12));  /* child_tid */
    code_emit(code, a64_movz_x(R8, 220, 0));      /* clone */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_cmp_reg_x(R0, SP));
    int32_t child_eq = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_ret());

    int32_t child = code->count;
    a64_patch_bcond(code, child_eq, child);
    code_emit(code, a64_ldr_imm(19, SP, 0, true));    /* child handle */
    code_emit(code, a64_ldr_imm(R9, 19, 40, true));   /* child fn */
    code_emit(code, a64_ldr_imm(R10, 19, 48, true));  /* child ctx */
    code_emit(code, a64_add_imm(20, 19, 32, true));   /* child-preserved &tidWord */
    code_emit(code, a64_add_imm(21, 19, 36, true));   /* child-preserved &state */
    code_emit(code, a64_orr_reg_x(R0, SP, R10));
    code_emit(code, a64_blr(R9));

    int32_t state_loop = code->count;
    code_emit(code, a64_ldaxr_w(14, 21));
    code_emit(code, a64_cmp_imm(14, 1));
    int32_t detached_eq = code->count;
    code_emit(code, a64_bcond(0, COND_EQ));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_cmp_imm(14, 0));
    int32_t state_done_ne = code->count;
    code_emit(code, a64_bcond(0, COND_NE));
    code_emit(code, a64_nop()); /* reserved veneer slot for a64_patch_bcond long-range escape */
    code_emit(code, a64_movz(14, 2, 0));
    code_emit(code, a64_stlxr_w(16, 14, 21));
    code_emit(code, a64_cbnz(16, state_loop - code->count));
    int32_t normal_exit_b = code->count;
    code_emit(code, a64_b(0));

    int32_t detached_cleanup = code->count;
    a64_patch_bcond(code, detached_eq, detached_cleanup);
    code_emit(code, a64_clrex());
    code_emit(code, a64_ldr_imm(22, 19, 0, true));    /* stackBase */
    code_emit(code, a64_ldr_imm(23, 19, 16, true));   /* stackSize */
    code_emit(code, a64_add_imm_shifted(SP, 19, 1, true));
    code_emit(code, a64_sub_imm(SP, SP, 16, true));   /* cleanup stack inside handle page */
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_movz_x(R8, 96, 0));           /* set_tid_address(NULL) */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_orr_reg_x(R0, SP, 22));
    code_emit(code, a64_orr_reg_x(R1, SP, 23));
    code_emit(code, a64_movz_x(R8, 215, 0));          /* munmap(stackBase, stackSize) */
    code_emit(code, a64_svc(0));
    code_emit(code, a64_orr_reg_x(R0, SP, 19));
    code_emit(code, a64_movz_x(R1, 4096, 0));
    code_emit(code, a64_movz_x(R8, 215, 0));          /* munmap(handle, page) */
    code_emit(code, a64_svc(0));
    int32_t detached_exit_b = code->count;
    code_emit(code, a64_b(0));

    int32_t normal_exit = code->count;
    a64_patch_bcond(code, state_done_ne, normal_exit);
    a64_patch_b(code, normal_exit_b, normal_exit);
    code_emit(code, a64_clrex());
    code_emit(code, a64_stlr_w(31, 20));
    code_emit(code, a64_orr_reg_x(R0, SP, 20));
    code_emit(code, a64_movz_x(R1, 129, 0));          /* FUTEX_WAKE_PRIVATE */
    code_emit(code, a64_movz_x(R2, 1, 0));
    code_emit(code, a64_movz_x(R3, 0, 0));
    code_emit(code, a64_movz_x(R4, 0, 0));
    code_emit(code, a64_movz_x(R5, 0, 0));
    code_emit(code, a64_movz_x(R8, 98, 0));           /* futex */
    code_emit(code, a64_svc(0));
    int32_t final_exit = code->count;
    a64_patch_b(code, detached_exit_b, final_exit);
    code_emit(code, a64_movz_x(R0, 0, 0));
    code_emit(code, a64_movz_x(R8, 93, 0));
    code_emit(code, a64_svc(0));
    code_emit(code, a64_b(0));
}

