    x64_push_r64(x, 12);       /* r12 = out */
    x64_push_r64(x, 13);       /* r13 = fn */
    x64_push_r64(x, 14);       /* r14 = arg */
    x64_push_r64(x, 15);       /* r15 = stack base */
    x64_mov_r64_r64(x, 12, 7);     /* r12 = out (rdi) */
    x64_mov_r64_r64(x, 13, 2);     /* r13 = fn (rdx) */
    x64_mov_r64_r64(x, 14, 1);     /* r14 = arg (rcx) */

    /* mmap(NULL, 16MB, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) */
    x64_xor_r64_r64(x, 7, 7);
    x64_mov_r32_imm32(x, 6, 16777216);
    x64_mov_r32_imm32(x, 2, 3);
    x64_mov_r32_imm32(x, 10, 0x22);
    x64_mov_r64_imm64(x, 8, (uint64_t)-1);
    x64_xor_r64_r64(x, 9, 9);
    x64_mov_r32_imm32(x, 0, 9);
