    x64_mov_r32_imm32(x, 6, 16777216);
    x64_mov_r32_imm32(x, 0, 11);
    x64_syscall(x);
    x64_mov_r32_imm32(x, 0, 11);       /* return EAGAIN */
    int32_t fail_stack_done = cold_x64_jmp_rel32_patch(x);
    cold_x64_patch_rel32_at(x, handle_ok, x->len);
    x64_mov_r64_r64(x, 3, 0);          /* rbx = handle */

