    x64_mov_mr64_imm32(x, 1, 8, 0);
    x64_mov_r32_imm32(x, 0, 16777216);             /* stackSize = 16MB */
    x64_mov_mr64_base_disp8_r64(x, 1, 16, 0);
    x64_mov_mr64_imm32(x, 1, 24, 0);
    x64_mov_mr32_imm32(x, 1, 32, 0);
