    x64_lea_r64_mr(x, 6, 2, 16777200);             /* child stack top */
    x64_mov_mr64_base_r64(x, 6, 1);                /* bootstrap handle */
    x64_lea_r64_mr(x, 2, 1, 32);                   /* parent_tid */
    x64_mov_r64_r64(x, 10, 2);                     /* child_tid */
    x64_xor_r64_r64(x, 8, 8);                      /* tls */
    x64_mov_r32_imm32(x, 7, 0x01350F00);
    x64_mov_r32_imm32(x, 0, 56);
