    x64_mov_r32_imm32(x, 0, 11);
    x64_syscall(x);
    x64_mov_r64_r64(x, 7, 15);                     /* munmap stack */
    x64_mov_r32_imm32(x, 6, 16777216);
    x64_mov_r32_imm32(x, 0, 11);
    x64_syscall(x);
    x64_mov_r32_imm32(x, 0, 11);                   /* return EAGAIN */
    int32_t clone_fail_done = cold_x64_jmp_rel32_patch(x);

