    x64_mov_r64_mr64_base(x, 0, 4);
    x64_sub_rsp_imm32(x, 32);
    x64_mov_mr64_r64(x, 4, 0, 0);
    x64_mov_r64_mr64_base_disp8(x, 9, 0, 40);
    x64_mov_r64_mr64_base_disp8(x, 7, 0, 48);
    x64_call_reg(x, 9);
    x64_mov_r64_mr64(x, 3, 4, 0);
    x64_add_rsp_imm32(x, 32);
    x64_lea_r64_mr(x, 13, 3, 36);

    int32_t state_loop = x->len;
