    x64_lea_r64_mr(x, 4, 3, 4080);
    x64_xor_r64_r64(x, 7, 7);
    x64_mov_r32_imm32(x, 0, 218);
    x64_syscall(x);
    x64_mov_r64_r64(x, 7, 14);
    x64_mov_r64_r64(x, 6, 15);
    x64_mov_r32_imm32(x, 0, 11);
    x64_syscall(x);
    x64_mov_r64_r64(x, 7, 3);
    x64_mov_r32_imm32(x, 6, 4096);
    x64_mov_r32_imm32(x, 0, 11);
    x64_syscall(x);
    int32_t final_exit_detached = cold_x64_jmp_rel32_patch(x);

    int32_t normal_exit = x->len;
    cold_x64_patch_rel32_at(x, normal_not_zero, normal_exit);
    cold_x64_patch_rel32_at(x, normal, normal_exit);
    x64_lea_r64_mr(x, 12, 3, 32);
    x64_mov_mr32_imm32(x, 12, 0, 0);
    x64_mov_r64_r64(x, 7, 12);
    x64_mov_r32_imm32(x, 6, 129);
    x64_mov_r32_imm32(x, 2, 1);
    x64_xor_r64_r64(x, 10, 10);
    x64_xor_r64_r64(x, 8, 8);
    x64_xor_r64_r64(x, 9, 9);
    x64_mov_r32_imm32(x, 0, 202);
