/* usleep(edi = microseconds) via nanosleep. */
static void cold_emit_linux_x86_64_usleep_provider(X64Code *x) {
    x64_mov_r32_r32(x, 0, 7);
    x64_xor_r32_r32(x, 2, 2);
    x64_mov_r32_imm32(x, 1, 1000000);
    x64_emit1(x, 0xF7); x64_emit1(x, MODRM(3, 6, 1));   /* div ecx */
    x64_sub_rsp_imm32(x, 16);
    x64_mov_mr64_r64(x, 4, 0, 0);                       /* tv_sec */
    x64_mov_r32_imm32(x, 1, 1000);
    x64_imul_r32_r32(x, 2, 1);
    x64_mov_mr64_r64(x, 4, 8, 2);                       /* tv_nsec */
    x64_mov_r64_r64(x, 7, 4);
    x64_xor_r32_r32(x, 6, 6);
    x64_mov_r32_imm32(x, 0, 35);                        /* nanosleep */
    x64_syscall(x);
    x64_add_rsp_imm32(x, 16);
    x64_xor_r32_r32(x, 0, 0);
    x64_ret(x);
}

static void cold_emit_linux_x86_64_host_syscall_tail(X64Code *x,
                                                      int32_t syscall_nr,
                                                      int32_t argc) {
    x64_mov_r32_imm32(x, 0, syscall_nr);
    if (argc >= 4) x64_mov_r64_r64(x, 10, 1);
    x64_syscall(x);
    x64_test_r64_r64(x, 0, 0);
    int32_t success = cold_x64_jcc_rel32_patch(x, CC_GE);
    x64_mov_r64_imm64(x, 0, (uint64_t)-1LL);
    cold_x64_patch_rel32_at(x, success, x->len);
    x64_ret(x);
}

static void cold_emit_linux_x86_64_renameat_noreplace_provider(X64Code *x) {
    x64_mov_r64_r64(x, 10, 2);
    x64_mov_r64_r64(x, 2, 7);
    x64_mov_r32_imm32(x, 8, 1);
    cold_emit_linux_x86_64_host_syscall_tail(x, 316, 3);
}

