    offsets[RUNTIME_ATOMIC_ADD_INDEX] = x.len;
    cold_emit_linux_x86_64_atomic_add_i32_provider(&x);
    offsets[THREAD_START_DETACHED_INDEX] = x.len;
    cold_emit_linux_x86_64_thread_start_provider(&x, 1);
    offsets[THREAD_START_JOINABLE_INDEX] = x.len;
    cold_emit_linux_x86_64_thread_start_provider(&x, 0);
