#define WASM_OP_I64_LOAD8_U  0x31
#define WASM_OP_I64_LOAD16_U 0x33
#define WASM_OP_I64_LOAD32_U 0x35

/* I64 store variants */
#define WASM_OP_I64_STORE8   0x3C
#define WASM_OP_I64_STORE16  0x3D
#define WASM_OP_I64_STORE32  0x3E

/* Stack and comparison */
#define WASM_OP_DROP      0x1A
#define WASM_OP_I32_MIN   0x6C
#define WASM_OP_I32_MAX   0x6D

/* Float arithmetic */
#define WASM_OP_F32_ADD    0x92
#define WASM_OP_F32_SUB    0x93
#define WASM_OP_F32_MUL    0x94
#define WASM_OP_F32_DIV    0x95
