        for (int32_t ai = 0; ai < c; ai++) {
            int32_t arg_slot = body->call_arg_slot[b + ai];
            wasm_op_local_get(wasm, (uint32_t)wasm_local_for_slot(body, arg_slot));
        }
        wasm_op_call(wasm, (uint32_t)wf);
