        la = wasm_local_for_slot(body, a);
        lb = wasm_local_for_slot(body, b);
        ld = wasm_local_for_slot(body, dst);
        wasm_op_local_get(wasm, (uint32_t)la);
        wasm_op_local_get(wasm, (uint32_t)lb);
