        wasm_op_local_get(wasm, (uint32_t)la);
        wasm_op_i32_const(wasm, 4);
        wasm_emit1(wasm, WASM_OP_I32_ADD);
        wasm_emit1(wasm, WASM_OP_I32_LOAD);
        wasm_emit_leb128_u(wasm, 2);
        wasm_emit_leb128_u(wasm, 0);
