        wasm_emit1(wasm, WASM_OP_I32_SHR_U);
        wasm_op_memory_grow(wasm);
        wasm_op_i32_const(wasm, 16);
        wasm_emit1(wasm, WASM_OP_I32_SHL);
        wasm_op_local_tee(wasm, (uint32_t)tmp_local); /* ptr in tmp_local */
