        wasm_emit1(wasm, WASM_OP_I32_ADD);
        wasm_op_local_set(wasm, (uint32_t)SCR_LEN_IS);
        wasm_emit1(wasm, WASM_OP_BR);
        wasm_emit_leb128_u(wasm, 0);
        wasm_emit1(wasm, WASM_OP_END);
        wasm_emit1(wasm, WASM_OP_END);
