        wasm_op_local_get(wasm, (uint32_t)la);
        wasm_op_i32_const(wasm, 0);
        wasm_emit1(wasm, WASM_OP_I32_LT_S);
        wasm_emit1(wasm, WASM_OP_IF);
        wasm_emit1(wasm, WASM_BLOCK_TYPE_EMPTY);
