        wasm_op_i32_const(wasm, 8);
        wasm_emit1(wasm, WASM_OP_I32_ADD);
        wasm_op_local_get(wasm, SCR_J_TC);
        wasm_emit1(wasm, WASM_OP_I32_ADD);
