static bool cold_write_binary_hex_sidecar(const char *path, char *error_buf, size_t error_cap) {
    if (!path || path[0] == '\0') {
        snprintf(error_buf, error_cap, "hex sidecar input path missing");
        return false;
    }
    char hex_path[PATH_MAX];
    int n = snprintf(hex_path, sizeof(hex_path), "%s.hex", path);
    if (n <= 0 || n >= (int)sizeof(hex_path)) {
        snprintf(error_buf, error_cap, "hex sidecar path too long");
        return false;
    }
    FILE *in = fopen(path, "rb");
    if (!in) {
        snprintf(error_buf, error_cap, "hex sidecar input open failed");
        return false;
    }
    FILE *out = fopen(hex_path, "wb");
    if (!out) {
        fclose(in);
        snprintf(error_buf, error_cap, "hex sidecar output open failed");
        return false;
    }
    static const char hex[] = "0123456789abcdef";
    int ch;
    while ((ch = fgetc(in)) != EOF) {
        uint8_t byte = (uint8_t)ch;
        fputc(hex[(byte >> 4) & 0xF], out);
        fputc(hex[byte & 0xF], out);
    }
    bool ok = ferror(in) == 0 && ferror(out) == 0;
    fclose(in);
    if (fclose(out) != 0) ok = false;
    if (!ok) {
        snprintf(error_buf, error_cap, "hex sidecar write failed");
        unlink(hex_path);
        return false;
    }
    return true;
}

